        self.camera_step_rotation_y_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_placement_offset_xyz = (0.0, 0.0, 0.0)
