    def rotate_camera_step_z(self, delta_deg: float) -> None:
        self.rotate_step_z("camera", delta_deg)

    def import_led_step(self, dialog_parent: tk.Misc | None = None) -> Path | None:
        initial_dir = DEFAULT_LED_STEP_PATH if DEFAULT_LED_STEP_PATH.is_dir() else DEFAULT_LED_STEP_PATH.parent
        path = self._ask_step_file("Import LED STEP", initial_dir, parent=dialog_parent)
        if path is None:
            return None
        initial_distance = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        if initial_distance <= 0.0:
            initial_distance = self._default_led_object_edge_distance()
        edge_distance = self._ask_led_edge_distance(initial_distance, parent=dialog_parent)
        if edge_distance is None:
            self.status_var.set("LED STEP import cancelled.")
            return None
        self._begin_history_capture()
        self.imported_led_step_path = path
        self.led_step_rotation_x_deg = 0.0
        self.led_step_rotation_y_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_step_object_edge_local_z = None
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self._selected_step_label = "led"
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self.led_object_edge_distance_mm = float(edge_distance)
        self._commit_history_capture()
        self.status_var.set(
            f"LED STEP imported: {path.name}; edge distance={self.led_object_edge_distance_mm:.3g} mm."
        )
        self._refresh_open_3d_views(step_label="led")
        return path

    def _default_led_object_edge_distance(self) -> float:
        lens_front_z = max(float(self._lens_front_datum_z()), 0.0)
        if lens_front_z <= 1e-9:
            return 0.0
        return max(0.0, min(lens_front_z * 0.25, lens_front_z - 1.0))

    def set_led_edge_distance(self) -> None:
        current = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        if current <= 0.0:
            current = self._default_led_object_edge_distance()
        value = self._ask_led_edge_distance(current)
        if value is None:
            return
        self._begin_history_capture()
        self.led_object_edge_distance_mm = float(value)
        self._commit_history_capture()
        self.status_var.set(f"LED edge distance: {self.led_object_edge_distance_mm:.3g} mm")
        self._refresh_open_3d_views(step_label="led")

    def _ask_led_edge_distance(self, initial_value: float, *, parent: tk.Misc | None = None) -> float | None:
        value_var = tk.StringVar(value=f"{max(float(initial_value), 0.0):g}")
        value_holder: dict[str, float] = {}

        dialog_parent = parent or self
        dialog = tk.Toplevel(dialog_parent)
        dialog.withdraw()
        dialog.title("LED Edge Distance")
        dialog.transient(dialog_parent)
        dialog.grab_set()
        dialog.resizable(False, False)

        ttk.Label(
            dialog,
            text="Distance from object plane to the object-side LED box edge [mm]",
        ).grid(row=0, column=0, columnspan=2, padx=12, pady=(12, 6), sticky="w")
        entry = ttk.Entry(dialog, textvariable=value_var, width=18)
        entry.grid(row=1, column=0, columnspan=2, padx=12, pady=(0, 12), sticky="ew")

        def accept() -> None:
            try:
                value_holder["value"] = max(float(value_var.get()), 0.0)
            except ValueError:
                self.status_var.set("Invalid LED edge distance.")
                return
            dialog.destroy()

        ttk.Button(dialog, text="Save", command=accept).grid(row=2, column=0, padx=(12, 4), pady=(0, 12), sticky="e")
        ttk.Button(dialog, text="Cancel", command=dialog.destroy).grid(row=2, column=1, padx=(4, 12), pady=(0, 12), sticky="w")
        dialog.bind("<Return>", lambda _event: accept())
        dialog.bind("<Escape>", lambda _event: dialog.destroy())
        self._show_centered_dialog(dialog)
        entry.focus_set()
        self.wait_window(dialog)

        value = value_holder.get("value")
        return float(value) if value is not None else None

    def rotate_led_step_z(self, delta_deg: float) -> None:
        self.rotate_step_z("led", delta_deg)

    def start_led_object_edge_pick(self) -> None:
        if self.imported_led_step_path is None:
            self.status_var.set("No LED STEP is imported.")
            return
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = True
        self._selected_step_label = "led"
        message = "Pick the LED body edge used for Object-to-LED distance."
        self.status_var.set(message)
        if self._three_d_inspector is not None:
            try:
                self._three_d_inspector.status_var.set(message)
                self._three_d_inspector._set_axis_pick_cursor(True)
                self._three_d_inspector._update_mode_badge()
            except Exception:
                pass

    def _led_step_z_translation(self) -> float:
        target_edge_z = max(float(getattr(self, "led_object_edge_distance_mm", 0.0)), 0.0)
        reference_z = getattr(self, "led_step_object_edge_local_z", None)
        if reference_z is None:
            return target_edge_z
        try:
            return target_edge_z - float(reference_z)
        except Exception:
            return target_edge_z

    def apply_led_object_edge_pick(self, feature_center_xyz: np.ndarray) -> None:
        feature_center = np.asarray(feature_center_xyz, dtype=float)
        if feature_center.size < 3 or not np.all(np.isfinite(feature_center[:3])):
            self.status_var.set("Invalid LED object-edge pick.")
            return
        # Store the picked edge in the LED's transformed local Z frame. Future
        # placement shifts the whole STEP so this edge, not a cable extremum,
        # lands at the Object-to-LED distance.
        local_z = float(feature_center[2]) - self._led_step_z_translation()
        self._begin_history_capture()
        self.led_step_object_edge_local_z = local_z
        self._cad_led_object_edge_pick = False
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._selected_step_label = "led"
        self._commit_history_capture()
        self.status_var.set(
            f"LED object edge locked. Local Z={local_z:.3g} mm; "
            f"edge distance={self.led_object_edge_distance_mm:.3g} mm."
        )
        self._refresh_open_3d_views(step_label="led")

    def _step_overlay_display_label(self, label: str) -> str:
        label = str(label).strip().lower()
        if label == "lens" and not bool(getattr(self, "lens_step_largest_component_only", True)):
            return "Optical"
        return {
            "lens": "Lens",
            "optical": "Optical",
            "led": "LED",
            "camera": "Camera",
        }.get(label, "STEP")

    def _step_path_for_label(self, label: str) -> Path | None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        return {
            "lens": self.imported_lens_step_path,
            "optical": self.imported_optical_step_path,
            "led": self.imported_led_step_path,
            "camera": self.imported_camera_step_path,
        }.get(label)

    def _clear_imported_step_overlay_state(self, label: str) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        path_attrs = {
            "lens": "imported_lens_step_path",
            "optical": "imported_optical_step_path",
            "led": "imported_led_step_path",
            "camera": "imported_camera_step_path",
        }
        path_attr = path_attrs.get(label)
        if path_attr:
            setattr(self, path_attr, None)
        for axis in ("x", "y", "z"):
            attr = f"{label}_step_rotation_{axis}_deg"
            if hasattr(self, attr):
                setattr(self, attr, 0.0)
        axis_attr = f"{label}_step_axis_offset_xy"
        if hasattr(self, axis_attr):
            setattr(self, axis_attr, (0.0, 0.0))
        placement_attr = f"{label}_step_placement_offset_xyz"
        if hasattr(self, placement_attr):
            setattr(self, placement_attr, (0.0, 0.0, 0.0))
        if label == "led":
            self.led_object_edge_distance_mm = 0.0
            self.led_step_object_edge_local_z = None
        if label == "lens":
            self.lens_step_largest_component_only = True
        if self._selected_step_label == label:
            self._selected_step_label = None

    def rotate_step_axis(self, label: str, axis: str, delta_deg: float) -> None:
        label = str(label).strip().lower()
        axis = str(axis).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET or axis not in {"x", "y", "z"}:
            return
        path = self._step_path_for_label(label)
        if path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        attr = f"{label}_step_rotation_{axis}_deg"
        self._begin_history_capture()
        current = float(getattr(self, attr, 0.0))
        next_angle = float((current + float(delta_deg)) % 360.0)
        setattr(self, attr, next_angle)
        self._selected_step_label = label
        self._commit_history_capture()
        self.status_var.set(f"{label.upper()} STEP {axis.upper()} rotation: {next_angle:.0f} deg")
        self._refresh_open_3d_views(step_label=label)

    def rotate_selected_step_axis(self, axis: str, delta_deg: float) -> None:
        label = self._selected_step_label
        if label not in STEP_OVERLAY_LABEL_SET:
            self.status_var.set("Select a STEP component in the 3D view first.")
            return
        self.rotate_step_axis(label, axis, delta_deg)

    def rotate_step_z(self, label: str, delta_deg: float) -> None:
        self.rotate_step_axis(label, "z", delta_deg)

    def rotate_selected_step_z(self, delta_deg: float) -> None:
        self.rotate_selected_step_axis("z", delta_deg)

    def rotate_step_x(self, label: str, delta_deg: float) -> None:
        self.rotate_step_axis(label, "x", delta_deg)

    def rotate_selected_step_x(self, delta_deg: float) -> None:
        self.rotate_selected_step_axis("x", delta_deg)

    def rotate_step_y(self, label: str, delta_deg: float) -> None:
        self.rotate_step_axis(label, "y", delta_deg)

    def rotate_selected_step_y(self, delta_deg: float) -> None:
        self.rotate_selected_step_axis("y", delta_deg)

    def select_step_component(self, label: str) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        self._selected_step_label = label
        self.status_var.set(
            f"Selected {label.upper()} STEP. Drag freely in Open 3D, click a face, then use Snap STEP Normal->Optical Axis."
        )

    def start_any_step_axis_pick(self) -> None:
        if not self._has_imported_step_cad():
            self.status_var.set("No lens, optical, LED, or camera STEP is imported.")
            return
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = True
        self._cad_led_object_edge_pick = False
        selected = self._selected_step_label if self._step_path_for_label(str(self._selected_step_label or "")) is not None else None
        target_note = (
            f" Selected {str(selected).upper()} STEP can also be centered on a KrakenOS surface."
            if selected is not None
            else " Select a STEP first if you want to center it on a KrakenOS surface."
        )
        message = (
            "Center STEP Axis: click a planar/circular outer feature on any imported STEP; "
            "the picked feature center will move to the optical axis." + target_note
        )
        self.status_var.set(message)
        if self._three_d_inspector is not None:
            try:
                self._three_d_inspector.status_var.set(message)
                self._three_d_inspector._set_axis_pick_cursor(True)
                self._three_d_inspector._update_mode_badge()
            except Exception:
                pass

    def start_step_axis_pick(self, label: str) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        path = self._step_path_for_label(label)
        if path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        self._cad_axis_pick_label = label
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._selected_step_label = label
        message = (
            f"Pick a planar/circular feature on the {label} STEP to define its optical axis, "
            "or click a KrakenOS surface to center that STEP axis on the surface axis."
        )
        self.status_var.set(message)
        if self._three_d_inspector is not None:
            try:
                self._three_d_inspector.status_var.set(message)
                self._three_d_inspector._set_axis_pick_cursor(True)
                self._three_d_inspector._update_mode_badge()
            except Exception:
                pass

    def _step_axis_offset_xy(self, label: str) -> tuple[float, float]:
        value = getattr(self, f"{label}_step_axis_offset_xy", (0.0, 0.0))
        try:
            return (float(value[0]), float(value[1]))
        except Exception:
            return (0.0, 0.0)

    def _set_step_axis_offset_xy(self, label: str, offset_xy: tuple[float, float]) -> None:
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        setattr(self, f"{label}_step_axis_offset_xy", (float(offset_xy[0]), float(offset_xy[1])))

    def _step_placement_offset_xyz(self, label: str) -> tuple[float, float, float]:
        value = getattr(self, f"{label}_step_placement_offset_xyz", (0.0, 0.0, 0.0))
        try:
            return (float(value[0]), float(value[1]), float(value[2]))
        except Exception:
            return (0.0, 0.0, 0.0)

    def _set_step_placement_offset_xyz(self, label: str, offset_xyz) -> None:
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        values = np.asarray(offset_xyz, dtype=float).reshape(-1)
        if values.size < 3 or not np.all(np.isfinite(values[:3])):
            return
        setattr(self, f"{label}_step_placement_offset_xyz", (float(values[0]), float(values[1]), float(values[2])))

    def translate_step_overlay(
        self,
        label: str,
        delta_xyz,
        *,
        grid_spacing_mm: float | None = None,
        refresh: bool = True,
        record_history: bool = True,
    ) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        if self._step_path_for_label(label) is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return
        delta = np.asarray(delta_xyz, dtype=float).reshape(-1)
        if delta.size < 3 or not np.all(np.isfinite(delta[:3])):
            self.status_var.set(f"Invalid {label} STEP placement delta.")
            return
        current = np.asarray(self._step_placement_offset_xyz(label), dtype=float)
        next_offset = current + delta[:3]
        if record_history:
            self._begin_history_capture()
        self._set_step_placement_offset_xyz(label, next_offset)
        self._selected_step_label = label
        if record_history:
            self._commit_history_capture()
        step_text = f" on {float(grid_spacing_mm):.6g} mm snap step" if grid_spacing_mm is not None else ""
        self.status_var.set(
            f"{label.upper()} STEP moved{step_text}: "
            f"d=({float(delta[0]):.6g}, {float(delta[1]):.6g}, {float(delta[2]):.6g}) mm; "
            f"offset=({float(next_offset[0]):.6g}, {float(next_offset[1]):.6g}, {float(next_offset[2]):.6g}) mm."
        )
        if refresh:
            self._refresh_open_3d_views(step_label=label)

    def _transformed_imported_step_mesh_for_label(self, label: str):
        label = str(label).strip().lower()
        builders = {
            "lens": self._transformed_imported_lens_step_mesh,
            "optical": self._transformed_imported_optical_step_mesh,
            "camera": self._transformed_imported_camera_step_mesh,
            "led": self._transformed_imported_led_step_mesh,
        }
        builder = builders.get(label)
        return builder() if builder is not None else None

    def promote_imported_step_to_optical_solid_row(
        self,
        label: str,
        *,
        insert_at: int | None = None,
        open_face_editor: bool = True,
        clear_overlay: bool = False,
        refresh_open_3d: bool = True,
    ) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        source_path = self._step_path_for_label(label)
        if source_path is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return None
        mesh = self._transformed_imported_step_mesh_for_label(label)
        if mesh is None or int(getattr(mesh, "n_points", 0)) <= 0:
            self.status_var.set(f"{label.upper()} STEP mesh unavailable for optical-solid promotion.")
            return None
        try:
            mesh = mesh.extract_surface(algorithm="dataset_surface").triangulate().copy(deep=True)
        except Exception:
            try:
                mesh = mesh.extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                mesh = mesh.copy(deep=True)
        points = np.asarray(getattr(mesh, "points", np.empty((0, 3))), dtype=float)
        if points.ndim != 2 or points.shape[0] == 0 or points.shape[1] < 3 or not np.all(np.isfinite(points[:, :3])):
            self.status_var.set(f"{label.upper()} STEP promotion found no finite mesh points.")
            return None
        bounds_min = np.min(points[:, :3], axis=0)
        bounds_max = np.max(points[:, :3], axis=0)
        center_world = 0.5 * (bounds_min + bounds_max)
        extents = np.maximum(bounds_max - bounds_min, 0.0)
        local_mesh = mesh.copy(deep=True)
        local_mesh.points = points[:, :3] - center_world[:3]

        digest = hashlib.sha1()
        digest.update(str(source_path.resolve()).encode("utf-8", errors="ignore"))
        digest.update(str(label).encode("utf-8"))
        digest.update(np.ascontiguousarray(local_mesh.points, dtype=np.float64).tobytes())
        digest.update(
            repr(
                {
                    "rot_x": self._step_x_rotation_deg(label),
                    "rot_y": self._step_y_rotation_deg(label),
                    "rot_z": self._step_roll_deg(label),
                    "axis_offset_xy": self._step_axis_offset_xy(label),
                    "placement_offset_xyz": self._step_placement_offset_xyz(label),
                    "largest_component_only": bool(getattr(self, "lens_step_largest_component_only", True))
                    if label == "lens"
                    else None,
                }
            ).encode("utf-8")
        )
        promoted_path = CAD_CACHE_DIR / "promoted_step_overlays" / f"{label}_{digest.hexdigest()[:16]}.stl"
        if not promoted_path.exists() or promoted_path.stat().st_size <= 0:
            promoted_path.parent.mkdir(parents=True, exist_ok=True)
            local_mesh.save(str(promoted_path))
        diagnostics = inspect_stl_mesh(promoted_path)

        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            raise RuntimeError(f"Could not read the surface table: {exc}") from exc

        if insert_at is None:
            selected_indices = self._selected_table_indices()
            arm_key = self._current_arm_view_key()
            if selected_indices:
                resolved_insert_at = max(selected_indices) + 1
            elif arm_key:
                resolved_insert_at = self._default_insert_index_for_arm_key(arm_key)
            else:
                resolved_insert_at = len(self.rows)
                if self.rows and self.rows[-1].surface == "Image":
                    resolved_insert_at -= 1
        else:
            resolved_insert_at = int(insert_at)
            arm_key = self._current_arm_view_key()
        resolved_insert_at = max(
            1,
            min(resolved_insert_at, len(self.rows) - (1 if self.rows and self.rows[-1].surface == "Image" else 0)),
        )
        z_station = float(sum(float(getattr(row, "thickness", 0.0) or 0.0) for row in self.rows[:resolved_insert_at]))

        row = self._optical_stl_solid_row(
            promoted_path.resolve(),
            source_path=source_path.resolve(),
            source_format="STEP",
        )
        if arm_key:
            self._apply_arm_key_metadata_to_row(row, arm_key)
        span = float(max(float(np.max(extents)), 1.0))
        display_label = self._step_overlay_display_label(label)
        row.element = f"{display_label.upper()} STEP solid"
        row.name = f"Promoted {display_label.upper()} STEP optical solid"
        row.thickness = 0.0
        row.diameter = span
        row.tilt_x = 0.0
        row.tilt_y = 0.0
        row.tilt_z = 0.0
        row.desp_x = float(center_world[0])
        row.desp_y = float(center_world[1])
        row.desp_z = float(center_world[2] - z_station)
        row.axis_move = 2.0
        row.advanced = dict(row.advanced or {})
        row.advanced["Note"] = (
            "Promoted from an Open 3D imported STEP overlay. The cached Solid_3d_stl mesh is saved "
            "in local coordinates around the overlay center, while row Desp stores the scene/world "
            "center. Review material and CAD/STL optical face roles before relying on traced physics."
        )
        row.advanced["StepOverlayPromotion"] = {
            "step_label": label,
            "source_step_path": str(source_path.resolve()),
            "promoted_mesh_path": str(promoted_path.resolve()),
            "mesh_coordinates": "local_centered_from_open3d_overlay",
            "center_world": [float(value) for value in center_world[:3]],
            "bounds_min_world": [float(value) for value in bounds_min[:3]],
            "bounds_max_world": [float(value) for value in bounds_max[:3]],
            "step_rotation_deg": [
                float(self._step_x_rotation_deg(label)),
                float(self._step_y_rotation_deg(label)),
                float(self._step_roll_deg(label)),
            ],
            "axis_offset_xy": [float(value) for value in self._step_axis_offset_xy(label)],
            "placement_offset_xyz": [float(value) for value in self._step_placement_offset_xyz(label)],
            "largest_component_only": bool(getattr(self, "lens_step_largest_component_only", True))
            if label == "lens"
            else None,
        }
        placement = normalize_scene_placement_settings(
            {
                "enabled": True,
                "anchor": "row_pose",
                "snap_enabled": True,
                "snap_mm": max(span / 20.0, 0.1),
                "snap_deg": 5.0,
                "grid_visible": True,
                "grid_spacing_mm": max(span / 10.0, 0.5),
                "grid_extent_mm": max(span * 2.0, 25.0),
                "promotion_source": "open3d_step_overlay",
                "promotion_step_label": label,
                "promotion_source_step_path": str(source_path.resolve()),
                "promotion_mesh_coordinates": "local_centered_from_open3d_overlay",
            }
        )
        row.advanced[SCENE_PLACEMENT_ADVANCED_ATTR] = placement

        self._begin_history_capture()
        self.rows.insert(resolved_insert_at, row)
        if clear_overlay:
            self._clear_imported_step_overlay_state(label)
        self._normalize_special_rows()
        self._sync_table()
        self._select_table_indices([resolved_insert_at], focus_index=resolved_insert_at)
        self._commit_history_capture()
        self._mark_plot_update_pending()
        self.append_debug(
            "Promoted {label} STEP overlay to optical solid S{row}: center=({x:.6g},{y:.6g},{z:.6g}) "
            "mesh={mesh}\n{diag}".format(
                label=label.upper(),
                row=int(resolved_insert_at),
                x=float(center_world[0]),
                y=float(center_world[1]),
                z=float(center_world[2]),
                mesh=promoted_path,
                diag=format_stl_mesh_diagnostics(diagnostics),
            )
        )
        if diagnostics.errors or diagnostics.warnings:
            self.status_var.set(
                f"Promoted {label.upper()} STEP to S{resolved_insert_at}; mesh diagnostics need review "
                f"({short_stl_mesh_diagnostics(diagnostics)})."
            )
        else:
            self.status_var.set(
                f"Promoted {label.upper()} STEP to optical solid row S{resolved_insert_at}. Assign faces/material, then Update."
            )
        if refresh_open_3d:
            self._refresh_open_3d_views()
        if open_face_editor:
            self.after(120, lambda idx=resolved_insert_at: self.open_optical_solid_face_role_editor(idx))
        return {
            "label": label,
            "row_index": int(resolved_insert_at),
            "mesh_path": str(promoted_path.resolve()),
            "source_step_path": str(source_path.resolve()),
            "center_world": tuple(float(value) for value in center_world[:3]),
            "diagnostics": diagnostics,
        }

    def snap_step_overlay_center_to_world_point(
        self,
        label: str,
        target_world_xyz,
        *,
        target_kind: str = "ray",
    ) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        if self._step_path_for_label(label) is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return None
        target = np.asarray(target_world_xyz, dtype=float).reshape(-1)
        if target.size < 3 or not np.all(np.isfinite(target[:3])):
            self.status_var.set(f"Invalid {label} STEP snap target.")
            return None
        mesh = self._transformed_imported_step_mesh_for_label(label)
        if mesh is None or int(getattr(mesh, "n_points", 0)) <= 0:
            self.status_var.set(f"{label.upper()} STEP mesh unavailable for snap.")
            return None
        try:
            bounds = np.asarray(mesh.bounds, dtype=float).reshape(6)
            center = np.asarray(
                (
                    0.5 * (float(bounds[0]) + float(bounds[1])),
                    0.5 * (float(bounds[2]) + float(bounds[3])),
                    0.5 * (float(bounds[4]) + float(bounds[5])),
                ),
                dtype=float,
            )
        except Exception:
            try:
                center = np.mean(np.asarray(mesh.points, dtype=float), axis=0)
            except Exception:
                center = np.zeros(3, dtype=float)
        if center.size < 3 or not np.all(np.isfinite(center[:3])):
            self.status_var.set(f"{label.upper()} STEP center unavailable for snap.")
            return None
        delta = target[:3] - center[:3]
        self.translate_step_overlay(label, delta, grid_spacing_mm=None)
        offset = self._step_placement_offset_xyz(label)
        result = {
            "label": label,
            "target_kind": str(target_kind or "target"),
            "target": tuple(float(value) for value in target[:3]),
            "previous_center": tuple(float(value) for value in center[:3]),
            "delta": tuple(float(value) for value in delta[:3]),
            "offset": offset,
        }
        self.status_var.set(
            "{label} STEP center snapped to {kind} at ({x:.6g}, {y:.6g}, {z:.6g}) mm; "
            "offset=({ox:.6g}, {oy:.6g}, {oz:.6g}) mm.".format(
                label=label.upper(),
                kind=str(target_kind or "target"),
                x=float(target[0]),
                y=float(target[1]),
                z=float(target[2]),
                ox=float(offset[0]),
                oy=float(offset[1]),
                oz=float(offset[2]),
            )
        )
        return result

    def snap_step_overlay_center_to_scene_target(
        self,
        label: str,
        row_index: int,
        *,
        face_id: str = "",
        system=None,
    ) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        if self._step_path_for_label(label) is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return None
        try:
            row_index = int(row_index)
        except Exception:
            self.status_var.set("Snap STEP->Target row is invalid.")
            return None
        if not (0 <= row_index < len(self.rows)):
            self.status_var.set("Snap STEP->Target row is out of range.")
            return None

        face_id = str(face_id or "").strip()
        target_kind = "scene target"
        target_label = f"S{row_index}"
        if face_id:
            face = self._scene_source_face_anchor_record(row_index, face_id)
            if face is None:
                self.status_var.set(f"Snap STEP->Target face {face_id} is unavailable on S{row_index}.")
                return None
            try:
                target = self._surface_reference_world_point(row_index, face_id=face_id, system=system)
            except Exception as exc:
                self.status_var.set(f"Snap STEP->Target face anchor unavailable: {_short_error_message(exc)}")
                return None
            target_kind = "CAD/STL face anchor"
            target_label = f"S{row_index} face {_optical_solid_face_marker_label(face)} [{face_id}]"
        else:
            try:
                trace_state = self._resolved_trace_mode(system=system or getattr(self, "last_system", None))
            except Exception:
                trace_state = {}
            scene_targets = self._scene_targets_for_graph(trace_state)
            target_record = next(
                (
                    target_item
                    for target_item in scene_targets
                    if int(getattr(target_item, "row_index", -1)) == row_index
                ),
                None,
            )
            if target_record is not None:
                target = np.asarray(getattr(target_record, "center_world", (np.nan, np.nan, np.nan)), dtype=float).reshape(-1)[:3]
                role = str(getattr(target_record, "role", "") or "scene target").replace("_", " ")
                name = str(getattr(target_record, "name", "") or self.rows[row_index].name or self.rows[row_index].surface or "").strip()
                target_kind = role
                target_label = f"{role} S{row_index}{f': {name}' if name else ''}"
            elif self._file_backed_stl_row_at(row_index) is not None:
                try:
                    target = self._surface_reference_world_point(row_index, system=system)
                except Exception as exc:
                    self.status_var.set(f"Snap STEP->Target CAD/STL center unavailable: {_short_error_message(exc)}")
                    return None
                row = self.rows[row_index]
                name = str(row.name or row.surface or "").strip()
                target_kind = "CAD/STL center"
                target_label = f"S{row_index} CAD/STL center{f': {name}' if name else ''}"
            else:
                self.status_var.set(
                    "Snap STEP->Target needs a detector/object/active target row or CAD/STL face anchor."
                )
                return None

        target = np.asarray(target, dtype=float).reshape(-1)
        if target.size < 3 or not np.all(np.isfinite(target[:3])):
            self.status_var.set(f"Snap STEP->Target resolved a non-finite target for S{row_index}.")
            return None
        result = self.snap_step_overlay_center_to_world_point(label, target[:3], target_kind=target_kind)
        if result is None:
            return None
        result["target_row_index"] = row_index
        result["target_face_id"] = face_id
        result["target_label"] = target_label
        return result

    def _step_offset_delta_for_world_xy(self, label: str, world_xy) -> tuple[float, float]:
        values = np.asarray(world_xy, dtype=float).reshape(-1)
        if values.size < 2 or not np.all(np.isfinite(values[:2])):
            return (0.0, 0.0)
        angle = np.deg2rad(-self._step_roll_deg(str(label).strip().lower()))
        cos_a = float(np.cos(angle))
        sin_a = float(np.sin(angle))
        x = float(values[0])
        y = float(values[1])
        return ((cos_a * x) - (sin_a * y), (sin_a * x) + (cos_a * y))

    def center_step_axis_on_world_point(
        self,
        label: str,
        target_world_xyz,
        *,
        row_index: int | None = None,
    ) -> dict[str, object] | None:
        """Center an imported STEP overlay axis on a layout/world point.

        The imported lens/optical/camera/LED overlays use ``*_step_axis_offset_xy`` as
        a pre-rotation transverse offset. The transformed overlay axis lands at
        ``(-offset_x, -offset_y)`` in layout X/Y for the common unrotated case.
        Clicking a KrakenOS surface while STEP-axis centering is active is a
        target-selection workflow, not a STEP-feature workflow, so set the
        absolute offset from the target surface axis instead of accumulating a
        picked-feature correction.
        """
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        if self._step_path_for_label(label) is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return None
        target = np.asarray(target_world_xyz, dtype=float).reshape(-1)
        if target.size < 2 or not np.all(np.isfinite(target[:2])):
            self.status_var.set(f"Invalid {label} STEP axis target.")
            return None
        delta = self._step_offset_delta_for_world_xy(label, target[:2])
        offset = (-float(delta[0]), -float(delta[1]))
        self._begin_history_capture()
        self._set_step_axis_offset_xy(label, offset)
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._selected_step_label = label
        if row_index is not None:
            try:
                self._select_table_row(int(row_index))
            except Exception:
                pass
        self._commit_history_capture()
        target_label = f"S{int(row_index)}" if row_index is not None else "world target"
        self.status_var.set(
            f"{label.upper()} STEP optical axis centered on {target_label} "
            f"(target X/Y={float(target[0]):.3g}, {float(target[1]):.3g} mm; "
            f"offset={offset[0]:.3g}, {offset[1]:.3g} mm)."
        )
        self._refresh_open_3d_views(step_label=label)
        return {
            "label": label,
            "row_index": int(row_index) if row_index is not None else None,
            "target": tuple(float(value) for value in target[:3]) if target.size >= 3 else (float(target[0]), float(target[1]), 0.0),
            "offset": offset,
        }

    def center_step_axis_on_surface(self, label: str, row_index: int) -> dict[str, object] | None:
        row_index = int(row_index)
        target = self._surface_reference_world_point(row_index)
        return self.center_step_axis_on_world_point(label, target, row_index=row_index)

    @staticmethod
    def _step_rotation_matrix_from_angles(x_deg: float, y_deg: float, z_deg: float) -> np.ndarray:
        x = np.deg2rad(float(x_deg))
        y = np.deg2rad(float(y_deg))
        z = np.deg2rad(float(z_deg))
        cx, sx = float(np.cos(x)), float(np.sin(x))
        cy, sy = float(np.cos(y)), float(np.sin(y))
        cz, sz = float(np.cos(z)), float(np.sin(z))
        rx = np.asarray(((1.0, 0.0, 0.0), (0.0, cx, -sx), (0.0, sx, cx)), dtype=float)
        ry = np.asarray(((cy, 0.0, sy), (0.0, 1.0, 0.0), (-sy, 0.0, cy)), dtype=float)
        rz = np.asarray(((cz, -sz, 0.0), (sz, cz, 0.0), (0.0, 0.0, 1.0)), dtype=float)
        return rz @ ry @ rx

    @staticmethod
    def _step_angles_from_rotation_matrix(matrix) -> tuple[float, float, float]:
        values = np.asarray(matrix, dtype=float).reshape(3, 3)
        sy = float(np.clip(-values[2, 0], -1.0, 1.0))
        y = float(np.arcsin(sy))
        cy = float(np.cos(y))
        if abs(cy) > 1e-9:
            x = float(np.arctan2(values[2, 1], values[2, 2]))
            z = float(np.arctan2(values[1, 0], values[0, 0]))
        else:
            x = 0.0
            z = float(np.arctan2(-values[0, 1], values[1, 1]))
        return tuple(float(np.rad2deg(angle) % 360.0) for angle in (x, y, z))

    @staticmethod
    def _rotation_matrix_between_vectors(source, target) -> np.ndarray:
        src = np.asarray(source, dtype=float).reshape(3)
        dst = np.asarray(target, dtype=float).reshape(3)
        src /= max(float(np.linalg.norm(src)), 1e-12)
        dst /= max(float(np.linalg.norm(dst)), 1e-12)
        cross = np.cross(src, dst)
        cross_norm = float(np.linalg.norm(cross))
        dot = float(np.clip(np.dot(src, dst), -1.0, 1.0))
        if cross_norm <= 1e-12:
            if dot > 0.0:
                return np.eye(3, dtype=float)
            axis = np.asarray((1.0, 0.0, 0.0), dtype=float)
            if abs(float(np.dot(axis, src))) > 0.9:
                axis = np.asarray((0.0, 1.0, 0.0), dtype=float)
            axis = np.cross(src, axis)
            axis /= max(float(np.linalg.norm(axis)), 1e-12)
            return (2.0 * np.outer(axis, axis)) - np.eye(3, dtype=float)
        axis = cross / cross_norm
        skew = np.asarray(
            (
                (0.0, -axis[2], axis[1]),
                (axis[2], 0.0, -axis[0]),
                (-axis[1], axis[0], 0.0),
            ),
            dtype=float,
        )
        angle = float(np.arctan2(cross_norm, dot))
        return np.eye(3, dtype=float) + (np.sin(angle) * skew) + ((1.0 - np.cos(angle)) * (skew @ skew))

    def _step_rotation_deg_tuple(self, label: str) -> tuple[float, float, float]:
        return (
            float(self._step_x_rotation_deg(label)),
            float(self._step_y_rotation_deg(label)),
            float(self._step_roll_deg(label)),
        )

    def _set_step_rotation_deg_tuple(self, label: str, angles: tuple[float, float, float]) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        x_deg, y_deg, z_deg = (float(value) % 360.0 for value in angles)
        setattr(self, f"{label}_step_rotation_x_deg", x_deg)
        setattr(self, f"{label}_step_rotation_y_deg", y_deg)
        setattr(self, f"{label}_step_rotation_z_deg", z_deg)

    def _step_optical_axis_frame_near_point(self, reference_point) -> dict[str, object]:
        reference = np.asarray(reference_point, dtype=float).reshape(-1)[:3]
        if reference.size < 3 or not np.all(np.isfinite(reference[:3])):
            raise RuntimeError("STEP face reference point is not finite.")
        try:
            frame = self._nearest_traced_ray_frame_near_point(reference[:3])
            return {
                "target_point": np.asarray(frame["target_point"], dtype=float).reshape(3),
                "direction": self._normalized_vector(frame["direction"]),
                "axis_label": "nearest traced optical path"
                + (f" ray {int(frame.get('ray_index', -1))}" if int(frame.get("ray_index", -1)) >= 0 else ""),
                "ray_index": int(frame.get("ray_index", -1)),
                "branch_path": str(frame.get("branch_path", "") or ""),
            }
        except Exception:
            return {
                "target_point": np.asarray((0.0, 0.0, float(reference[2])), dtype=float),
                "direction": np.asarray((0.0, 0.0, 1.0), dtype=float),
                "axis_label": "global +Z optical axis",
                "ray_index": -1,
                "branch_path": "",
            }

    def snap_step_feature_normal_to_optical_axis(
        self,
        label: str,
        feature_center_xyz,
        feature_normal_xyz,
        *,
        axis_frame: dict[str, object] | None = None,
    ) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return None
        if self._step_path_for_label(label) is None:
            self.status_var.set(f"No {label} STEP is imported.")
            return None
        feature_center = np.asarray(feature_center_xyz, dtype=float).reshape(-1)[:3]
        feature_normal = np.asarray(feature_normal_xyz, dtype=float).reshape(-1)[:3]
        if (
            feature_center.size < 3
            or feature_normal.size < 3
            or not np.all(np.isfinite(feature_center[:3]))
            or not np.all(np.isfinite(feature_normal[:3]))
        ):
            self.status_var.set("Snap STEP Normal->Optical Axis needs a finite picked STEP face center and normal.")
            return None
        feature_normal = self._normalized_vector(feature_normal[:3])
        frame = dict(axis_frame) if isinstance(axis_frame, dict) else self._step_optical_axis_frame_near_point(feature_center[:3])
        target_point = np.asarray(frame["target_point"], dtype=float).reshape(3)
        axis_direction = self._normalized_vector(frame["direction"])
        target_normal = axis_direction if float(np.dot(feature_normal, axis_direction)) >= 0.0 else -axis_direction

        current_mesh = self._transformed_imported_step_mesh_for_label(label)
        if current_mesh is None or int(getattr(current_mesh, "n_points", 0)) <= 0:
            self.status_var.set(f"{label.upper()} STEP mesh unavailable for optical-axis normal snap.")
            return None
        current_points = np.asarray(getattr(current_mesh, "points", np.empty((0, 3))), dtype=float)
        if current_points.ndim != 2 or current_points.shape[0] < 4 or current_points.shape[1] < 3:
            self.status_var.set(f"{label.upper()} STEP mesh does not have enough points for optical-axis normal snap.")
            return None

        current_angles = self._step_rotation_deg_tuple(label)
        current_offset = np.asarray(self._step_placement_offset_xyz(label), dtype=float).reshape(3)
        current_matrix = self._step_rotation_matrix_from_angles(*current_angles)
        delta_matrix = self._rotation_matrix_between_vectors(feature_normal, target_normal)
        next_matrix = delta_matrix @ current_matrix
        next_angles = self._step_angles_from_rotation_matrix(next_matrix)

        self._set_step_rotation_deg_tuple(label, next_angles)
        try:
            rotated_mesh = self._transformed_imported_step_mesh_for_label(label)
        finally:
            self._set_step_rotation_deg_tuple(label, current_angles)
        if rotated_mesh is None or int(getattr(rotated_mesh, "n_points", 0)) <= 0:
            self.status_var.set(f"{label.upper()} STEP rotated mesh unavailable for optical-axis normal snap.")
            return None
        rotated_points = np.asarray(getattr(rotated_mesh, "points", np.empty((0, 3))), dtype=float)
        affine = _affine_from_point_sets(current_points[:, :3], rotated_points[:, :3])
        if affine is not None:
            rotated_feature_center = (affine @ np.asarray((feature_center[0], feature_center[1], feature_center[2], 1.0), dtype=float))[:3]
        else:
            rotated_feature_center = feature_center[:3]
        placement_delta = target_point[:3] - np.asarray(rotated_feature_center, dtype=float).reshape(3)
        next_offset = current_offset[:3] + placement_delta[:3]

        self._begin_history_capture()
        self._set_step_rotation_deg_tuple(label, next_angles)
        self._set_step_placement_offset_xyz(label, next_offset)
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._selected_step_label = label
        self._commit_history_capture()
        rotated_normal = self._rotation_matrix_between_vectors(feature_normal, target_normal) @ feature_normal
        angle_error = float(np.rad2deg(np.arccos(np.clip(float(np.dot(rotated_normal, target_normal)), -1.0, 1.0))))
        axis_label = str(frame.get("axis_label", "optical axis"))
        self.status_var.set(
            f"{label.upper()} STEP face normal aligned to {axis_label}; "
            f"face center moved to ({target_point[0]:.6g}, {target_point[1]:.6g}, {target_point[2]:.6g}) mm."
        )
        self._refresh_open_3d_views(step_label=label)
        return {
            "label": label,
            "axis_label": axis_label,
            "target_point": tuple(float(value) for value in target_point[:3]),
            "target_direction": tuple(float(value) for value in target_normal[:3]),
            "rotation_deg": tuple(float(value) for value in next_angles),
            "placement_offset_xyz": tuple(float(value) for value in next_offset[:3]),
            "angle_error_deg": angle_error,
            "ray_index": int(frame.get("ray_index", -1)),
            "branch_path": str(frame.get("branch_path", "") or ""),
        }

    def _step_roll_deg(self, label: str) -> float:
        if label == "lens":
            return float(getattr(self, "lens_step_rotation_z_deg", 0.0))
        if label == "optical":
            return float(getattr(self, "optical_step_rotation_z_deg", 0.0))
        if label == "camera":
            return float(getattr(self, "camera_step_rotation_z_deg", 0.0))
        if label == "led":
            return float(getattr(self, "led_step_rotation_z_deg", 0.0))
        return 0.0

    def _step_x_rotation_deg(self, label: str) -> float:
        if label == "lens":
            return float(getattr(self, "lens_step_rotation_x_deg", 0.0))
        if label == "optical":
            return float(getattr(self, "optical_step_rotation_x_deg", 0.0))
        if label == "camera":
            return float(getattr(self, "camera_step_rotation_x_deg", 0.0))
        if label == "led":
            return float(getattr(self, "led_step_rotation_x_deg", 0.0))
        return 0.0

    def _step_y_rotation_deg(self, label: str) -> float:
        if label == "lens":
            return float(getattr(self, "lens_step_rotation_y_deg", 0.0))
        if label == "optical":
            return float(getattr(self, "optical_step_rotation_y_deg", 0.0))
        if label == "camera":
            return float(getattr(self, "camera_step_rotation_y_deg", 0.0))
        if label == "led":
            return float(getattr(self, "led_step_rotation_y_deg", 0.0))
        return 0.0

    def _step_target_front_z(self, label: str) -> float:
        if label == "lens":
            return float(self._lens_front_datum_z())
        if label == "camera":
            return float(self._current_image_plane_z() - self._current_camera_front_to_sensor_mm())
        if label == "led":
            return float(self._led_step_z_translation())
        return 0.0

    def apply_step_axis_pick(self, label: str, feature_center_xyz: np.ndarray) -> None:
        label = str(label).strip().lower()
        if label not in STEP_OVERLAY_LABEL_SET:
            return
        feature_center = np.asarray(feature_center_xyz, dtype=float)
        if feature_center.size < 2 or not np.all(np.isfinite(feature_center[:2])):
            self.status_var.set(f"Invalid {label} CAD feature center.")
            return
        current = np.asarray(self._step_axis_offset_xy(label), dtype=float)
        # Offsets translate the whole aligned STEP in the transverse frame. To
        # make the picked feature center land on the optical axis, cancel its
        # current world-space X/Y residual after undoing only the final Z roll.
        delta = np.asarray(self._step_offset_delta_for_world_xy(label, feature_center[:2]), dtype=float)
        new_offset = current + delta
        self._begin_history_capture()
        self._set_step_axis_offset_xy(label, (float(new_offset[0]), float(new_offset[1])))
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._selected_step_label = label
        self._commit_history_capture()
        self.status_var.set(
            f"{label.upper()} STEP feature center moved to optical axis "
            f"(picked X/Y={feature_center[0]:.3g}, {feature_center[1]:.3g} mm; "
            f"offset={new_offset[0]:.3g}, {new_offset[1]:.3g} mm)."
        )
        self._refresh_open_3d_views(step_label=label)

    def clear_step_axis_offsets(self) -> None:
        self._begin_history_capture()
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.optical_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self.lens_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.optical_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.camera_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.led_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._commit_history_capture()
        self.status_var.set("CAD STEP optical-axis offsets cleared.")
        self._refresh_open_3d_views()

    def clear_step_imports(self) -> None:
        self._begin_history_capture()
        self.imported_camera_step_path = None
        self.imported_lens_step_path = None
        self.imported_optical_step_path = None
        self.imported_led_step_path = None
        self.lens_step_largest_component_only = True
        self.camera_step_rotation_x_deg = 0.0
        self.lens_step_rotation_x_deg = 0.0
        self.optical_step_rotation_x_deg = 0.0
        self.led_step_rotation_x_deg = 0.0
        self.camera_step_rotation_y_deg = 0.0
        self.lens_step_rotation_y_deg = 0.0
        self.optical_step_rotation_y_deg = 0.0
        self.led_step_rotation_y_deg = 0.0
        self.camera_step_rotation_z_deg = 0.0
        self.lens_step_rotation_z_deg = 0.0
        self.optical_step_rotation_z_deg = 0.0
        self.led_step_rotation_z_deg = 0.0
        self.led_object_edge_distance_mm = 0.0
        self.led_step_object_edge_local_z = None
        self.lens_step_axis_offset_xy = (0.0, 0.0)
        self.optical_step_axis_offset_xy = (0.0, 0.0)
        self.camera_step_axis_offset_xy = (0.0, 0.0)
        self.led_step_axis_offset_xy = (0.0, 0.0)
        self.lens_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.optical_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.camera_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self.led_step_placement_offset_xyz = (0.0, 0.0, 0.0)
        self._cad_axis_pick_label = None
        self._cad_axis_pick_any = False
        self._cad_led_object_edge_pick = False
        self._selected_step_label = None
        self._commit_history_capture()
        self.status_var.set("Camera/lens/optical/LED STEP imports cleared.")
        self._refresh_open_3d_views()

    def _has_imported_step_cad(self) -> bool:
        return any(
            path is not None
            for path in (
                self.imported_lens_step_path,
                self.imported_optical_step_path,
                self.imported_led_step_path,
                self.imported_camera_step_path,
            )
        )

    def _step_export_alignment_params(self, label: str) -> dict[str, object] | None:
        label = str(label).strip().lower()
        if label == "lens":
            if self.imported_lens_step_path is None:
                return None
            cylinder_axis = self._step_primary_cylinder_axis(self.imported_lens_step_path)
            return {
                "path": self.imported_lens_step_path,
                "largest_component": bool(getattr(self, "lens_step_largest_component_only", True)),
                "source_axis": cylinder_axis if cylinder_axis is not None else "pca0",
                "front_face": "max",
                "target_front_z": self._lens_front_datum_z(),
                "label": "Lens STEP",
                "roll_deg": float(getattr(self, "lens_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "lens_step_rotation_x_deg", 0.0)),
                "y_rotation_deg": float(getattr(self, "lens_step_rotation_y_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("lens"),
                "placement_offset_xyz": self._step_placement_offset_xyz("lens"),
            }
        if label == "camera":
            if self.imported_camera_step_path is None:
                return None
            camera_front_z = self._current_image_plane_z() - self._current_camera_front_to_sensor_mm()
            return {
                "path": self.imported_camera_step_path,
                "largest_component": True,
                "source_axis": "z",
                "front_face": "max",
                "target_front_z": camera_front_z,
                "label": "Camera STEP",
                "roll_deg": float(getattr(self, "camera_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "camera_step_rotation_x_deg", 0.0)),
                "y_rotation_deg": float(getattr(self, "camera_step_rotation_y_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("camera"),
                "placement_offset_xyz": self._step_placement_offset_xyz("camera"),
            }
        if label == "optical":
            if self.imported_optical_step_path is None:
                return None
            return {
                "path": self.imported_optical_step_path,
                "largest_component": False,
                "source_axis": "z",
                "front_face": "min",
                "target_front_z": 0.0,
                "label": "Optical STEP",
                "roll_deg": float(getattr(self, "optical_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "optical_step_rotation_x_deg", 0.0)),
                "y_rotation_deg": float(getattr(self, "optical_step_rotation_y_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("optical"),
                "placement_offset_xyz": self._step_placement_offset_xyz("optical"),
            }
        if label == "led":
            if self.imported_led_step_path is None:
                return None
            return {
                "path": self.imported_led_step_path,
                "largest_component": False,
                "source_axis": "z",
                "front_face": "min",
                "target_front_z": self._led_step_z_translation(),
                "label": "LED STEP",
                "roll_deg": float(getattr(self, "led_step_rotation_z_deg", 0.0)),
                "x_rotation_deg": float(getattr(self, "led_step_rotation_x_deg", 0.0)),
                "y_rotation_deg": float(getattr(self, "led_step_rotation_y_deg", 0.0)),
                "axis_offset_xy": self._step_axis_offset_xy("led"),
                "placement_offset_xyz": self._step_placement_offset_xyz("led"),
            }
        return None

    def _step_alignment_affine(self, params: dict[str, object]) -> np.ndarray | None:
        path = Path(params["path"])
        source_mesh = self._load_step_mesh(
            path,
            largest_component=bool(params.get("largest_component", False)),
        )
        aligned_mesh = self._cad_mesh_aligned_to_optical_axis(
            source_mesh,
            source_axis=params.get("source_axis", "z"),
            front_face=str(params.get("front_face", "min")),
            target_front_z=float(params.get("target_front_z", 0.0)),
            label=str(params.get("label", "STEP")),
            roll_deg=float(params.get("roll_deg", 0.0)),
            x_rotation_deg=float(params.get("x_rotation_deg", 0.0)),
            y_rotation_deg=float(params.get("y_rotation_deg", 0.0)),
            axis_offset_xy=params.get("axis_offset_xy"),
            placement_offset_xyz=params.get("placement_offset_xyz"),
        )
        if aligned_mesh is None:
            return None
        matrix = _affine_from_point_sets(
            np.asarray(source_mesh.points, dtype=float),
            np.asarray(aligned_mesh.points, dtype=float),
        )
        return matrix

    def _collect_native_step_export_shapes(self, progress_callback=None) -> list[tuple[str, object]]:
        shape_items: list[tuple[str, object]] = []
        labels = STEP_OVERLAY_LABELS
        for index, label in enumerate(labels, start=1):
            params = self._step_export_alignment_params(label)
            if params is None:
                continue
            if progress_callback is not None:
                progress_callback(
                    f"Preparing {params.get('label', label)} native STEP",
                    index,
                    len(labels),
                )
            try:
                matrix = self._step_alignment_affine(params)
                if matrix is None:
                    raise RuntimeError("could not compute CAD placement affine")
                shape = _read_step_shape(Path(params["path"]))
                shape_items.append((str(params.get("label", label)), _shape_with_affine(shape, matrix)))
            except Exception as exc:
                self.append_debug(f"3D STEP native {label} export skipped: {exc}")
        return shape_items

    def _step_export_ray_polylines(self, system) -> list[np.ndarray]:
        previous_ray_count = getattr(self, "_preview_field_ray_count", None)
        previous_bundle_count = getattr(self, "_preview_field_bundle_count", None)
        rays_per_group = previous_ray_count
        try:
            wavelength = self._current_wavelength()
            max_radius = max((max(float(row.diameter) / 2.0, 0.5) for row in self.rows), default=1.0)
            rays = Kos.raykeeper(system)
            self._trace_preview_rays(
                system,
                rays,
                wavelength,
                max_radius,
                allow_full_pupil=True,
                sampling_mode="world_envelope",
            )
            rays_per_group = getattr(self, "_preview_field_ray_count", previous_ray_count)
        except Exception as exc:
            self.append_debug(f"3D STEP ray export skipped: {exc}")
            rays = self.last_rays
        finally:
            if previous_ray_count is not None:
                self._preview_field_ray_count = previous_ray_count
            if previous_bundle_count is not None:
                self._preview_field_bundle_count = previous_bundle_count
        polylines: list[np.ndarray] = []
        for ray in getattr(rays, "CC", ()) if rays is not None else ():
            pts = np.asarray(ray, dtype=float)
            if pts.ndim != 2 or pts.shape[0] < 2 or pts.shape[1] < 3:
                continue
            if not np.any(np.all(np.isfinite(pts[:, :3]), axis=1)):
                continue
            polylines.append(pts[:, :3].copy())
        envelope = _ray_bundle_envelope_polylines(
            polylines,
            rays_per_group,
        )
        if len(envelope) < len(polylines):
            self.append_progress(
                f"STEP ray export reduced to envelope: {len(envelope)}/{len(polylines)} traced rays"
            )
        return envelope

    def _collect_3d_step_export_meshes(self, system) -> list[tuple[str, object]]:
        _load_3d_backends()
        if pv is None:
            raise RuntimeError("PyVista is required to collect 3D export geometry")

        mesh_items: list[tuple[str, object]] = []

        def add_mesh(label: str, mesh) -> None:
            if mesh is None:
                return
            try:
                surface = mesh.extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                try:
                    surface = mesh.copy(deep=True)
                except Exception:
                    return
            try:
                if int(getattr(surface, "n_points", 0)) > 0:
                    mesh_items.append((label, surface))
            except Exception:
                pass

        transforms = getattr(system, "TRANS_2A", None)
        surfaces = getattr(system, "AAA", None)
        if transforms is not None and surfaces is not None:
            block_count = min(len(self.rows), getattr(surfaces, "n_blocks", 0), len(transforms))
            for index in range(block_count):
                row = self.rows[index]
                if row.surface in {"Object", "Image"}:
                    continue
                add_mesh(
                    f"surface_{index}_{row.name or row.surface}",
                    Kraken3DInspector._mesh_with_transform(surfaces[index], transforms[index]),
                )

        side_index = 0
        for row_index in getattr(system, "side_number", []):
            try:
                body = pv.wrap(system.BBB[side_index]).extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                side_index += 1
                continue
            side_index += 1
            if 0 <= int(row_index) < len(self.rows):
                row = self.rows[int(row_index)]
                add_mesh(f"edge_{int(row_index)}_{row.name or row.surface}", body)
            else:
                add_mesh(f"edge_{int(row_index)}", body)

        try:
            add_mesh("external_camera", self._transformed_external_camera_mesh())
        except Exception as exc:
            self.append_debug(f"3D STEP export external camera skipped: {exc}")

        for label, builder in (
            ("lens_step", self._transformed_imported_lens_step_mesh),
            ("optical_step", self._transformed_imported_optical_step_mesh),
            ("led_step", self._transformed_imported_led_step_mesh),
            ("camera_step", self._transformed_imported_camera_step_mesh),
        ):
            try:
                add_mesh(label, builder())
            except Exception as exc:
                self.append_debug(f"3D STEP export {label} skipped: {exc}")

        return mesh_items

    def _collect_step_edge_and_extra_meshes(self, system) -> list[tuple[str, object]]:
        """Collect edge geometry and imported meshes, excluding optical surface
        faces (which are handled analytically)."""
        _load_3d_backends()
        if pv is None:
            return []

        mesh_items: list[tuple[str, object]] = []

        def add_mesh(label: str, mesh) -> None:
            if mesh is None:
                return
            try:
                surface = mesh.extract_surface(algorithm="dataset_surface").copy(deep=True)
            except Exception:
                try:
                    surface = mesh.copy(deep=True)
                except Exception:
                    return
            try:
                if int(getattr(surface, "n_points", 0)) > 0:
                    mesh_items.append((label, surface))
            except Exception:
                pass

        side_index = 0
        for row_index in getattr(system, "side_number", []):
            try:
                body = pv.wrap(system.BBB[side_index]).extract_surface(
                    algorithm="dataset_surface"
                ).copy(deep=True)
            except Exception:
                side_index += 1
                continue
            side_index += 1
            if 0 <= int(row_index) < len(self.rows):
                row = self.rows[int(row_index)]
                add_mesh(f"edge_{int(row_index)}_{row.name or row.surface}", body)
            else:
                add_mesh(f"edge_{int(row_index)}", body)

        try:
            add_mesh("external_camera", self._transformed_external_camera_mesh())
        except Exception:
            pass

        for label, builder in (
            ("lens_step", self._transformed_imported_lens_step_mesh),
            ("optical_step", self._transformed_imported_optical_step_mesh),
            ("led_step", self._transformed_imported_led_step_mesh),
            ("camera_step", self._transformed_imported_camera_step_mesh),
        ):
            try:
                add_mesh(label, builder())
            except Exception:
                pass

        return mesh_items

    def _ask_step_file(self, title: str, initial_dir: Path, *, parent: tk.Misc | None = None) -> Path | None:
        path = filedialog.askopenfilename(
            title=title,
            initialdir=str(initial_dir if initial_dir.exists() else Path.home()),
            filetypes=[
                ("STEP files", "*.step *.stp *.ste *.STEP *.STP *.STE"),
                ("All files", "*"),
            ],
            parent=parent or self,
        )
        if not path:
            return None
        selected = Path(path).expanduser()
        if not selected.exists():
            messagebox.showerror("STEP file not found", f"File does not exist:\n\n{selected}", parent=parent or self)
            return None
        return selected

    def _refresh_open_3d_views(self, *, camera_only: bool = False, step_label: str | None = None) -> None:
        if camera_only:
            step_label = "camera"
        if self._three_d_inspector is not None:
            try:
                if self._three_d_inspector.winfo_exists():
                    self._three_d_inspector.refresh_from_editor()
            except Exception:
                pass
        if self._legacy_3d_plotter is not None:
            labels = [step_label] if step_label else list(STEP_OVERLAY_LABELS)
            refreshed = False
            for label in labels:
                if label and self._refresh_legacy_step_actor(self._legacy_3d_plotter, label):
                    refreshed = True
            if refreshed:
                return
            self.status_var.set("STEP change saved. Close and reopen legacy 3D view to redraw.")

    def _refresh_legacy_camera_step_actor(self, plotter) -> bool:
        return self._refresh_legacy_step_actor(plotter, "camera")

    def _refresh_legacy_step_actor(self, plotter, label: str) -> bool:
        if plotter is None:
            return False
        scene = dict(getattr(plotter, "_kraken_scene", {}) or {})
        cad_step_actors = dict(scene.get("cad_step_actors", {}) or {})
        cad_step_actor_map = dict(scene.get("cad_step_actor_map", {}) or {})
        step_actors = list(cad_step_actors.get(label, []) or [])
        visibility = dict(getattr(plotter, "_kraken_visibility", {}) or {})
        visible = bool(visibility.get(f"step_{label}", True))
        try:
            builders = {
                "camera": self._transformed_imported_camera_step_mesh,
                "led": self._transformed_imported_led_step_mesh,
                "lens": self._transformed_imported_lens_step_mesh,
                "optical": self._transformed_imported_optical_step_mesh,
            }
            builder = builders.get(label)
            if builder is None:
                return False
            cad_mesh = builder()
        except Exception as exc:
            self.append_debug(f"Legacy 3D {label} STEP refresh failed: {exc}")
            return False
        if cad_mesh is None or int(getattr(cad_mesh, "n_points", 0)) <= 0:
            if not step_actors:
                return False
            hidden = False
            for _kind, actor in step_actors:
                try:
                    actor.SetVisibility(False)
                    hidden = True
                except Exception:
                    pass
            if hidden:
                try:
                    plotter.render()
                except Exception:
                    pass
            return hidden
        try:
            edges = cad_mesh.extract_feature_edges(
                feature_angle=20,
                boundary_edges=True,
                feature_edges=True,
                manifold_edges=False,
            )
        except Exception:
            edges = None
        if not step_actors:
            try:
                color, opacity = {
                    "lens": ("#4b5563", 0.22),
                    "optical": ("#0891b2", 0.30),
                    "led": ("#f59e0b", 0.35),
                    "camera": ("#6b7280", 0.32),
                }.get(label, ("#6b7280", 0.32))
                helper_actors = list(scene.get("helper_actors", []) or [])
                cad_step_actors.setdefault(label, [])
                actor = plotter.add_mesh(
                    cad_mesh,
                    color=color,
                    opacity=opacity,
                    smooth_shading=False,
                    show_edges=False,
                    pickable=True,
                )
                try:
                    actor.SetPickable(True)
                except Exception:
                    pass
                actor_key = Kraken3DInspector._actor_key(actor)
                if actor_key is not None:
                    cad_step_actor_map[actor_key] = label
                try:
                    actor.SetVisibility(visible)
                except Exception:
                    pass
                cad_step_actors[label].append(("mesh", actor))
                if edges is not None and int(getattr(edges, "n_points", 0)) > 0:
                    edge_actor = plotter.add_mesh(edges, color="#111827", line_width=0.8, pickable=False)
                    try:
                        edge_actor.SetVisibility(visible)
                    except Exception:
                        pass
                    cad_step_actors[label].append(("edges", edge_actor))
                scene["helper_actors"] = helper_actors
                scene["cad_step_actors"] = cad_step_actors
                scene["cad_step_actor_map"] = cad_step_actor_map
                setattr(plotter, "_kraken_scene", scene)
                try:
                    plotter.render()
                except Exception:
                    pass
                return True
            except Exception as exc:
                self.append_debug(f"Legacy 3D {label} STEP add failed: {exc}")
                return False
        refreshed = False
        for kind, actor in step_actors:
            try:
                mapper = actor.GetMapper()
                if mapper is None:
                    continue
                if kind == "edges":
                    if edges is None or int(getattr(edges, "n_points", 0)) <= 0:
                        actor.SetVisibility(False)
                        continue
                    mapper.SetInputData(edges)
                    actor.SetVisibility(visible)
                else:
                    mapper.SetInputData(cad_mesh)
                    actor.SetVisibility(visible)
                mapper.Modified()
                refreshed = True
            except Exception as exc:
                self.append_debug(f"Legacy 3D {label} actor update failed: {exc}")
        if refreshed:
            try:
                plotter.render()
            except Exception:
                pass
            if label == "camera":
                self.status_var.set(
                    f"Camera STEP rotation: X={self.camera_step_rotation_x_deg:.0f}, "
                    f"Y={self.camera_step_rotation_y_deg:.0f}, "
                    f"Z={self.camera_step_rotation_z_deg:.0f} deg"
                )
            elif label == "lens":
                self.status_var.set(
                    f"Lens STEP rotation: X={self.lens_step_rotation_x_deg:.0f}, "
                    f"Y={self.lens_step_rotation_y_deg:.0f}, "
                    f"Z={self.lens_step_rotation_z_deg:.0f} deg"
                )
            elif label == "optical":
                self.status_var.set(
                    f"Optical STEP rotation: X={self.optical_step_rotation_x_deg:.0f}, "
                    f"Y={self.optical_step_rotation_y_deg:.0f}, "
                    f"Z={self.optical_step_rotation_z_deg:.0f} deg"
                )
            elif label == "led":
                reference_text = (
                    "unset"
                    if getattr(self, "led_step_object_edge_local_z", None) is None
                    else f"{float(self.led_step_object_edge_local_z):.3g} mm"
                )
                self.status_var.set(
                    f"LED STEP: x rotation={self.led_step_rotation_x_deg:.0f} deg, "
                    f"y rotation={self.led_step_rotation_y_deg:.0f} deg, "
                    f"z rotation={self.led_step_rotation_z_deg:.0f} deg, "
                    f"edge distance={self.led_object_edge_distance_mm:.3g} mm, "
                    f"edge ref={reference_text}"
                )
        return refreshed

