    def _finish_edit(self, row_id: str, field: str, quiet: bool = False) -> None:
        if self.editor is None:
            return
        value = self.editor.get().strip()
        self.editor.destroy()
        self.editor = None
        self._editor_row_id = None
        self._editor_field = None
        if not value:
            return
        row_index = self._table_item_row_index(row_id)
        if row_index is None:
            return
        if field in NUMERIC_FIELDS:
            accepts_pose_sequence = False
            path_local_pose_cell = self._path_local_pose_cell_enabled(row_index, field)
            if field in POSE_TOLERANCE_FIELDS and 0 <= row_index < len(self.rows) and not path_local_pose_cell:
                try:
                    pose_values = _parse_float_sequence_text(value.replace("*", "").strip())
                    if len(pose_values) > POSE_TOLERANCE_MAX_VARIANTS:
                        raise ValueError(f"Use {POSE_TOLERANCE_MAX_VARIANTS} or fewer overlay values.")
                    accepts_pose_sequence = bool(pose_values)
                except Exception:
                    accepts_pose_sequence = False
            if not accepts_pose_sequence:
                try:
                    float(value)
                except ValueError:
                    if not quiet:
                        messagebox.showerror(
                            "Invalid value",
                            f"{COLUMN_LABELS[field]} expects a number"
                            + (" or comma/range tolerance values." if field in POSE_TOLERANCE_FIELDS and not path_local_pose_cell else "."),
                        )
                    return
        if not self._table_cell_enabled(row_index, field):
            if not quiet:
                self.status_var.set(self._surface_type_disabled_message(row_index, field))
            return
        self._begin_history_capture()
        if field == "diameter" and row_index == len(self.rows) - 1:
            self._set_image_diameter_mode("Manual")
        self.table.set(row_id, field, value)
        self._read_rows_from_table()
        self._normalize_special_rows()
        self._couple_object_image_diameter_after_edit(row_index, field)
        self._sync_table()
        self._commit_history_capture()
        self._mark_plot_update_pending()

    def _couple_object_image_diameter_after_edit(self, row_index: int, field: str) -> None:
        if field != "diameter" or len(self.rows) < 2:
            return
        if row_index not in {0, len(self.rows) - 1}:
            return
        if self._current_object_mode() != "Finite":
            return
        magnification = self._current_finite_paraxial_magnification()
        if magnification is None or not np.isfinite(magnification) or abs(float(magnification)) <= 1e-12:
            return
        mag = abs(float(magnification))
        self._set_image_diameter_mode("Manual")
        if row_index == 0 and self.rows[0].surface == "Object":
            object_diameter = max(float(self.rows[0].diameter), 0.0)
            self.rows[-1].diameter = max(object_diameter * mag, 1e-6)
            source = "Object"
        elif row_index == len(self.rows) - 1 and self.rows[-1].surface == "Image":
            image_diameter = max(float(self.rows[-1].diameter), 0.0)
            self.rows[0].diameter = max(image_diameter / mag, 1e-6)
            source = "Image"
        else:
            return
        self._sync_field_value_from_diameter_pair()
        status_var = self.__dict__.get("status_var")
        if status_var is not None:
            status_var.set(
                f"{source} diameter applied; paired diameter updated with |m|={mag:.6g}. Click Update to redraw."
            )

    def _sync_object_diameter_from_manual_image(self) -> bool:
        if len(self.rows) < 2 or self.rows[0].surface != "Object" or self.rows[-1].surface != "Image":
            return False
        if self._current_object_mode() != "Finite" or self._current_image_diameter_mode() != "Manual":
            return False
        magnification = self._current_finite_paraxial_magnification()
        if magnification is None or not np.isfinite(magnification) or abs(float(magnification)) <= 1e-12:
            return False
        image_diameter = max(float(self.rows[-1].diameter), 0.0)
        self.rows[0].diameter = max(image_diameter / abs(float(magnification)), 1e-6)
        self._sync_field_value_from_diameter_pair()
        return True

    def _sync_field_value_from_diameter_pair(self) -> None:
        if self.__dict__.get("field_value_var") is None or self.__dict__.get("field_type_var") is None or not self.rows:
            return
        field_type = self._current_field_type()
        object_half = max(float(self.rows[0].diameter) * 0.5, 0.0)
        image_half = max(float(self.rows[-1].diameter) * 0.5, 0.0)
        if field_type == "Object Height":
            value = object_half
        elif field_type in {"Paraxial Image Height", "Real Image Height"}:
            value = image_half
        elif field_type == "Angle":
            value = float(np.rad2deg(np.arctan2(object_half, max(self._current_object_distance(), 1e-9))))
        else:
            return
        self.field_value_var.set(self._format_table_float(value))

    def _set_image_diameter_mode(self, mode: str) -> None:
        image_diameter_mode_var = self.__dict__.get("image_diameter_mode_var")
        if image_diameter_mode_var is not None and mode in {"Auto", "Manual"}:
            image_diameter_mode_var.set(mode)

    def _cancel_edit(self) -> None:
        if self.editor is None:
            return
        self.editor.destroy()
        self.editor = None
        self._editor_row_id = None
        self._editor_field = None

    def _commit_pending_table_edit(self) -> None:
        if self.editor is None or self._editor_row_id is None or self._editor_field is None:
            return
        self._finish_edit(self._editor_row_id, self._editor_field, quiet=True)

    def _show_choice_menu(
        self,
        row_id: str,
        field: str,
        values: tuple[str, ...],
        x_root: int,
        y_root: int,
    ) -> None:
        self._cleanup_current_popup_menu()
        menu = tk.Menu(self, tearoff=0)
        for value in values:
            menu.add_command(
                label=value,
                command=lambda selected=value: self._apply_choice(row_id, field, selected),
            )
        self._post_popup_menu(menu, x_root, y_root)

    def _post_popup_menu(self, menu: tk.Menu, x_root: int, y_root: int) -> None:
        self.popup_menu = menu
        try:
            menu.tk_popup(x_root, y_root)
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass

    def _apply_choice(self, row_id: str, field: str, value: str) -> None:
        self._begin_history_capture()
        self.table.set(row_id, field, value)
        self._read_rows_from_table()
        if field == "surface":
            index = self._table_item_row_index(row_id)
            if index is None:
                return
            row = self.rows[index]
            self._apply_surface_type_defaults(index, row, value)
        self._normalize_special_rows()
        self._sync_table()
        self._commit_history_capture()
        self._mark_plot_update_pending()
        self._cleanup_current_popup_menu()

    def _apply_surface_type_defaults(self, index: int, row: SurfaceRow, surface_type: str) -> None:
        prev_row = self.rows[index - 1] if index > 0 else None
        next_row = self.rows[index + 1] if index + 1 < len(self.rows) else None
        neighbor_diameters = [
            float(candidate.diameter)
            for candidate in (prev_row, next_row)
            if candidate is not None and candidate.surface not in {"Object", "Image"}
        ]
        fallback_diameter = min(neighbor_diameters) if neighbor_diameters else max(float(row.diameter), 10.0)

        if surface_type in REFLECTIVE_PROXY_SURFACES:
            default_name = (
                "Object target"
                if surface_type == OBJECT_TARGET_SURFACE
                else "Diffuse object"
                if surface_type == DIFFUSE_OBJECT_SURFACE
                else "Mirror"
            )
            row.name = default_name if row.name in {"", "Surface", "Standard", "Aperture", "Mirror", "Object target", "Diffuse object"} else row.name
            row.glass = "MIRROR"
            row.rc = 0.0
            if surface_type == "Mirror" and abs(row.tilt_x) < 1e-9 and abs(row.tilt_y) < 1e-9 and abs(row.tilt_z) < 1e-9:
                row.tilt_x = 45.0
            if abs(row.axis_move) < 1e-9:
                row.axis_move = 2.0
            advanced = dict(row.advanced or {})
            if surface_type == OBJECT_TARGET_SURFACE:
                display = dict(advanced.get("Display2D", {}) or {})
                display.setdefault("label", "Object target")
                advanced["Display2D"] = display
                note = (
                    "Object Target currently traces as a specular reflective proxy so source/object split "
                    "fixtures can return rays. Use a Diffuse Object row when rough/diffuse BRDF scattering is needed."
                )
                existing_note = str(advanced.get("Note", "") or "").strip()
                if note not in existing_note:
                    advanced["Note"] = f"{note} {existing_note}".strip()
                row.element = row.element or "Object target"
            elif surface_type == DIFFUSE_OBJECT_SURFACE:
                display = dict(advanced.get("Display2D", {}) or {})
                display.setdefault("label", "Diffuse object")
                advanced["Display2D"] = display
                advanced[DIFFUSE_SCATTER_ADVANCED_ATTR] = _normalize_diffuse_scatter_settings(
                    advanced.get(DIFFUSE_SCATTER_ADVANCED_ATTR, DIFFUSE_SCATTER_DEFAULT_SETTINGS)
                )
                note = (
                    "Diffuse Object spawns deterministic built-in scatter branches in Non-Sequential Preview. "
                    "Use Diffuse/BRDF settings to control model, reflectance, samples, scatter cone, and target guidance."
                )
                existing_note = str(advanced.get("Note", "") or "").strip()
                if note not in existing_note:
                    advanced["Note"] = f"{note} {existing_note}".strip()
                row.element = row.element or "Diffuse object"
            else:
                display = dict(advanced.get("Display2D", {}) or {})
                if display.get("label") in {"Object target", "Diffuse object"}:
                    display.pop("label", None)
                if display:
                    advanced["Display2D"] = display
                else:
                    advanced.pop("Display2D", None)
                advanced.pop(DIFFUSE_SCATTER_ADVANCED_ATTR, None)
            row.advanced = advanced
            self._clear_disabled_surface_type_fields(row)
            return

        if surface_type == BEAM_SPLITTER_SURFACE:
            row.name = "50/50 Beam Splitter" if row.name in {"", "Surface", "Standard", "Aperture", "Mirror", "Object target"} else row.name
            if row.glass == "MIRROR":
                row.glass = "AIR"
            row.rc = 0.0
            if abs(row.tilt_x) < 1e-9 and abs(row.tilt_y) < 1e-9 and abs(row.tilt_z) < 1e-9:
                row.tilt_x = 45.0
            advanced = dict(row.advanced or {})
            splitter_settings = _normalize_beam_splitter_settings(advanced.get(BEAM_SPLITTER_ADVANCED_ATTR))
            advanced[BEAM_SPLITTER_ADVANCED_ATTR] = splitter_settings
            advanced["Coating"] = _beam_splitter_coating_for_settings(splitter_settings, advanced.get("Coating"))
            note = (
                "Beam Splitter rows spawn deterministic reflected/transmitted paths in Non-Sequential Preview. "
                "Use Glass + Thickness plus a following rear AIR surface for finite plate deviation; "
                "use the same rear TiltX for a parallel plate."
            )
            existing_note = str(advanced.get("Note", "") or "").strip()
            if note not in existing_note:
                advanced["Note"] = f"{note} {existing_note}".strip()
            row.advanced = advanced
            self._clear_disabled_surface_type_fields(row)
            return

        if surface_type == "Aperture":
            row.name = "Aperture"
            row.glass = "AIR"
            row.rc = 0.0
            row.diameter = max(0.1, min(float(self._current_aperture_value()), fallback_diameter))
            self._clear_disabled_surface_type_fields(row)
            return

        if surface_type == "Thin Lens":
            row.name = "Thin Lens" if row.name in {"", "Surface", "Standard"} else row.name
            if row.glass == "MIRROR":
                row.glass = "AIR"
            if abs(row.rc) < 1e-9:
                row.rc = 100.0
            self._clear_disabled_surface_type_fields(row)
            return

        if surface_type == "Grating":
            row.name = "Grating" if row.name in {"", "Surface", "Standard"} else row.name
            row.rc = 0.0
            if abs(row.diff_ord) < 1e-9:
                row.diff_ord = 1.0
            if abs(row.grating_d) < 1e-9:
                row.grating_d = 1.0
            self._clear_disabled_surface_type_fields(row)
            return

        if surface_type == "Standard":
            row.name = "Surface" if row.name in {"", "Mirror", "Object target", "Diffuse object", "Aperture", "Thin Lens", "Grating", "50/50 Beam Splitter"} else row.name
            if row.glass == "MIRROR":
                row.glass = "AIR"
            row.advanced = dict(row.advanced or {})
            row.advanced.pop(BEAM_SPLITTER_ADVANCED_ATTR, None)
            row.advanced.pop(DIFFUSE_SCATTER_ADVANCED_ATTR, None)
        self._clear_disabled_surface_type_fields(row)

    def _clear_disabled_surface_type_fields(self, row: SurfaceRow) -> None:
        disabled = (set(FIELDS) | set(GRATING_SETTING_FIELDS)) - self._surface_type_enabled_fields(row.surface)
        if "glass" in disabled:
            row.glass = "MIRROR" if row.surface in REFLECTIVE_PROXY_SURFACES else "AIR"
        numeric_attrs = {
            "rc": "rc",
            "k": "k",
            "axicon": "axicon",
            "diff_ord": "diff_ord",
            "grating_d": "grating_d",
            "grating_angle": "grating_angle",
            "thickness": "thickness",
            "in_diameter": "in_diameter",
            "tilt_x": "tilt_x",
            "tilt_y": "tilt_y",
            "tilt_z": "tilt_z",
            "desp_x": "desp_x",
            "desp_y": "desp_y",
            "desp_z": "desp_z",
            "axis_move": "axis_move",
        }
        for field, attr in numeric_attrs.items():
            if field in disabled:
                setattr(row, attr, 0.0)

    @staticmethod
    def _row_has_optimization(row: SurfaceRow) -> bool:
        return row.optimize_rc or row.optimize_thickness or bool(_row_native_variable_names(row))

    @staticmethod
    def _row_native_variable_enabled(row: SurfaceRow, parameter: str) -> bool:
        return any(
            _native_variable_matches(candidate, parameter)
            for candidate in _row_native_variable_names(row)
        )

    @classmethod
    def _variable_enabled_for_row(cls, row: SurfaceRow, spec) -> bool:
        return bool(spec.is_enabled(row) or cls._row_native_variable_enabled(row, spec.parameter))

    @classmethod
    def _optimization_marker_fields_for_row(cls, row: SurfaceRow) -> tuple[str, ...]:
        marker_fields: list[str] = []
        for field in FIELDS:
            spec = VARIABLE_REGISTRY.get(field)
            if spec is None or not spec.is_supported(row):
                continue
            if cls._variable_enabled_for_row(row, spec):
                marker_fields.append(field)
        return tuple(marker_fields)

    @staticmethod
    def _remove_native_variable_from_row(row: SurfaceRow, parameter: str) -> None:
        names = [
            candidate
            for candidate in _row_native_variable_names(row)
            if not _native_variable_matches(candidate, parameter)
        ]
        row.advanced = dict(row.advanced or {})
        if names:
            row.advanced["Var"] = names
        else:
            row.advanced.pop("Var", None)
        bounds = row.advanced.get("VarBounds")
        if isinstance(bounds, dict):
            for key in list(bounds):
                if _native_variable_matches(key, parameter):
                    bounds.pop(key, None)
            if bounds:
                row.advanced["VarBounds"] = bounds
            else:
                row.advanced.pop("VarBounds", None)

    def toggle_current_optimization_cell(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None:
            return
        self._begin_history_capture()
        enabled = self._variable_enabled_for_row(row, spec)
        spec.set_enabled(row, not enabled)
        if enabled:
            self._remove_native_variable_from_row(row, spec.parameter)
        self._sync_table()
        self._commit_history_capture()
        self.refresh_plot()
        self._cleanup_current_popup_menu()

    def toggle_current_tolerance_compensator(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None or not self._variable_enabled_for_row(row, spec):
            return
        enabled = self._tolerance_variable_compensator_enabled(
            OpticalVariable(index, spec.parameter, 0.0, 1.0, name=f"{row.name} {spec.label}")
        )
        self._begin_history_capture()
        self.set_tolerance_compensator_enabled(index, spec.parameter, not enabled)
        self._commit_history_capture()
        role = "compensator" if not enabled else "tolerance-only"
        self.append_progress(f"Row {index} {spec.label} set to {role}.")
        self._cleanup_current_popup_menu()

    def edit_current_bounds(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None:
            return
        current = spec.get_bounds(row)
        current_value = spec.value_from_row(row)
        default_bounds = current or spec.default_bounds(current_value)

        dialog = tk.Toplevel(self)
        dialog.withdraw()
        dialog.title(f"Bounds for {row.name} {spec.label}")
        dialog.transient(self)
        dialog.grab_set()
        dialog.resizable(False, False)

        ttk.Label(dialog, text="Lower").grid(row=0, column=0, padx=12, pady=(12, 4), sticky="w")
        lower_var = tk.StringVar(value=f"{default_bounds[0]:g}")
        ttk.Entry(dialog, textvariable=lower_var, width=16).grid(row=1, column=0, padx=12, pady=(0, 8))

        ttk.Label(dialog, text="Upper").grid(row=2, column=0, padx=12, pady=(0, 4), sticky="w")
        upper_var = tk.StringVar(value=f"{default_bounds[1]:g}")
        ttk.Entry(dialog, textvariable=upper_var, width=16).grid(row=3, column=0, padx=12, pady=(0, 12))

        def accept():
            try:
                lower = float(lower_var.get())
                upper = float(upper_var.get())
            except ValueError:
                self.append_debug("Invalid optimization bounds entry.")
                return
            if lower >= upper:
                self.append_debug("Optimization bounds rejected: lower must be less than upper.")
                return
            self._begin_history_capture()
            spec.set_bounds(row, (lower, upper))
            self._commit_history_capture()
            self.append_progress(
                f"Bounds set for row {index} {spec.label}: [{lower:g}, {upper:g}]"
            )
            dialog.destroy()

        buttons = ttk.Frame(dialog)
        buttons.grid(row=4, column=0, padx=12, pady=(0, 12), sticky="w")
        ttk.Button(buttons, text="Save", command=accept).pack(side="left")
        ttk.Button(buttons, text="Cancel", command=dialog.destroy).pack(side="left", padx=(8, 0))

        self._show_centered_dialog(dialog)
        self.wait_window(dialog)
        self._cleanup_current_popup_menu()

    def _show_centered_dialog(self, dialog: tk.Toplevel) -> None:
        def place_dialog() -> None:
            if not dialog.winfo_exists():
                return
            dialog.update_idletasks()
            dialog_width = max(dialog.winfo_reqwidth(), dialog.winfo_width(), 1)
            dialog_height = max(dialog.winfo_reqheight(), dialog.winfo_height(), 1)
            screen_width = max(dialog.winfo_screenwidth(), 1)
            screen_height = max(dialog.winfo_screenheight(), 1)
            pos_x = max((screen_width - dialog_width) // 2, 0)
            pos_y = max((screen_height - dialog_height) // 2, 0)
            dialog.geometry(f"{dialog_width}x{dialog_height}+{pos_x}+{pos_y}")

        place_dialog()
        dialog.deiconify()
        dialog.lift()
        dialog.focus_force()
        dialog.after_idle(place_dialog)
        dialog.after(80, place_dialog)

    @staticmethod
    def _format_ray_inspector_value(value) -> str:
        try:
            numeric = float(value)
        except Exception:
            text = str(value).strip()
            return text if text else "-"
        if not np.isfinite(numeric):
            return "-"
        return f"{numeric:.6g}"

    def _ray_detector_aperture_record(self, record: dict[str, object]) -> dict[str, object]:
        return detector_aperture_record_status(
            record,
            detector_surface_indices=self._scene_detector_surface_indices(),
        )

    def _ray_detector_aperture_table_values(self, record: dict[str, object]) -> tuple[str, str]:
        aperture = self._ray_detector_aperture_record(record)
        status = str(aperture.get("detector_aperture_status", "") or "").strip()
        surface = aperture.get("detector_aperture_surface", "")
        try:
            surface_text = f"S{int(surface)}"
        except Exception:
            surface_text = ""
        if status == "hit":
            label = f"Hit {surface_text}".strip()
        elif status == "miss":
            label = f"Miss {surface_text}".strip()
        elif status == "bypass":
            label = f"Bypass {surface_text}".strip()
        else:
            label = "-"
        return label, self._format_ray_inspector_value(aperture.get("detector_aperture_margin_mm", ""))

    def _trace_preview_summary(self, rays=None, bundle: SceneBundle | None = None) -> dict[str, object]:
        rays = self.last_rays if rays is None else rays
        bundle = self._last_scene_bundle if bundle is None else bundle
        trace_state = self._resolved_trace_mode()
        row_specs = self._serializable_row_specs()
        scalar_required = _requires_scalar_trace(row_specs)
        batch_capable = (not scalar_required) and hasattr(self.last_system, "BatchTrace") and hasattr(rays, "batch_push")
        backend = str(getattr(self, "_last_preview_trace_backend", "") or "")
        return trace_preview_summary(
            rays=rays,
            bundle=bundle,
            trace_state=trace_state,
            final_surface_index=max(0, len(self.rows) - 1),
            scalar_required=scalar_required,
            batch_capable=batch_capable,
            backend=backend,
        )

    def _sequential_focus_diagnostic(
        self,
        rays=None,
        trace_summary: dict[str, object] | None = None,
    ) -> dict[str, object]:
        return sequential_focus_diagnostic(
            rays=self.last_rays if rays is None else rays,
            final_surface_index=max(0, len(self.rows) - 1),
            trace_summary=trace_summary if trace_summary is not None else self._trace_preview_summary(rays),
            object_mode=self._current_object_mode(),
            field_type=self._current_field_type(),
            object_distance=self._current_object_distance(),
        )

    @staticmethod
    def _raykeeper_array(rays, seq_name: str, ray_index: int, *, dtype=float) -> np.ndarray:
        seq = getattr(rays, seq_name, ())
        if seq is None or ray_index >= len(seq):
            return np.empty(0, dtype=dtype)
        try:
            return np.asarray(seq[ray_index], dtype=dtype).ravel()
        except Exception:
            try:
                return np.asarray(seq[ray_index]).ravel()
            except Exception:
                return np.empty(0, dtype=dtype)

    @staticmethod
    def _finite_mean(values: list[float] | np.ndarray) -> float | None:
        arr = np.asarray(values, dtype=float).ravel()
        arr = arr[np.isfinite(arr)]
        if arr.size == 0:
            return None
        return float(np.mean(arr))

    @staticmethod
    def _format_percent_value(value: float | None) -> str:
        if value is None or not np.isfinite(float(value)):
            return "-"
        return f"{100.0 * float(value):.4g}%"

    def _polarization_summary(self, rays=None) -> dict[str, object]:
        rays = self.last_rays if rays is None else rays
        if rays is None:
            return {
                "total_rays": 0,
                "image_rays": 0,
                "mean_tt": None,
                "image_mean_tt": None,
                "mean_tp": None,
                "mean_ts": None,
                "mean_rp": None,
                "mean_rs": None,
                "mean_ps_transmission_split": None,
                "mean_ps_reflection_split": None,
                "coated_surface_count": 0,
                "surface_rows": [],
            }

        final_surface = max(0, len(self.rows) - 1)
        total_rays = len(getattr(rays, "SURFACE", ()) or ())
        all_tt: list[float] = []
        image_tt: list[float] = []
        all_tp: list[float] = []
        all_ts: list[float] = []
        all_rp: list[float] = []
        all_rs: list[float] = []
        trans_split: list[float] = []
        refl_split: list[float] = []
        per_surface: dict[int, dict[str, list[float]]] = {}

        for ray_index in range(total_rays):
            surface_arr = self._raykeeper_array(rays, "SURFACE", ray_index, dtype=int)
            tp_arr = self._raykeeper_array(rays, "TP", ray_index, dtype=float)
            ts_arr = self._raykeeper_array(rays, "TS", ray_index, dtype=float)
            rp_arr = self._raykeeper_array(rays, "RP", ray_index, dtype=float)
            rs_arr = self._raykeeper_array(rays, "RS", ray_index, dtype=float)
            ttbe_arr = self._raykeeper_array(rays, "TTBE", ray_index, dtype=float)
            tt_arr = self._raykeeper_array(rays, "TT", ray_index, dtype=float)

            if tt_arr.size and np.isfinite(tt_arr[-1]):
                tt_value = float(tt_arr[-1])
                all_tt.append(tt_value)
                if surface_arr.size and int(surface_arr[-1]) == final_surface:
                    image_tt.append(tt_value)

            hit_count = int(max(surface_arr.size, tp_arr.size, ts_arr.size, rp_arr.size, rs_arr.size, ttbe_arr.size))
            for hit_index in range(hit_count):
                if hit_index >= surface_arr.size:
                    continue
                surface_id = int(surface_arr[hit_index])
                bucket = per_surface.setdefault(
                    surface_id,
                    {"tp": [], "ts": [], "rp": [], "rs": [], "ttbe": []},
                )

                def _append(arr: np.ndarray, key: str, aggregate: list[float]) -> None:
                    if hit_index >= arr.size:
                        return
                    value = float(arr[hit_index])
                    if np.isfinite(value):
                        bucket[key].append(value)
                        aggregate.append(value)

                _append(tp_arr, "tp", all_tp)
                _append(ts_arr, "ts", all_ts)
                _append(rp_arr, "rp", all_rp)
                _append(rs_arr, "rs", all_rs)
                if hit_index < ttbe_arr.size and np.isfinite(float(ttbe_arr[hit_index])):
                    bucket["ttbe"].append(float(ttbe_arr[hit_index]))
                if hit_index < tp_arr.size and hit_index < ts_arr.size:
                    tp = float(tp_arr[hit_index])
                    ts = float(ts_arr[hit_index])
                    if np.isfinite(tp) and np.isfinite(ts):
                        trans_split.append(abs(tp - ts))
                if hit_index < rp_arr.size and hit_index < rs_arr.size:
                    rp = float(rp_arr[hit_index])
                    rs = float(rs_arr[hit_index])
                    if np.isfinite(rp) and np.isfinite(rs):
                        refl_split.append(abs(rp - rs))

        surface_rows: list[dict[str, object]] = []
        for surface_id in sorted(per_surface):
            bucket = per_surface[surface_id]
            name = self.rows[surface_id].name if 0 <= surface_id < len(self.rows) else f"S{surface_id}"
            surface_rows.append(
                {
                    "surface": surface_id,
                    "name": name,
                    "tp": self._finite_mean(bucket["tp"]),
                    "ts": self._finite_mean(bucket["ts"]),
                    "rp": self._finite_mean(bucket["rp"]),
                    "rs": self._finite_mean(bucket["rs"]),
                    "ttbe": self._finite_mean(bucket["ttbe"]),
                }
            )

        coated_surface_count = 0
        for row in self.rows:
            advanced = row.advanced or {}
            if any(attr in advanced for attr in ("Coating", "CoatingMet")):
                coated_surface_count += 1

        return {
            "total_rays": total_rays,
            "image_rays": len(image_tt),
            "mean_tt": self._finite_mean(all_tt),
            "image_mean_tt": self._finite_mean(image_tt),
            "mean_tp": self._finite_mean(all_tp),
            "mean_ts": self._finite_mean(all_ts),
            "mean_rp": self._finite_mean(all_rp),
            "mean_rs": self._finite_mean(all_rs),
            "mean_ps_transmission_split": self._finite_mean(trans_split),
            "mean_ps_reflection_split": self._finite_mean(refl_split),
            "coated_surface_count": coated_surface_count,
            "surface_rows": surface_rows,
        }

    def _phase2_feature_summary(self) -> dict[str, object]:
        error_rows: list[str] = []
        coating_rows: list[str] = []
        max_error_pv = 0.0
        max_error_rms = 0.0
        for index, row in enumerate(self.rows):
            advanced = row.advanced or {}
            if "Error_map" in advanced:
                label = f"S{index} {row.name}".strip()
                try:
                    _x, _y, z_arr, _spacing = _error_map_arrays(advanced["Error_map"])
                    z_arr = np.asarray(z_arr, dtype=float)
                    finite = z_arr[np.isfinite(z_arr)]
                    if finite.size:
                        pv = float(np.ptp(finite))
                        rms = float(np.sqrt(np.mean((finite - float(np.mean(finite))) ** 2)))
                        max_error_pv = max(max_error_pv, pv)
                        max_error_rms = max(max_error_rms, rms)
                        label = f"{label} (PV {pv:.4g}, RMS {rms:.4g})"
                except Exception:
                    label = f"{label} (invalid map)"
                error_rows.append(label)
            if any(attr in advanced for attr in ("Coating", "CoatingMet")):
                coating_rows.append(f"S{index} {row.name}".strip())

        source_stats = self._source_statistics()
        return {
            "source_model": source_stats.get("source_model", SOURCE_MODEL_DEFAULT),
            "source_summary": self._format_source_summary(),
            "error_map_count": len(error_rows),
            "error_map_rows": error_rows,
            "max_error_pv": max_error_pv if error_rows else None,
            "max_error_rms": max_error_rms if error_rows else None,
            "coating_count": len(coating_rows),
            "coating_rows": coating_rows,
            "metal_catalog_count": len(getattr(self, "metal_catalogs", []) or []),
        }

    @staticmethod
    def _unit_ray_frame_vector(value) -> np.ndarray | None:
        try:
            vector = np.asarray(value, dtype=float).reshape(-1)[:3]
        except Exception:
            return None
        if vector.size < 3 or not np.all(np.isfinite(vector)):
            return None
        norm = float(np.linalg.norm(vector))
        if not np.isfinite(norm) or norm <= 1e-12:
            return None
        return vector / norm

    @classmethod
    def _ray_hit_gaussian_frame_fields(cls, incoming, outgoing, normal) -> dict[str, object]:
        """Return a branch-local right-handed T/S/K frame for a traced hit."""
        incoming_unit = cls._unit_ray_frame_vector(incoming)
        outgoing_unit = cls._unit_ray_frame_vector(outgoing)
        normal_unit = cls._unit_ray_frame_vector(normal)
        k_axis = outgoing_unit if outgoing_unit is not None else incoming_unit
        if k_axis is None:
            return {
                "gb_frame_valid": False,
                "gb_incidence_deg": np.nan,
                "gb_k_l": np.nan,
                "gb_k_m": np.nan,
                "gb_k_n": np.nan,
                "gb_t_l": np.nan,
                "gb_t_m": np.nan,
                "gb_t_n": np.nan,
                "gb_s_l": np.nan,
                "gb_s_m": np.nan,
                "gb_s_n": np.nan,
            }

        incidence_deg = np.nan
        if incoming_unit is not None and normal_unit is not None:
            cos_i = float(np.clip(abs(float(np.dot(incoming_unit, normal_unit))), 0.0, 1.0))
            incidence_deg = float(np.rad2deg(np.arccos(cos_i)))

        reference = normal_unit
        if reference is None or float(np.linalg.norm(reference - (np.dot(reference, k_axis) * k_axis))) <= 1e-10:
            candidates = (
                np.asarray((0.0, 1.0, 0.0), dtype=float),
                np.asarray((1.0, 0.0, 0.0), dtype=float),
                np.asarray((0.0, 0.0, 1.0), dtype=float),
            )
            reference = max(candidates, key=lambda candidate: float(np.linalg.norm(candidate - (np.dot(candidate, k_axis) * k_axis))))

        t_axis = reference - (float(np.dot(reference, k_axis)) * k_axis)
        t_norm = float(np.linalg.norm(t_axis))
        if not np.isfinite(t_norm) or t_norm <= 1e-12:
            return {
                "gb_frame_valid": False,
                "gb_incidence_deg": incidence_deg,
                "gb_k_l": float(k_axis[0]),
                "gb_k_m": float(k_axis[1]),
                "gb_k_n": float(k_axis[2]),
                "gb_t_l": np.nan,
                "gb_t_m": np.nan,
                "gb_t_n": np.nan,
                "gb_s_l": np.nan,
                "gb_s_m": np.nan,
                "gb_s_n": np.nan,
            }
        t_axis = t_axis / t_norm
        s_axis = np.cross(k_axis, t_axis)
        s_norm = float(np.linalg.norm(s_axis))
        if not np.isfinite(s_norm) or s_norm <= 1e-12:
            return {
                "gb_frame_valid": False,
                "gb_incidence_deg": incidence_deg,
                "gb_k_l": float(k_axis[0]),
                "gb_k_m": float(k_axis[1]),
                "gb_k_n": float(k_axis[2]),
                "gb_t_l": float(t_axis[0]),
                "gb_t_m": float(t_axis[1]),
                "gb_t_n": float(t_axis[2]),
                "gb_s_l": np.nan,
                "gb_s_m": np.nan,
                "gb_s_n": np.nan,
            }
        s_axis = s_axis / s_norm
        t_axis = np.cross(s_axis, k_axis)
        t_axis = t_axis / max(float(np.linalg.norm(t_axis)), 1e-12)
        return {
            "gb_frame_valid": True,
            "gb_incidence_deg": incidence_deg,
            "gb_k_l": float(k_axis[0]),
            "gb_k_m": float(k_axis[1]),
            "gb_k_n": float(k_axis[2]),
            "gb_t_l": float(t_axis[0]),
            "gb_t_m": float(t_axis[1]),
            "gb_t_n": float(t_axis[2]),
            "gb_s_l": float(s_axis[0]),
            "gb_s_m": float(s_axis[1]),
            "gb_s_n": float(s_axis[2]),
        }

