    def export_ray_events_csv(self) -> None:
        bundle = self._last_scene_bundle
        if bundle is None:
            self._collect_ray_analysis_records()
            bundle = self._last_scene_bundle
        records = scene_bundle_ray_event_records(bundle) if bundle is not None else []
        if not records:
            messagebox.showinfo("Export Ray Events", "No canonical ray-event data to export. Click Update first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Ray Events CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=RAY_EVENT_RECORD_COLUMNS)
            writer.writeheader()
            for record in records:
                writer.writerow({column: record.get(column, "") for column in RAY_EVENT_RECORD_COLUMNS})
        self.status_var.set(f"Ray Events CSV exported: {Path(path).name}")

    def _branch_gaussian_q_input_beam(self, wavelength: float):
        if self._current_source_model() == "Gaussian beam":
            return self._current_gaussian_beam_input(wavelength)
        return default_branch_gaussian_q_beam(float(wavelength))

    def _collect_branch_gaussian_q_records(
        self,
        records: list[dict[str, object]] | None = None,
        wavelength: float | None = None,
    ) -> tuple[list[dict[str, object]], dict[str, object]]:
        ray_records = list(records if records is not None else self._collect_ray_analysis_records())
        wavelength_value = float(self._current_wavelength() if wavelength is None else wavelength)
        source_model = self._current_source_model()
        try:
            beam = self._branch_gaussian_q_input_beam(wavelength_value)
        except Exception:
            beam = default_branch_gaussian_q_beam(wavelength_value)
            source_model = ""
        return collect_branch_gaussian_q_records(
            ray_records,
            surfaces=self.rows,
            beam=beam,
            wavelength_um=wavelength_value,
            source_model=source_model,
            branch_code_for_path=lambda path: "".join(self._branch_path_selector_sequence(path)) or "primary",
            error_formatter=_short_error_message,
        )

    def _branch_gaussian_q_summary_text(self, summary: dict[str, object]) -> str:
        return branch_gaussian_q_summary_text(summary)

    def open_branch_gaussian_q_report(self) -> None:
        window = self._branch_gaussian_q_window
        if window is not None and window.winfo_exists():
            self._refresh_branch_gaussian_q_report()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.withdraw()
        window.title("Branch Gaussian Q Report")
        window.geometry("1320x620")
        window.minsize(900, 420)
        window.transient(self)
        window.protocol("WM_DELETE_WINDOW", self._close_branch_gaussian_q_report)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 0))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_branch_gaussian_q_report).pack(side="left")
        ttk.Button(toolbar, text="Copy", command=self.copy_branch_gaussian_q_report_to_clipboard).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Export CSV", command=self.export_branch_gaussian_q_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_branch_gaussian_q_report).pack(side="left", padx=(6, 0))

        self._branch_gaussian_q_summary_var = tk.StringVar(master=window, value="No trace data. Click Update first.")
        ttk.Label(
            window,
            textvariable=self._branch_gaussian_q_summary_var,
            padding=(8, 6, 8, 0),
            anchor="w",
            justify="left",
        ).grid(row=1, column=0, sticky="ew")

        frame = ttk.Frame(window, padding=8)
        frame.grid(row=2, column=0, sticky="nsew")
        frame.columnconfigure(0, weight=1)
        frame.rowconfigure(0, weight=1)
        columns = (
            "ray",
            "path",
            "step",
            "surface",
            "event",
            "note",
            "incidence",
            "n",
            "ct",
            "cs",
            "qt",
            "qs",
            "w",
            "clip",
            "stable",
        )
        table = ttk.Treeview(frame, columns=columns, show="headings", selectmode="browse")
        headings = {
            "ray": "Ray",
            "path": "Path",
            "step": "Step",
            "surface": "Surface",
            "event": "Event",
            "note": "q note",
            "incidence": "Inc [deg]",
            "n": "n0->n1",
            "ct": "Ct",
            "cs": "Cs",
            "qt": "qT [mm]",
            "qs": "qS [mm]",
            "w": "wT/wS [mm]",
            "clip": "Clip",
            "stable": "Stable",
        }
        widths = {
            "ray": 58,
            "path": 130,
            "step": 55,
            "surface": 150,
            "event": 92,
            "note": 240,
            "incidence": 78,
            "n": 80,
            "ct": 90,
            "cs": 90,
            "qt": 150,
            "qs": 150,
            "w": 120,
            "clip": 76,
            "stable": 70,
        }
        for column in columns:
            table.heading(column, text=headings[column])
            table.column(column, width=widths[column], anchor=("w" if column in {"path", "surface", "event", "note"} else "e"), stretch=column in {"path", "surface", "note"})
        table.grid(row=0, column=0, sticky="nsew")
        y_scroll = ttk.Scrollbar(frame, orient="vertical", command=table.yview)
        y_scroll.grid(row=0, column=1, sticky="ns")
        x_scroll = ttk.Scrollbar(frame, orient="horizontal", command=table.xview)
        x_scroll.grid(row=1, column=0, sticky="ew")
        table.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)

        self._branch_gaussian_q_window = window
        self._branch_gaussian_q_table = table
        self._show_centered_dialog(window)
        self._refresh_branch_gaussian_q_report()

    def _close_branch_gaussian_q_report(self) -> None:
        window = self._branch_gaussian_q_window
        self._branch_gaussian_q_window = None
        self._branch_gaussian_q_summary_var = None
        self._branch_gaussian_q_table = None
        self._branch_gaussian_q_records = []
        self._branch_gaussian_q_summary = {}
        if window is not None and window.winfo_exists():
            window.destroy()

    def _refresh_branch_gaussian_q_report_if_open(self) -> None:
        window = self._branch_gaussian_q_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_branch_gaussian_q_report()
            return
        self._refresh_branch_gaussian_q_report()

    def _refresh_branch_gaussian_q_report(self) -> None:
        table = self._branch_gaussian_q_table
        if table is None:
            return
        rows, summary = self._collect_branch_gaussian_q_records(records=self._active_ray_analysis_records())
        self._branch_gaussian_q_records = rows
        self._branch_gaussian_q_summary = summary
        table.delete(*table.get_children())
        for index, row in enumerate(rows):
            table.insert("", "end", iid=str(index), values=branch_gaussian_q_table_values(row))
        if self._branch_gaussian_q_summary_var is not None:
            self._branch_gaussian_q_summary_var.set(
                self._branch_gaussian_q_summary_text(summary)
                if rows or int(summary.get("failure_count", 0) or 0)
                else "No Gaussian q branch records. Click Update first."
            )

    def _branch_gaussian_q_report_text(self) -> str:
        rows = list(self.__dict__.get("_branch_gaussian_q_records", []) or [])
        summary = dict(self.__dict__.get("_branch_gaussian_q_summary", {}) or {})
        if not rows and not summary:
            rows, summary = self._collect_branch_gaussian_q_records(records=self._active_ray_analysis_records())
        return branch_gaussian_q_report_text(rows, summary)

    def copy_branch_gaussian_q_report_to_clipboard(self) -> None:
        try:
            text = self._branch_gaussian_q_report_text()
            ok, backend = self._copy_text_to_clipboard(text)
            self.append_debug(text)
            if ok:
                self.status_var.set(f"Branch Gaussian q report copied to clipboard ({backend}).")
            else:
                self.status_var.set("Branch Gaussian q report written to Debug; clipboard unavailable.")
        except Exception as exc:
            self.append_debug(f"Branch Gaussian q report failed: {exc}")

    def export_branch_gaussian_q_csv(self) -> None:
        rows = list(self._branch_gaussian_q_records)
        if not rows:
            rows, summary = self._collect_branch_gaussian_q_records(records=self._active_ray_analysis_records())
            self._branch_gaussian_q_records = rows
            self._branch_gaussian_q_summary = summary
        if not rows:
            messagebox.showinfo("Export Branch Gaussian Q", "No Gaussian q branch records. Click Update first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Branch Gaussian Q CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=BRANCH_GAUSSIAN_Q_CSV_COLUMNS, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(rows)
        self.status_var.set(f"Branch Gaussian q CSV exported: {Path(path).name}")

    def _surface_path_text(self, surface_ids) -> str:
        labels: list[str] = []
        for surface_id in np.asarray(surface_ids, dtype=int).ravel():
            index = int(surface_id)
            name = self.rows[index].name if 0 <= index < len(self.rows) else ""
            labels.append(f"S{index}:{name}" if name else f"S{index}")
        return " -> ".join(labels)

    def _scene_hit_to_inspector_hit(self, hit) -> dict[str, object]:
        xyz = np.asarray(getattr(hit, "point_world", (np.nan, np.nan, np.nan)), dtype=float).ravel()
        lmn = np.asarray(getattr(hit, "incoming_direction", (np.nan, np.nan, np.nan)), dtype=float).ravel()
        r_lmn = np.asarray(getattr(hit, "outgoing_direction", (np.nan, np.nan, np.nan)), dtype=float).ravel()
        s_lmn = np.asarray(getattr(hit, "surface_normal", (np.nan, np.nan, np.nan)), dtype=float).ravel()
        surface_id = getattr(hit, "surface_id", "")
        record = {
            "step": int(getattr(hit, "step", 0)),
            "branch": int(getattr(hit, "branch_id", 0)),
            "surface": "" if surface_id is None else int(surface_id),
            "event": str(getattr(hit, "interaction", "") or ""),
            "name": str(getattr(hit, "name", "") or ""),
            "glass": str(getattr(hit, "material", "") or ""),
            "x": float(xyz[0]) if xyz.size >= 1 else np.nan,
            "y": float(xyz[1]) if xyz.size >= 2 else np.nan,
            "z": float(xyz[2]) if xyz.size >= 3 else np.nan,
            "distance": getattr(hit, "distance", np.nan),
            "op": getattr(hit, "optical_path", np.nan),
            "l": float(lmn[0]) if lmn.size >= 1 else np.nan,
            "m": float(lmn[1]) if lmn.size >= 2 else np.nan,
            "n": float(lmn[2]) if lmn.size >= 3 else np.nan,
            "out_l": float(r_lmn[0]) if r_lmn.size >= 1 else np.nan,
            "out_m": float(r_lmn[1]) if r_lmn.size >= 2 else np.nan,
            "out_n": float(r_lmn[2]) if r_lmn.size >= 3 else np.nan,
            "normal_l": float(s_lmn[0]) if s_lmn.size >= 1 else np.nan,
            "normal_m": float(s_lmn[1]) if s_lmn.size >= 2 else np.nan,
            "normal_n": float(s_lmn[2]) if s_lmn.size >= 3 else np.nan,
            "n0": getattr(hit, "n0", np.nan),
            "n1": getattr(hit, "n1", np.nan),
            "rp": getattr(hit, "rp", np.nan),
            "rs": getattr(hit, "rs", np.nan),
            "tp": getattr(hit, "tp", np.nan),
            "ts": getattr(hit, "ts", np.nan),
            "ttbe": getattr(hit, "ttbe", np.nan),
            "interaction_model": str(getattr(hit, "interaction_model", "") or ""),
            "interaction_target_surface": getattr(hit, "interaction_target_surface", None),
            "interaction_in_power": getattr(hit, "interaction_in_power", np.nan),
            "interaction_coeff": getattr(hit, "interaction_coeff", np.nan),
            "interaction_out_power": getattr(hit, "interaction_out_power", np.nan),
            "interaction_loss_power": getattr(hit, "interaction_loss_power", np.nan),
            "interaction_bulk": getattr(hit, "interaction_bulk", np.nan),
        }
        record.update(self._ray_hit_gaussian_frame_fields(lmn, r_lmn, s_lmn))
        return record

    def _branch_metrics_from_hits(self, hits: list[dict[str, object]]) -> tuple[float, float, float | None]:
        distance = 0.0
        optical_path = 0.0
        transmission = None
        for hit in hits:
            try:
                value = float(hit.get("distance", np.nan))
                if np.isfinite(value):
                    distance += value
            except Exception:
                pass
            try:
                value = float(hit.get("op", np.nan))
                if np.isfinite(value):
                    optical_path += value
            except Exception:
                pass
            try:
                value = float(hit.get("ttbe", np.nan))
                if np.isfinite(value):
                    transmission = value
            except Exception:
                pass
        return distance, optical_path, transmission

    def _branch_tree_records_from_ray_records(self, ray_records: list[dict[str, object]]) -> list[dict[str, object]]:
        records: list[dict[str, object]] = []
        for ray_record in list(ray_records or []):
            grouped: dict[int, list[dict[str, object]]] = {}
            for hit in list(ray_record.get("hits", []) or []):
                try:
                    branch_id = int(hit.get("branch", 0))
                except Exception:
                    branch_id = 0
                grouped.setdefault(branch_id, []).append(hit)
            if not grouped:
                grouped[0] = []
            for branch_id, branch_hits in sorted(grouped.items()):
                surface_ids = [
                    int(hit["surface"])
                    for hit in branch_hits
                    if str(hit.get("surface", "")).strip()
                ]
                distance, optical_path, transmission = self._branch_metrics_from_hits(branch_hits)
                last_surface = int(surface_ids[-1]) if surface_ids else ray_record.get("last_surface")
                last_name = str(branch_hits[-1].get("name", "") or "") if branch_hits else str(ray_record.get("last_name", "") or "")
                records.append(
                    {
                        "ray_index": int(ray_record.get("ray_index", 0)),
                        "field_index": int(ray_record.get("field_index", 0)),
                        "branch_id": int(branch_id),
                        "branch_path": str(ray_record.get("branch_path", "") or ""),
                        "parent_branch_id": None if int(branch_id) == 0 else int(branch_id) - 1,
                        "start_step": int(min([int(hit.get("step", 0)) for hit in branch_hits] or [0])),
                        "end_step": int(max([int(hit.get("step", 0)) for hit in branch_hits] or [0])),
                        "surface_path": self._surface_path_text(surface_ids),
                        "termination": str(ray_record.get("termination", "")),
                        "termination_diagnostic": str(ray_record.get("termination_diagnostic", "") or ""),
                        "terminal_media": str(ray_record.get("terminal_media", "") or ""),
                        "terminal_index": ray_record.get("terminal_index", ""),
                        "terminal_inside_volumes": str(ray_record.get("terminal_inside_volumes", "") or ""),
                        "terminal_media_state": str(ray_record.get("terminal_media_state", "") or ""),
                        "branch_tree_diagnostic": str(ray_record.get("branch_tree_diagnostic", "") or ""),
                        "hit_count": len(branch_hits),
                        "distance": distance,
                        "op": optical_path,
                        "transmission": transmission,
                        "last_surface": last_surface,
                        "last_name": last_name,
                        "reaches_image": bool(ray_record.get("reaches_image", False)),
                        "hits": branch_hits,
                    }
                )
        return records

    def _collect_branch_tree_records(
        self,
        ray_records: list[dict[str, object]] | None = None,
    ) -> list[dict[str, object]]:
        if ray_records is not None:
            return self._branch_tree_records_from_ray_records(ray_records)
        bundle = self._last_scene_bundle
        paths = list(getattr(bundle, "ray_paths", []) or []) if bundle is not None else []
        records: list[dict[str, object]] = []
        if paths:
            for path in paths:
                path_hits = list(getattr(path, "hits", []) or [])
                path_events = list(getattr(path, "events", []) or [])
                path_surface_events = [
                    event
                    for event in path_events
                    if str(getattr(event, "event_kind", "") or "") == "surface"
                ]
                path_terminal_events = [
                    event
                    for event in path_events
                    if str(getattr(event, "event_kind", "") or "") == "terminal"
                ]
                terminal_event = path_terminal_events[-1] if path_terminal_events else None
                terminal_media = str(getattr(terminal_event, "media_out", "") or "") if terminal_event is not None else ""
                terminal_index = getattr(terminal_event, "n1", None) if terminal_event is not None else ""
                terminal_index = "" if terminal_index is None else terminal_index
                terminal_inside_volumes = (
                    str(getattr(terminal_event, "inside_volumes_after", "") or "")
                    if terminal_event is not None
                    else ""
                )
                terminal_media_state = (
                    str(getattr(terminal_event, "media_state_method", "") or "")
                    if terminal_event is not None
                    else ""
                )
                hits_by_branch: dict[int, list[dict[str, object]]] = {}
                if path_surface_events:
                    for event in path_surface_events:
                        branch_id = int(getattr(event, "branch_id", 0))
                        hits_by_branch.setdefault(branch_id, []).append(self._ray_event_to_inspector_hit(event))
                else:
                    for hit in path_hits:
                        branch_id = int(getattr(hit, "branch_id", 0))
                        hits_by_branch.setdefault(branch_id, []).append(self._scene_hit_to_inspector_hit(hit))
                branches = list(getattr(path, "branches", []) or [])
                if not branches and hits_by_branch:
                    branches = [
                        RayBranch3D(
                            branch_id=branch_id,
                            parent_branch_id=None if branch_id == 0 else max(branch_id - 1, 0),
                            start_step=int(min(int(hit.get("step", 0)) for hit in branch_hits)),
                            end_step=int(max(int(hit.get("step", 0)) for hit in branch_hits)),
                            surface_ids=np.asarray(
                                [int(hit["surface"]) for hit in branch_hits if str(hit.get("surface", "")).strip()],
                                dtype=int,
                            ),
                            termination_reason=str(getattr(path, "termination_reason", "")),
                            termination_diagnostic=str(getattr(path, "termination_diagnostic", "")),
                        )
                        for branch_id, branch_hits in sorted(hits_by_branch.items())
                    ]
                for branch in branches:
                    branch_id = int(getattr(branch, "branch_id", 0))
                    branch_hits = list(hits_by_branch.get(branch_id, []))
                    surface_ids = np.asarray(getattr(branch, "surface_ids", []), dtype=int).ravel()
                    if surface_ids.size == 0 and branch_hits:
                        surface_ids = np.asarray(
                            [int(hit["surface"]) for hit in branch_hits if str(hit.get("surface", "")).strip()],
                            dtype=int,
                        )
                    distance, optical_path, transmission = self._branch_metrics_from_hits(branch_hits)
                    last_surface = int(surface_ids[-1]) if surface_ids.size else None
                    last_name = ""
                    if last_surface is not None and 0 <= last_surface < len(self.rows):
                        last_name = self.rows[last_surface].name
                    if not last_name and branch_hits:
                        last_name = str(branch_hits[-1].get("name", "") or "")
                    records.append(
                        {
                            "ray_index": int(getattr(path, "ray_index", 0)),
                            "field_index": int(getattr(path, "field_index", 0)),
                            "branch_id": branch_id,
                            "branch_path": str(getattr(path, "branch_path", "") or getattr(path, "branch_label", "") or ""),
                            "parent_branch_id": getattr(branch, "parent_branch_id", None),
                            "start_step": int(getattr(branch, "start_step", 0)),
                            "end_step": int(getattr(branch, "end_step", 0)),
                            "surface_path": self._surface_path_text(surface_ids),
                            "termination": str(getattr(branch, "termination_reason", "") or getattr(path, "termination_reason", "")),
                            "termination_diagnostic": str(
                                getattr(branch, "termination_diagnostic", "") or getattr(path, "termination_diagnostic", "")
                            ),
                            "terminal_media": terminal_media,
                            "terminal_index": terminal_index,
                            "terminal_inside_volumes": terminal_inside_volumes,
                            "terminal_media_state": terminal_media_state,
                            "branch_tree_diagnostic": str(getattr(path, "branch_tree_diagnostic", "") or ""),
                            "hit_count": len(branch_hits),
                            "distance": distance,
                            "op": optical_path,
                            "transmission": transmission,
                            "last_surface": last_surface,
                            "last_name": last_name,
                            "reaches_image": ray_path_reaches_image_from_events(path),
                            "hits": branch_hits,
                        }
                    )
            return records

        return self._branch_tree_records_from_ray_records(self._collect_ray_analysis_records())

    def open_branch_tree_inspector(self) -> None:
        window = self._branch_tree_window
        if window is not None and window.winfo_exists():
            self._refresh_branch_tree_inspector()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.withdraw()
        window.title("Trace Path Inspector")
        window.geometry("1160x680")
        window.minsize(820, 460)
        window.transient(self)
        window.protocol("WM_DELETE_WINDOW", self._close_branch_tree_inspector)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 0))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_branch_tree_inspector).pack(side="left")
        ttk.Button(toolbar, text="Export CSV", command=self.export_branch_tree_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Open Ray", command=self._open_branch_tree_selected_ray).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_branch_tree_inspector).pack(side="left", padx=(6, 0))

        self._branch_tree_summary_var = tk.StringVar(master=window, value="No trace data. Click Update.")
        ttk.Label(
            window,
            textvariable=self._branch_tree_summary_var,
            padding=(8, 6, 8, 0),
            anchor="w",
            justify="left",
        ).grid(row=1, column=0, sticky="ew")

        panes = ttk.Panedwindow(window, orient=tk.VERTICAL)
        panes.grid(row=2, column=0, sticky="nsew", padx=8, pady=8)

        branch_frame = ttk.LabelFrame(panes, text="Ray / trace-path graph", padding=6)
        branch_frame.columnconfigure(0, weight=1)
        branch_frame.rowconfigure(0, weight=1)
        panes.add(branch_frame, weight=2)

        hit_frame = ttk.LabelFrame(panes, text="Selected path hits", padding=6)
        hit_frame.columnconfigure(0, weight=1)
        hit_frame.rowconfigure(0, weight=1)
        panes.add(hit_frame, weight=3)

        branch_columns = (
            "field",
            "parent",
            "steps",
            "surfaces",
            "termination",
            "terminal_media",
            "terminal_index",
            "terminal_inside",
            "diagnostic",
            "hits",
            "distance",
            "op",
            "ttbe",
        )
        branch_tree = ttk.Treeview(branch_frame, columns=branch_columns, show="tree headings", selectmode="browse")
        branch_tree.heading("#0", text="Ray / Path")
        branch_tree.heading("field", text="Field")
        branch_tree.heading("parent", text="Parent")
        branch_tree.heading("steps", text="Steps")
        branch_tree.heading("surfaces", text="Surface path")
        branch_tree.heading("termination", text="Termination")
        branch_tree.heading("terminal_media", text="Terminal medium")
        branch_tree.heading("terminal_index", text="Terminal n")
        branch_tree.heading("terminal_inside", text="Terminal inside")
        branch_tree.heading("diagnostic", text="Diagnostic")
        branch_tree.heading("hits", text="Hits")
        branch_tree.heading("distance", text="Dist [mm]")
        branch_tree.heading("op", text="OP [mm]")
        branch_tree.heading("ttbe", text="TTBE")
        branch_tree.column("#0", width=160, anchor="w", stretch=False)
        branch_tree.column("field", width=60, anchor="center", stretch=False)
        branch_tree.column("parent", width=70, anchor="center", stretch=False)
        branch_tree.column("steps", width=80, anchor="center", stretch=False)
        branch_tree.column("surfaces", width=320, anchor="w", stretch=True)
        branch_tree.column("termination", width=160, anchor="w", stretch=True)
        branch_tree.column("terminal_media", width=120, anchor="w", stretch=False)
        branch_tree.column("terminal_index", width=82, anchor="e", stretch=False)
        branch_tree.column("terminal_inside", width=130, anchor="w", stretch=False)
        branch_tree.column("diagnostic", width=240, anchor="w", stretch=True)
        branch_tree.column("hits", width=55, anchor="center", stretch=False)
        branch_tree.column("distance", width=90, anchor="e", stretch=False)
        branch_tree.column("op", width=90, anchor="e", stretch=False)
        branch_tree.column("ttbe", width=76, anchor="e", stretch=False)
        branch_tree.grid(row=0, column=0, sticky="nsew")
        branch_scroll = ttk.Scrollbar(branch_frame, orient="vertical", command=branch_tree.yview)
        branch_scroll.grid(row=0, column=1, sticky="ns")
        branch_tree.configure(yscrollcommand=branch_scroll.set)
        branch_tree.bind("<<TreeviewSelect>>", self._populate_branch_tree_hits, add="+")
        branch_tree.bind("<Double-1>", lambda _event: self._open_branch_tree_selected_ray(), add="+")

        hit_specs = self._ray_hit_table_specs()
        hit_columns = tuple(spec[0] for spec in hit_specs)
        hit_table = ttk.Treeview(hit_frame, columns=hit_columns, show="headings", selectmode="none")
        for column, heading, width, anchor, stretch in hit_specs:
            hit_table.heading(column, text=heading)
            hit_table.column(column, width=width, anchor=anchor, stretch=stretch)
        hit_table.grid(row=0, column=0, sticky="nsew")
        hit_scroll = ttk.Scrollbar(hit_frame, orient="vertical", command=hit_table.yview)
        hit_scroll.grid(row=0, column=1, sticky="ns")
        hit_x_scroll = ttk.Scrollbar(hit_frame, orient="horizontal", command=hit_table.xview)
        hit_x_scroll.grid(row=1, column=0, sticky="ew")
        hit_table.configure(yscrollcommand=hit_scroll.set, xscrollcommand=hit_x_scroll.set)

        self._branch_tree_window = window
        self._branch_tree_table = branch_tree
        self._branch_tree_hit_table = hit_table
        self._show_centered_dialog(window)
        self._refresh_branch_tree_inspector()

    def _close_branch_tree_inspector(self) -> None:
        window = self._branch_tree_window
        self._branch_tree_window = None
        self._branch_tree_summary_var = None
        self._branch_tree_table = None
        self._branch_tree_hit_table = None
        self._branch_tree_records = []
        if window is not None and window.winfo_exists():
            window.destroy()

    def _refresh_branch_tree_if_open(self) -> None:
        window = self._branch_tree_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_branch_tree_inspector()
            return
        self._refresh_branch_tree_inspector()

    def _refresh_branch_tree_inspector(self) -> None:
        tree = self._branch_tree_table
        hit_table = self._branch_tree_hit_table
        if tree is None or hit_table is None:
            return
        records = self._collect_branch_tree_records(ray_records=self._active_ray_analysis_records())
        self._branch_tree_records = records
        summary = self._trace_preview_summary()
        if self._branch_tree_summary_var is not None:
            if summary["total_rays"]:
                branch_count = len(records)
                self._branch_tree_summary_var.set(
                    "{requested} -> {active} | backend={backend} | rays={total} | paths={branches} | image hits={hits}/{total}".format(
                        requested=summary["requested"],
                        active=summary["active"],
                        backend=summary["backend"],
                        total=summary["total_rays"],
                        branches=branch_count,
                        hits=summary["image_hits"],
                    )
                )
                note = str(summary.get("note", "")).strip()
                if note:
                    self._branch_tree_summary_var.set(f"{self._branch_tree_summary_var.get()} | {note}")
            else:
                self._branch_tree_summary_var.set("No trace data. Click Update.")

        selected = tree.selection()
        selected_iid = selected[0] if selected else None
        tree.delete(*tree.get_children())
        hit_table.delete(*hit_table.get_children())
        records_by_ray: dict[int, list[dict[str, object]]] = {}
        for record in records:
            records_by_ray.setdefault(int(record["ray_index"]), []).append(record)
        first_branch_iid = None
        for ray_index in sorted(records_by_ray):
            branch_records = sorted(records_by_ray[ray_index], key=lambda item: int(item.get("branch_id", 0)))
            field_index = int(branch_records[0].get("field_index", 0)) if branch_records else 0
            ray_iid = f"ray:{ray_index}"
            tree.insert(
                "",
                "end",
                iid=ray_iid,
                text=f"Ray {ray_index}",
                values=(field_index, "-", "-", "-", "ray", "-", "-", "-", "-", len(branch_records), "-", "-", "-"),
                open=True,
            )
            branch_iids: dict[int, str] = {}
            for record in branch_records:
                branch_id = int(record.get("branch_id", 0))
                branch_iid = f"branch:{ray_index}:{branch_id}"
                branch_iids[branch_id] = branch_iid
                record["_tree_iid"] = branch_iid
                if first_branch_iid is None:
                    first_branch_iid = branch_iid
                parent_branch = record.get("parent_branch_id")
                parent_iid = ray_iid
                try:
                    parent_iid = branch_iids.get(int(parent_branch), ray_iid) if parent_branch is not None else ray_iid
                except Exception:
                    parent_iid = ray_iid
                branch_path = str(record.get("branch_path", "") or "").strip()
                branch_text = f"Path {branch_id}"
                if branch_path:
                    branch_text = f"{branch_text}: {branch_path}"
                tree.insert(
                    parent_iid,
                    "end",
                    iid=branch_iid,
                    text=branch_text,
                    values=(
                        int(record.get("field_index", 0)),
                        "-" if parent_branch is None else parent_branch,
                        f"{record.get('start_step', '')}-{record.get('end_step', '')}",
                        record.get("surface_path", ""),
                        record.get("termination", ""),
                        record.get("terminal_media", ""),
                        self._format_ray_inspector_value(record.get("terminal_index")),
                        record.get("terminal_inside_volumes", ""),
                        record.get("termination_diagnostic", "") or record.get("branch_tree_diagnostic", ""),
                        int(record.get("hit_count", 0)),
                        self._format_ray_inspector_value(record.get("distance")),
                        self._format_ray_inspector_value(record.get("op")),
                        self._format_ray_inspector_value(record.get("transmission")),
                    ),
                    open=True,
                )
        target_iid = selected_iid if selected_iid and tree.exists(selected_iid) else first_branch_iid
        if target_iid:
            tree.selection_set(target_iid)
            tree.focus(target_iid)
            tree.see(target_iid)
            self._populate_branch_tree_hits()

    def _branch_tree_record_for_iid(self, iid: str) -> dict[str, object] | None:
        if iid.startswith("branch:"):
            for record in self._branch_tree_records:
                if str(record.get("_tree_iid", "")) == iid:
                    return record
        return None

    def _branch_tree_selected_ray_index(self) -> int | None:
        tree = self._branch_tree_table
        if tree is None:
            return None
        selected = tree.selection()
        if not selected:
            return None
        iid = str(selected[0])
        try:
            if iid.startswith("ray:"):
                return int(iid.split(":", 1)[1])
            if iid.startswith("branch:"):
                return int(iid.split(":", 2)[1])
        except Exception:
            return None
        return None

    def _open_branch_tree_selected_ray(self) -> None:
        ray_index = self._branch_tree_selected_ray_index()
        if ray_index is None:
            return
        self._select_ray_inspector_ray(int(ray_index))

    def _populate_branch_tree_hits(self, _event=None) -> None:
        tree = self._branch_tree_table
        hit_table = self._branch_tree_hit_table
        if tree is None or hit_table is None:
            return
        hit_table.delete(*hit_table.get_children())
        selected = tree.selection()
        if not selected:
            return
        iid = str(selected[0])
        if iid.startswith("ray:"):
            try:
                ray_index = int(iid.split(":", 1)[1])
            except Exception:
                return
            hits: list[dict[str, object]] = []
            for record in self._branch_tree_records:
                if int(record.get("ray_index", -1)) == ray_index:
                    hits.extend(list(record.get("hits", []) or []))
        else:
            record = self._branch_tree_record_for_iid(iid)
            if record is None:
                return
            hits = list(record.get("hits", []) or [])
        for hit in hits:
            hit_table.insert("", "end", values=self._ray_hit_table_values(hit))

    def export_branch_tree_csv(self) -> None:
        records = list(self._branch_tree_records or self._collect_branch_tree_records(ray_records=self._active_ray_analysis_records()))
        if not records:
            messagebox.showinfo("Export Trace Path Tree", "No trace-path data to export. Click Update first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Trace Path Tree CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        columns = (
            "ray_index",
            "field_index",
            "branch_id",
            "branch_path",
            "parent_branch_id",
            "start_step",
            "end_step",
            "surface_path",
            "termination",
            "termination_diagnostic",
            "terminal_media",
            "terminal_index",
            "terminal_inside_volumes",
            "terminal_media_state",
            "branch_tree_diagnostic",
            "reaches_image",
            "hit_count",
            "branch_distance",
            "branch_op",
            "branch_transmission",
            "last_surface",
            "last_name",
            "hit_step",
            "hit_event_id",
            "hit_event_kind",
            "surface",
            "event",
            "hit_diagnostic",
            "name",
            "glass",
            "volume_id",
            "media_transition",
            "media_in",
            "media_out",
            "media_state_method",
            "media_state_diagnostic",
            "inside_volumes_before",
            "inside_volumes_after",
            "mesh_cell_id",
            "mesh_original_cell_id",
            "mesh_face_id",
            "mesh_face_match_method",
            "mesh_face_match_score",
            "mesh_face_match_warning",
            "x",
            "y",
            "z",
            "distance",
            "op",
            "l",
            "m",
            "n",
            "out_l",
            "out_m",
            "out_n",
            "normal_l",
            "normal_m",
            "normal_n",
            "gb_frame_valid",
            "gb_incidence_deg",
            "gb_k_l",
            "gb_k_m",
            "gb_k_n",
            "gb_t_l",
            "gb_t_m",
            "gb_t_n",
            "gb_s_l",
            "gb_s_m",
            "gb_s_n",
            "n0",
            "n1",
            "rp",
            "rs",
            "tp",
            "ts",
            "ttbe",
            "interaction_model",
            "interaction_target_surface",
            "interaction_in_power",
            "interaction_coeff",
            "interaction_out_power",
            "interaction_loss_power",
            "interaction_bulk",
        )
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=columns)
            writer.writeheader()
            for record in records:
                base = {
                    "ray_index": record.get("ray_index", ""),
                    "field_index": record.get("field_index", ""),
                    "branch_id": record.get("branch_id", ""),
                    "branch_path": record.get("branch_path", ""),
                    "parent_branch_id": record.get("parent_branch_id", ""),
                    "start_step": record.get("start_step", ""),
                    "end_step": record.get("end_step", ""),
                    "surface_path": record.get("surface_path", ""),
                    "termination": record.get("termination", ""),
                    "termination_diagnostic": record.get("termination_diagnostic", ""),
                    "terminal_media": record.get("terminal_media", ""),
                    "terminal_index": record.get("terminal_index", ""),
                    "terminal_inside_volumes": record.get("terminal_inside_volumes", ""),
                    "terminal_media_state": record.get("terminal_media_state", ""),
                    "branch_tree_diagnostic": record.get("branch_tree_diagnostic", ""),
                    "reaches_image": record.get("reaches_image", ""),
                    "hit_count": record.get("hit_count", ""),
                    "branch_distance": record.get("distance", ""),
                    "branch_op": record.get("op", ""),
                    "branch_transmission": record.get("transmission", ""),
                    "last_surface": record.get("last_surface", ""),
                    "last_name": record.get("last_name", ""),
                }
                hits = list(record.get("hits", []) or [])
                if not hits:
                    writer.writerow(base)
                    continue
                for hit in hits:
                    row = dict(base)
                    row.update(
                        {
                            "hit_step": hit.get("step", ""),
                            "hit_event_id": hit.get("event_id", ""),
                            "hit_event_kind": hit.get("event_kind", ""),
                            "surface": hit.get("surface", ""),
                            "event": hit.get("event", ""),
                            "hit_diagnostic": hit.get("diagnostic", ""),
                            "name": hit.get("name", ""),
                            "glass": hit.get("glass", ""),
                            "volume_id": hit.get("volume_id", ""),
                            "media_transition": hit.get("media_transition", ""),
                            "media_in": hit.get("media_in", ""),
                            "media_out": hit.get("media_out", ""),
                            "media_state_method": hit.get("media_state_method", ""),
                            "media_state_diagnostic": hit.get("media_state_diagnostic", ""),
                            "inside_volumes_before": hit.get("inside_volumes_before", ""),
                            "inside_volumes_after": hit.get("inside_volumes_after", ""),
                            "mesh_cell_id": hit.get("mesh_cell_id", ""),
                            "mesh_original_cell_id": hit.get("mesh_original_cell_id", ""),
                            "mesh_face_id": hit.get("mesh_face_id", ""),
                            "mesh_face_match_method": hit.get("mesh_face_match_method", ""),
                            "mesh_face_match_score": hit.get("mesh_face_match_score", ""),
                            "mesh_face_match_warning": hit.get("mesh_face_match_warning", ""),
                            "x": hit.get("x", ""),
                            "y": hit.get("y", ""),
                            "z": hit.get("z", ""),
                            "distance": hit.get("distance", ""),
                            "op": hit.get("op", ""),
                            "l": hit.get("l", ""),
                            "m": hit.get("m", ""),
                            "n": hit.get("n", ""),
                            "out_l": hit.get("out_l", ""),
                            "out_m": hit.get("out_m", ""),
                            "out_n": hit.get("out_n", ""),
                            "normal_l": hit.get("normal_l", ""),
                            "normal_m": hit.get("normal_m", ""),
                            "normal_n": hit.get("normal_n", ""),
                            "gb_frame_valid": hit.get("gb_frame_valid", ""),
                            "gb_incidence_deg": hit.get("gb_incidence_deg", ""),
                            "gb_k_l": hit.get("gb_k_l", ""),
                            "gb_k_m": hit.get("gb_k_m", ""),
                            "gb_k_n": hit.get("gb_k_n", ""),
                            "gb_t_l": hit.get("gb_t_l", ""),
                            "gb_t_m": hit.get("gb_t_m", ""),
                            "gb_t_n": hit.get("gb_t_n", ""),
                            "gb_s_l": hit.get("gb_s_l", ""),
                            "gb_s_m": hit.get("gb_s_m", ""),
                            "gb_s_n": hit.get("gb_s_n", ""),
                            "n0": hit.get("n0", ""),
                            "n1": hit.get("n1", ""),
                            "rp": hit.get("rp", ""),
                            "rs": hit.get("rs", ""),
                            "tp": hit.get("tp", ""),
                            "ts": hit.get("ts", ""),
                            "ttbe": hit.get("ttbe", ""),
                            "interaction_model": hit.get("interaction_model", ""),
                            "interaction_target_surface": hit.get("interaction_target_surface", ""),
                            "interaction_in_power": hit.get("interaction_in_power", ""),
                            "interaction_coeff": hit.get("interaction_coeff", ""),
                            "interaction_out_power": hit.get("interaction_out_power", ""),
                            "interaction_loss_power": hit.get("interaction_loss_power", ""),
                            "interaction_bulk": hit.get("interaction_bulk", ""),
                        }
                    )
                    writer.writerow(row)
        self.status_var.set(f"Trace Path Tree CSV exported: {Path(path).name}")

    @staticmethod
    def _safe_float(value, default: float = 0.0) -> float:
        try:
            result = float(value)
        except Exception:
            return default
        if not np.isfinite(result):
            return default
        return result

    @staticmethod
    def _safe_positive_float(value, default: float = 0.0) -> float:
        try:
            result = float(value)
        except Exception:
            return default
        if not np.isfinite(result):
            return default
        return max(result, 0.0)

    @staticmethod
    def _safe_complex(value, default: complex = complex(1.0, 0.0)) -> complex:
        try:
            result = complex(value)
        except Exception:
            return default
        if not np.isfinite(result.real) or not np.isfinite(result.imag):
            return default
        return result

    @classmethod
    def _normalize_jones_pair(cls, p_value, s_value) -> tuple[complex, complex]:
        p_component = cls._safe_complex(p_value, complex(1.0, 0.0))
        s_component = cls._safe_complex(s_value, complex(0.0, 0.0))
        norm = float(np.sqrt((abs(p_component) ** 2.0) + (abs(s_component) ** 2.0)))
        if not np.isfinite(norm) or norm <= 1e-15:
            return complex(1.0, 0.0), complex(0.0, 0.0)
        return p_component / norm, s_component / norm

    @staticmethod
    def _normalize_complex_vector(value) -> np.ndarray:
        try:
            vector = np.asarray(value, dtype=np.complex128).reshape(-1)[:3]
        except Exception:
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        if vector.size < 3:
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        if not np.all(np.isfinite(vector.real) & np.isfinite(vector.imag)):
            vector = np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        norm = float(np.sqrt(np.sum(np.abs(vector) ** 2.0)))
        if not np.isfinite(norm) or norm <= 1e-15:
            return np.asarray((1.0 + 0.0j, 0.0 + 0.0j, 0.0 + 0.0j), dtype=np.complex128)
        return vector / norm

    @staticmethod
    def _format_jones_value(value) -> str:
        try:
            component = complex(value)
        except Exception:
            return ""
        sign = "+" if component.imag >= 0.0 else "-"
        return f"{component.real:.4g}{sign}{abs(component.imag):.4g}j"

    def _branch_output_label(self, branch_path: str) -> str:
        return branch_output_label(branch_path)

    def _terminal_surface_label(self, surface_index, fallback_name: str = "") -> str:
        try:
            index = int(surface_index)
        except Exception:
            return str(fallback_name or "No terminal surface").strip()
        if not (0 <= index < len(self.rows)):
            return str(fallback_name or f"S{index}").strip()
        row = self.rows[index]
        metadata = self._element_metadata(row)
        element = self._element_key(row) or str(metadata.get("element_name", "") or "").strip()
        name = str(getattr(row, "name", "") or fallback_name or "").strip()
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)
        prefix = "Detector" if role == "Detector" or self._row_has_detector_output_metadata(row) else str(row.surface or "Surface")
        label = element or name or f"S{index}"
        return f"S{index} {prefix}: {label}"

    @staticmethod
    def _ray_termination_status_text(termination: str, last_surface, reaches_image: bool = False) -> str:
        if reaches_image or termination == "image":
            return "Image"
        try:
            surface_text = f"S{int(last_surface)}"
        except Exception:
            surface_text = ""
        if termination == "missed_image":
            return f"Missed image after {surface_text}" if surface_text else "Missed image"
        if termination == "missed_folded_image":
            return "Missed image"
        if termination == "no_next_intersection":
            return f"Continues after {surface_text}" if surface_text else "Continues"
        if termination in {"no_hit", "no_folded_display_path"}:
            return "No hit"
        if str(termination or "").startswith("stopped_at_surface_"):
            return f"Stop @ {surface_text}" if surface_text else "Stopped"
        return str(termination or "").strip() or "No hit"

    def _surface_index_is_detector(self, surface_index) -> bool:
        try:
            index = int(surface_index)
        except Exception:
            return False
        if not (0 <= index < len(self.rows)):
            return False
        row = self.rows[index]
        metadata = self._element_metadata(row)
        role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)
        if role == "Detector" or self._row_has_detector_output_metadata(row):
            return True
        return index in self._scene_detector_surface_indices()

    def _scene_detector_surface_indices(self, trace_state: dict[str, object] | None = None) -> set[int]:
        if trace_state is None:
            try:
                trace_state = self._resolved_trace_mode(system=getattr(self, "last_system", None))
            except Exception:
                trace_state = {"use_nonseq": False}
        use_nonseq = bool(trace_state.get("use_nonseq"))
        detectors: set[int] = set()
        for index, row in enumerate(getattr(self, "rows", []) or []):
            metadata = self._element_metadata(row)
            role = str(metadata.get("arm_role", ELEMENT_ARM_ROLE_DEFAULT) or ELEMENT_ARM_ROLE_DEFAULT)
            surface = str(getattr(row, "surface", "") or "").strip()
            if role == "Detector" or self._row_has_detector_output_metadata(row) or surface == "Image":
                detectors.add(int(index))
        target_index = self._current_nonseq_target_surface_index()
        if target_index is not None and 0 <= target_index < len(self.rows):
            detectors.add(int(target_index))
        if not use_nonseq and self.rows and self.rows[-1].surface == "Image":
            detectors.add(len(self.rows) - 1)
        return detectors

    def _source_illumination_target_priority(self, surface_index: int) -> int:
        if not (0 <= int(surface_index) < len(self.rows)):
            return 99
        row = self.rows[int(surface_index)]
        if self._surface_index_is_detector(surface_index):
            return 0
        if row.surface in {OBJECT_TARGET_SURFACE, DIFFUSE_OBJECT_SURFACE, "Object"}:
            return 1
        if row.surface == "Aperture":
            return 2
        return 3

    def _source_illumination_auto_target_index(self) -> int | None:
        terminal_surfaces: set[int] = set()
        hit_surfaces: set[int] = set()
        for record in self._collect_ray_analysis_records():
            try:
                terminal_index = int(record.get("last_surface"))
            except Exception:
                terminal_index = None
            if terminal_index is not None and 0 <= terminal_index < len(self.rows):
                terminal_surfaces.add(terminal_index)
            for hit in list(record.get("hits", []) or []):
                try:
                    surface_index = int(hit.get("surface"))
                except Exception:
                    continue
                if 0 <= surface_index < len(self.rows):
                    hit_surfaces.add(surface_index)

        if terminal_surfaces:
            return min(
                terminal_surfaces,
                key=lambda index: (
                    self._source_illumination_target_priority(index),
                    -index,
                ),
            )

        if hit_surfaces:
            return min(
                hit_surfaces,
                key=lambda index: (
                    self._source_illumination_target_priority(index),
                    -index,
                ),
            )

        detector_candidates = [
            index
            for index, _row in enumerate(self.rows)
            if self._surface_index_is_detector(index)
        ]
        if detector_candidates:
            return max(detector_candidates)
        return len(self.rows) - 1 if self.rows else None

    def _detector_settings_for_surface(self, surface_index) -> dict[str, object]:
        try:
            index = int(surface_index)
        except Exception:
            return _normalize_detector_settings({})
        if not (0 <= index < len(self.rows)):
            return _normalize_detector_settings({})
        return self._detector_settings(self.rows[index])

    @staticmethod
    def _single_terminal_surface_from_samples(samples: dict[str, object]) -> int | None:
        surfaces: set[int] = set()
        for surface in list(samples.get("terminal_surfaces", []) or []):
            try:
                surfaces.add(int(surface))
            except Exception:
                pass
        if len(surfaces) != 1:
            return None
        return next(iter(surfaces))

    def _detector_model_for_samples(self, samples: dict[str, object]) -> dict[str, object]:
        surface_index = self._single_terminal_surface_from_samples(samples)
        settings = self._detector_settings_for_surface(surface_index) if surface_index is not None else _normalize_detector_settings({})
        active_width = float(settings.get("active_width_mm", 0.0))
        active_height = float(settings.get("active_height_mm", 0.0))
        if surface_index is not None and 0 <= surface_index < len(self.rows):
            diameter = self._safe_positive_float(getattr(self.rows[surface_index], "diameter", 0.0), 0.0)
            if active_width <= 0.0 and diameter > 0.0:
                active_width = diameter
            if active_height <= 0.0 and diameter > 0.0:
                active_height = diameter
        return {
            "surface_index": surface_index,
            "settings": settings,
            "active_width_mm": active_width,
            "active_height_mm": active_height,
            "bins": str(settings.get("bins", "") or ""),
            "pixel_pitch_um": float(settings.get("pixel_pitch_um", 0.0)),
        }

    def _collect_branch_throughput_records(
        self,
        ray_records: list[dict[str, object]] | None = None,
    ) -> list[dict[str, object]]:
        ray_records = list(ray_records if ray_records is not None else self._collect_ray_analysis_records())
        if not ray_records:
            return []
        return self._branch_throughput_records_for_ray_records(ray_records)

    def _branch_throughput_records_for_ray_records(self, ray_records: list[dict[str, object]]) -> list[dict[str, object]]:
        if not ray_records:
            return []
        return collect_branch_throughput_records(
            ray_records,
            terminal_label_for_record=lambda record: self._terminal_surface_label(
                record.get("last_surface"),
                str(record.get("last_name", "") or ""),
            ),
            is_detector_surface=self._surface_index_is_detector,
        )

    def _source_illumination_target_choices(self) -> list[str]:
        choices = ["Auto"]
        for index, row in enumerate(self.rows):
            choices.append(f"{index}: {row.name or row.surface}")
        return choices

    def _source_illumination_target_index(self) -> int | None:
        target_var = self.__dict__.get("_source_illumination_target_var")
        value = (
            str(target_var.get()).strip()
            if target_var is not None
            else "Auto"
        )
        if value and value != "Auto":
            try:
                index = int(value.split(":", 1)[0].strip())
                if 0 <= index < len(self.rows):
                    return index
            except Exception:
                pass
        analysis_var = self.__dict__.get("analysis_surface_var")
        analysis_text = str(analysis_var.get()).strip() if analysis_var is not None else "Auto"
        if analysis_text and analysis_text != "Auto":
            try:
                analysis_index = int(analysis_text.split(":", 1)[0].strip())
                if 0 <= analysis_index < len(self.rows):
                    return analysis_index
            except Exception:
                pass
        nonseq_target_index = self._current_nonseq_target_surface_index()
        if nonseq_target_index is not None:
            return nonseq_target_index
        return self._source_illumination_auto_target_index()

    def _source_illumination_terminal_label_for_record(self, record: dict[str, object]) -> str:
        last_surface = record.get("last_surface")
        last_name = str(record.get("last_name", "") or "")
        terminal = self._terminal_surface_label(last_surface, last_name)
        termination = str(record.get("termination", "") or "").strip()
        if terminal:
            return terminal
        return termination or "No recorded hit"

    def _collect_source_illumination_records(
        self,
        target_surface_index: int | None = None,
        *,
        ray_records: list[dict[str, object]] | None = None,
    ) -> list[dict[str, object]]:
        ray_records = list(ray_records if ray_records is not None else self._collect_ray_analysis_records())
        if not ray_records:
            return []
        if target_surface_index is None:
            target_surface_index = self._source_illumination_target_index()
        try:
            target_surface_index = int(target_surface_index)
        except Exception:
            return []
        if not (0 <= target_surface_index < len(self.rows)):
            return []
        return collect_source_illumination_records(
            ray_records,
            target_surface_index,
            self.rows[target_surface_index].name if 0 <= target_surface_index < len(self.rows) else "",
            terminal_label_for_record=self._source_illumination_terminal_label_for_record,
        )

    def open_source_illumination_report(self) -> None:
        window = self._source_illumination_window
        if window is not None and window.winfo_exists():
            self._refresh_source_illumination_report()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.title("Source Illumination Report")
        window.geometry("1160x600")
        window.protocol("WM_DELETE_WINDOW", self._close_source_illumination_report)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 4))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Label(toolbar, text="Target").pack(side="left")
        default_target = "Auto"
        self._source_illumination_target_var = tk.StringVar(master=window, value=default_target)
        self._source_illumination_target_menu = ttk.Combobox(
            toolbar,
            textvariable=self._source_illumination_target_var,
            values=self._source_illumination_target_choices(),
            state="readonly",
            width=28,
        )
        self._source_illumination_target_menu.pack(side="left", padx=(6, 10))
        self._source_illumination_target_menu.bind("<<ComboboxSelected>>", lambda _event: self._refresh_source_illumination_report(), add="+")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_source_illumination_report).pack(side="left")
        ttk.Button(toolbar, text="Copy", command=self.copy_source_illumination_report_to_clipboard).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Export CSV", command=self.export_source_illumination_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_source_illumination_report).pack(side="left", padx=(6, 0))

        self._source_illumination_summary_var = tk.StringVar(master=window, value="No trace data. Click Update.")
        ttk.Label(window, textvariable=self._source_illumination_summary_var, padding=(8, 0, 8, 4)).grid(row=1, column=0, sticky="ew")

        columns = SOURCE_ILLUMINATION_TABLE_COLUMNS
        table = ttk.Treeview(window, columns=columns, show="headings", selectmode="browse")
        for column in columns:
            table.heading(column, text=SOURCE_ILLUMINATION_TABLE_HEADINGS[column])
            table.column(
                column,
                width=SOURCE_ILLUMINATION_TABLE_WIDTHS[column],
                anchor=("e" if column not in {"source", "model", "loss", "centroid", "span"} else "w"),
            )
        table.grid(row=2, column=0, sticky="nsew", padx=8, pady=(0, 8))
        yscroll = ttk.Scrollbar(window, orient="vertical", command=table.yview)
        yscroll.grid(row=2, column=1, sticky="ns", pady=(0, 8))
        table.configure(yscrollcommand=yscroll.set)
        table.bind("<<TreeviewSelect>>", lambda _event: self._refresh_source_illumination_detail(), add="+")

        detail_frame = ttk.LabelFrame(window, text="Selected source details", padding=(8, 6, 8, 8))
        detail_frame.grid(row=3, column=0, columnspan=2, sticky="ew", padx=8, pady=(0, 8))
        detail_frame.columnconfigure(0, weight=1)
        detail_text = tk.Text(detail_frame, height=6, wrap="word", borderwidth=0, relief="flat")
        detail_text.grid(row=0, column=0, sticky="ew")
        detail_text.configure(state="disabled")
        self._bind_text_copy_shortcuts(detail_text)
        self._bind_text_context_menu(detail_text)

        self._source_illumination_window = window
        self._source_illumination_table = table
        self._source_illumination_detail_text = detail_text
        self._refresh_source_illumination_report()

    def _close_source_illumination_report(self) -> None:
        window = self._source_illumination_window
        self._source_illumination_window = None
        self._source_illumination_summary_var = None
        self._source_illumination_target_var = None
        self._source_illumination_target_menu = None
        self._source_illumination_table = None
        self._source_illumination_detail_text = None
        self._source_illumination_records = []
        if window is not None:
            try:
                window.destroy()
            except tk.TclError:
                pass

    def _set_source_illumination_detail_text(self, text: str) -> None:
        widget = self._source_illumination_detail_text
        if widget is None:
            return
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", str(text or ""))
        widget.configure(state="disabled")

    def _source_illumination_record_detail_text(self, record: dict[str, object]) -> str:
        return source_illumination_record_detail_text(record)

    def _refresh_source_illumination_detail(self) -> None:
        table = self._source_illumination_table
        if table is None:
            return
        selection = table.selection()
        if not selection:
            self._set_source_illumination_detail_text("Select a source row to inspect loss and footprint diagnostics.")
            return
        try:
            index = int(str(selection[0]).rsplit("_", 1)[-1])
        except Exception:
            index = -1
        if not (0 <= index < len(self._source_illumination_records)):
            self._set_source_illumination_detail_text("Selected source record is no longer available. Click Refresh.")
            return
        self._set_source_illumination_detail_text(
            self._source_illumination_record_detail_text(self._source_illumination_records[index])
        )

    def _refresh_source_illumination_report_if_open(self) -> None:
        window = self._source_illumination_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_source_illumination_report()
            return
        self._refresh_source_illumination_report()

    def _refresh_source_illumination_report(self) -> None:
        table = self._source_illumination_table
        if table is None:
            return
        if self._source_illumination_target_menu is not None:
            self._source_illumination_target_menu["values"] = self._source_illumination_target_choices()
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(
            target_index,
            ray_records=self._active_ray_analysis_records(),
        )
        self._source_illumination_records = records
        table.delete(*table.get_children())
        target_label = "None" if target_index is None else f"S{target_index}: {self.rows[target_index].name}"
        if self._source_illumination_summary_var is not None:
            self._source_illumination_summary_var.set(source_illumination_summary_text(records, target_label))
        for index, record in enumerate(records):
            table.insert(
                "",
                "end",
                iid=f"source_illum_{index}",
                values=source_illumination_table_values(record),
            )
        if records:
            first_iid = "source_illum_0"
            table.selection_set(first_iid)
            table.focus(first_iid)
            self._refresh_source_illumination_detail()
        else:
            self._set_source_illumination_detail_text(
                "No source illumination records. Click Update, then choose a target surface or leave Target as Auto."
            )

    def _source_illumination_report_text(self) -> str:
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(
            target_index,
            ray_records=self._active_ray_analysis_records(),
        )
        if target_index is None:
            target_label = "None"
        else:
            target_label = f"S{target_index}: {self.rows[target_index].name}"
        return source_illumination_report_text(records, target_label)

    def copy_source_illumination_report_to_clipboard(self) -> None:
        try:
            text = self._source_illumination_report_text()
            ok, backend = self._copy_text_to_clipboard(text)
            self.append_debug(text)
            if ok:
                self.status_var.set(f"Source illumination report copied to clipboard ({backend}).")
            else:
                self.status_var.set("Source illumination report written to Debug; clipboard unavailable.")
        except Exception as exc:
            self.append_debug(f"Source illumination report failed: {exc}")

    def export_source_illumination_csv(self) -> None:
        target_index = self._source_illumination_target_index()
        records = self._collect_source_illumination_records(
            target_index,
            ray_records=self._active_ray_analysis_records(),
        )
        if not records:
            messagebox.showinfo("Export Source Illumination", "No source illumination records. Click Update first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Source Illumination CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        write_source_illumination_csv(path, records)
        self.status_var.set(f"Source illumination CSV exported: {Path(path).name}")

    def open_branch_throughput_report(self) -> None:
        window = self._branch_throughput_window
        if window is not None and window.winfo_exists():
            self._refresh_branch_throughput_report()
            window.deiconify()
            window.lift()
            window.focus_force()
            return

        window = tk.Toplevel(self)
        window.withdraw()
        window.title("Path Throughput Report")
        window.geometry("1120x560")
        window.minsize(820, 360)
        window.transient(self)
        window.protocol("WM_DELETE_WINDOW", self._close_branch_throughput_report)
        window.columnconfigure(0, weight=1)
        window.rowconfigure(2, weight=1)

        toolbar = ttk.Frame(window, padding=(8, 8, 8, 0))
        toolbar.grid(row=0, column=0, sticky="ew")
        ttk.Button(toolbar, text="Refresh", command=self._refresh_branch_throughput_report).pack(side="left")
        ttk.Button(toolbar, text="Copy", command=self.copy_branch_throughput_report_to_clipboard).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Export CSV", command=self.export_branch_throughput_csv).pack(side="left", padx=(6, 0))
        ttk.Button(toolbar, text="Close", command=self._close_branch_throughput_report).pack(side="left", padx=(6, 0))
        ttk.Label(toolbar, text="Filter").pack(side="left", padx=(18, 4))
        self._branch_throughput_filter_var = tk.StringVar(master=window, value=ANALYSIS_PATH_FILTER_DEFAULT)
        self._branch_throughput_filter_menu = ttk.Combobox(
            toolbar,
            textvariable=self._branch_throughput_filter_var,
            state="readonly",
            width=36,
            values=[ANALYSIS_PATH_FILTER_DEFAULT],
        )
        self._branch_throughput_filter_menu.pack(side="left")
        self._branch_throughput_filter_menu.bind("<<ComboboxSelected>>", lambda _event: self._refresh_branch_throughput_report(), add="+")

        self._branch_throughput_summary_var = tk.StringVar(master=window, value="No trace data. Click Update.")
        ttk.Label(
            window,
            textvariable=self._branch_throughput_summary_var,
            padding=(8, 6, 8, 0),
            anchor="w",
            justify="left",
        ).grid(row=1, column=0, sticky="ew")

        table_frame = ttk.Frame(window, padding=8)
        table_frame.grid(row=2, column=0, sticky="nsew")
        table_frame.columnconfigure(0, weight=1)
        table_frame.rowconfigure(0, weight=1)
        columns = BRANCH_THROUGHPUT_TABLE_COLUMNS
        table = ttk.Treeview(table_frame, columns=columns, show="headings", selectmode="browse")
        for column, heading in BRANCH_THROUGHPUT_TABLE_HEADINGS.items():
            table.heading(column, text=heading)
        for column, width, anchor in BRANCH_THROUGHPUT_TABLE_LAYOUT:
            table.column(column, width=width, anchor=anchor, stretch=column in {"terminal", "path"})
        table.grid(row=0, column=0, sticky="nsew")
        y_scroll = ttk.Scrollbar(table_frame, orient="vertical", command=table.yview)
        y_scroll.grid(row=0, column=1, sticky="ns")
        x_scroll = ttk.Scrollbar(table_frame, orient="horizontal", command=table.xview)
        x_scroll.grid(row=1, column=0, sticky="ew")
        table.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)

        self._branch_throughput_window = window
        self._branch_throughput_table = table
        self._show_centered_dialog(window)
        self._refresh_branch_throughput_report()

    def _close_branch_throughput_report(self) -> None:
        window = self._branch_throughput_window
        self._branch_throughput_window = None
        self._branch_throughput_summary_var = None
        self._branch_throughput_filter_var = None
        self._branch_throughput_filter_menu = None
        self._branch_throughput_table = None
        self._branch_throughput_records = []
        if window is not None and window.winfo_exists():
            window.destroy()

    def _refresh_branch_throughput_report_if_open(self) -> None:
        window = self._branch_throughput_window
        if window is None:
            return
        if not window.winfo_exists():
            self._close_branch_throughput_report()
            return
        self._refresh_branch_throughput_report()

    @staticmethod
    def _branch_throughput_filter_choices(records: list[dict[str, object]]) -> list[str]:
        return branch_throughput_filter_choices(records)

    @staticmethod
    def _branch_throughput_filter_matches(record: dict[str, object], filter_text: str) -> bool:
        return branch_throughput_filter_matches(record, filter_text)

    def _filtered_branch_throughput_records(self, records: list[dict[str, object]]) -> list[dict[str, object]]:
        filter_var = self.__dict__.get("_branch_throughput_filter_var")
        filter_text = (
            filter_var.get()
            if filter_var is not None
            else ANALYSIS_PATH_FILTER_DEFAULT
        )
        return filtered_branch_throughput_records(records, filter_text)

    def _current_analysis_branch_filter(self) -> str:
        value = ANALYSIS_PATH_FILTER_DEFAULT
        var = getattr(self, "analysis_branch_filter_var", None)
        if var is not None:
            try:
                value = _normalize_path_filter_label(var.get())
            except Exception:
                value = ANALYSIS_PATH_FILTER_DEFAULT
        return _normalize_path_filter_label(value)

    def _current_coherent_sum_mode(self) -> str:
        value = COHERENT_SUM_MODE_DEFAULT
        var = getattr(self, "coherent_sum_mode_var", None)
        if var is not None:
            try:
                value = _normalize_coherent_sum_mode(var.get())
            except Exception:
                value = COHERENT_SUM_MODE_DEFAULT
        return _normalize_coherent_sum_mode(value)

    @staticmethod
    def _normalize_ray_display_mode(value) -> str:
        text = str(value or RAY_DISPLAY_DEFAULT).strip()
        aliases = {
            "all": RAY_DISPLAY_ALL,
            "all traced rays": RAY_DISPLAY_ALL,
            "all rays": RAY_DISPLAY_ALL,
            "detector": RAY_DISPLAY_DETECTOR,
            "detector hits": RAY_DISPLAY_DETECTOR,
            "image": RAY_DISPLAY_DETECTOR,
            "image hits": RAY_DISPLAY_DETECTOR,
            "missed": RAY_DISPLAY_MISSED_DETECTOR,
            "missed detector": RAY_DISPLAY_MISSED_DETECTOR,
            "missed detectors": RAY_DISPLAY_MISSED_DETECTOR,
            "missed image": RAY_DISPLAY_MISSED_DETECTOR,
            "absorbed": RAY_DISPLAY_ABSORBED,
            "absorber": RAY_DISPLAY_ABSORBED,
            "escaped": RAY_DISPLAY_ESCAPED,
            "escape": RAY_DISPLAY_ESCAPED,
            "stopped": RAY_DISPLAY_STOPPED,
            "diagnostic": RAY_DISPLAY_STOPPED,
            "stopped / diagnostic": RAY_DISPLAY_STOPPED,
            "split": RAY_DISPLAY_SPLITTER,
            "splitter": RAY_DISPLAY_SPLITTER,
            "beam splitter": RAY_DISPLAY_SPLITTER,
            "beam-splitter": RAY_DISPLAY_SPLITTER,
            "beam-splitter paths": RAY_DISPLAY_SPLITTER,
            "hide direct": RAY_DISPLAY_SPLITTER,
            "hide direct source rays": RAY_DISPLAY_SPLITTER,
            "useful": RAY_DISPLAY_SPLITTER,
            "useful paths": RAY_DISPLAY_SPLITTER,
        }
        return aliases.get(text.lower(), text if text in RAY_DISPLAY_VALUES else RAY_DISPLAY_DEFAULT)

    def _current_ray_display_mode(self) -> str:
        var = getattr(self, "ray_display_mode_var", None)
        if var is None:
            return RAY_DISPLAY_DEFAULT
        try:
            return self._normalize_ray_display_mode(var.get())
        except Exception:
            return RAY_DISPLAY_DEFAULT

    def _refresh_analysis_branch_choices(self) -> None:
        menu = getattr(self, "analysis_branch_filter_menu", None)
        var = getattr(self, "analysis_branch_filter_var", None)
        if menu is None or var is None:
            return
        records = self._collect_branch_throughput_records(ray_records=self._active_ray_analysis_records())
        choices = self._branch_throughput_filter_choices(records)
        current = self._current_analysis_branch_filter()
        if current not in choices and not records:
            choices.append(current)
        menu["values"] = choices
        if current not in choices:
            var.set(ANALYSIS_PATH_FILTER_DEFAULT)

    def _ray_record_branch_filter_matches(self, record: dict[str, object], filter_text: str) -> bool:
        branch_path = str(record.get("branch_path", "") or "").strip()
        last_surface = record.get("last_surface")
        terminal = self._terminal_surface_label(last_surface, str(record.get("last_name", "") or ""))
        pseudo_record = {
            "output": self._branch_output_label(branch_path),
            "branch_code": "".join(self._branch_path_selector_sequence(branch_path)) or "primary",
            "terminal": terminal,
        }
        return self._branch_throughput_filter_matches(pseudo_record, filter_text)

    def _record_terminal_hit_local_xy(self, system, record: dict[str, object]) -> tuple[float, float, str]:
        hits = list(record.get("hits", []) or [])
        if not hits:
            return (np.nan, np.nan, "world")
        hit = hits[-1]
        try:
            surface_index = int(record.get("last_surface"))
        except Exception:
            surface_index = -1
        return self._hit_local_xy(system, surface_index, hit)

    def _hit_local_xy(self, system, surface_index: int, hit: dict[str, object]) -> tuple[float, float, str]:
        try:
            world = np.asarray(
                [
                    float(hit.get("x", np.nan)),
                    float(hit.get("y", np.nan)),
                    float(hit.get("z", np.nan)),
                    1.0,
                ],
                dtype=float,
            )
        except Exception:
            return (np.nan, np.nan, "world")
        if not np.all(np.isfinite(world[:3])):
            return (np.nan, np.nan, "world")
        transforms = self._system_transform_list(system)
        if transforms is not None and 0 <= surface_index < len(transforms):
            try:
                transform = np.asarray(transforms[surface_index], dtype=float)
                local = np.linalg.inv(transform) @ world
                if np.all(np.isfinite(local[:2])):
                    return (float(local[0]), float(local[1]), "local")
            except Exception:
                pass
        return (float(world[0]), float(world[1]), "world")

    def _source_illumination_hit_samples(
        self,
        system,
        target_surface_index: int | None = None,
        *,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        if target_surface_index is None:
            target_surface_index = self._source_illumination_target_index()
        try:
            target_surface_index = int(target_surface_index)
        except Exception:
            return empty_source_illumination_samples()
        if not (0 <= target_surface_index < len(self.rows)):
            return empty_source_illumination_samples()
        source_records = list(ray_records if ray_records is not None else self._collect_ray_analysis_records())
        diagnostic_records = self._collect_source_illumination_records(
            target_surface_index,
            ray_records=source_records,
        )
        return source_illumination_hit_samples_from_records(
            source_records,
            target_surface_index,
            self.rows[target_surface_index].name,
            hit_xy_for_hit=lambda hit: self._hit_local_xy(system, target_surface_index, hit),
            diagnostic_records=diagnostic_records,
        )

    def _source_illumination_target_model(self, samples: dict[str, object]) -> dict[str, object]:
        target_index = samples.get("target_surface")
        model: dict[str, object] = {
            "target_surface": target_index,
            "is_detector": self._surface_index_is_detector(target_index),
        }
        if not bool(model["is_detector"]):
            return model
        settings = self._detector_settings_for_surface(target_index)
        model["active_width_mm"] = float(settings.get("active_width_mm", 0.0) or 0.0)
        model["active_height_mm"] = float(settings.get("active_height_mm", 0.0) or 0.0)
        try:
            model["diameter_mm"] = self._safe_positive_float(getattr(self.rows[int(target_index)], "diameter", 0.0), 0.0)
        except Exception:
            model["diameter_mm"] = 0.0
        return model

    def _source_illumination_map_extent(
        self,
        samples: dict[str, object],
        x_values: np.ndarray,
        y_values: np.ndarray,
    ) -> tuple[float, float, float, float]:
        return source_illumination_map_extent(samples, x_values, y_values, self._source_illumination_target_model(samples))

    def _source_illumination_map_data(
        self,
        system,
        target_surface_index: int | None = None,
        *,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        samples = self._source_illumination_hit_samples(system, target_surface_index, ray_records=ray_records)
        return source_illumination_map_data_from_samples(
            samples,
            target_model=self._source_illumination_target_model(samples),
        )

    def _plot_source_illumination_map_analysis(
        self,
        analysis_ax,
        system,
        *,
        ray_records: list[dict[str, object]] | None = None,
    ) -> None:
        target_index = self._source_illumination_target_index()
        data = self._source_illumination_map_data(system, target_index, ray_records=ray_records)
        samples = dict(data["samples"])
        x_values = np.asarray(data["x_values"], dtype=float)
        density = np.asarray(data["density"], dtype=float)
        extent = list(data["extent"])
        image = analysis_ax.imshow(density, origin="lower", extent=extent, cmap="magma", aspect="auto")
        source_ids = list(data.get("source_ids", []) or [])
        colors = self._field_colors(max(1, len(set(source_ids))))
        color_by_source = {source_id: colors[index % len(colors)] for index, source_id in enumerate(sorted(set(source_ids)))}
        for centroid in list(data.get("source_centroids", []) or []):
            source_id = str(centroid.get("source_id", ""))
            analysis_ax.scatter(
                [float(centroid.get("x_mm", 0.0) or 0.0)],
                [float(centroid.get("y_mm", 0.0) or 0.0)],
                s=42,
                color=color_by_source[source_id],
                edgecolors="white",
                linewidths=0.8,
                label=str(centroid.get("source_name", "") or source_id),
                zorder=5,
            )
        if len(set(source_ids)) > 1:
            analysis_ax.legend(loc="upper right", fontsize=7, title="Source centroid")
        coordinate_label = str(data.get("coordinate_label", "target local"))
        target_label = (
            f"S{int(samples['target_surface'])}: {samples.get('target_name', '')}"
            if samples.get("target_surface") is not None
            else "target"
        )
        input_power = float(samples.get("input_power", 0.0) or 0.0)
        hit_power = float(samples.get("hit_power", 0.0) or 0.0)
        throughput = hit_power / input_power if input_power > 0.0 else np.nan
        hit_rays = int(samples.get("hit_rays", 0) or 0)
        launched_rays = int(samples.get("launched_rays", 0) or 0)
        missed_rays = int(samples.get("missed_rays", 0) or 0)
        loss_summary = str(samples.get("loss_summary", "") or "None")
        analysis_ax.set_title(f"Source Illumination Map | {target_label}")
        analysis_ax.set_xlabel(f"X [{coordinate_label}, mm]")
        analysis_ax.set_ylabel(f"Y [{coordinate_label}, mm]")
        analysis_ax.set_box_aspect(0.72)
        analysis_ax.grid(False)
        self.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04, label="Relative hit power density")
        analysis_ax.text(
            0.02,
            0.98,
            (
                f"sources={int(samples.get('source_count', 0) or 0)} | events={x_values.size}\n"
                f"rays hit={hit_rays}/{launched_rays}, missed={missed_rays}\n"
                f"power throughput={self._format_percent_value(throughput)}"
                + (f"\nloss: {loss_summary}" if missed_rays > 0 and loss_summary != "None" else "")
            ),
            transform=analysis_ax.transAxes,
            ha="left",
            va="top",
            fontsize=7.5,
            bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.82, "pad": 3},
        )
        self.append_debug(
            f"Source illumination map ok: target={target_label}, events={x_values.size}, "
            f"sources={samples.get('source_count')}, throughput={throughput:.6g}"
        )

    def _branch_detector_spot_samples(
        self,
        system,
        filter_text: str,
        *,
        require_detector: bool = False,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        source_records = list(ray_records if ray_records is not None else self._collect_ray_analysis_records())
        ray_records = [
            record
            for record in source_records
            if self._ray_record_branch_filter_matches(record, filter_text)
        ]
        if not ray_records:
            return {
                "x": np.asarray([]),
                "y": np.asarray([]),
                "weights": np.asarray([]),
                "terminals": [],
                "terminal_surfaces": [],
                "coord": "local",
                "used_detector_only": False,
                "matched_ray_count": 0,
                "analysis_sources": [],
            }

        detector_records = [
            record for record in ray_records if self._surface_index_is_detector(record.get("last_surface"))
        ]
        if require_detector and not detector_records:
            return {
                "x": np.asarray([]),
                "y": np.asarray([]),
                "weights": np.asarray([]),
                "terminals": [
                    self._terminal_surface_label(record.get("last_surface"), str(record.get("last_name", "") or ""))
                    for record in ray_records
                ],
                "terminal_surfaces": [record.get("last_surface") for record in ray_records],
                "coord": "local",
                "used_detector_only": False,
                "matched_ray_count": len(ray_records),
                "analysis_sources": [str(record.get("analysis_source", "") or "") for record in ray_records],
            }
        samples = detector_records if detector_records else ray_records
        x_values: list[float] = []
        y_values: list[float] = []
        weights: list[float] = []
        terminals: list[str] = []
        terminal_surfaces: list[object] = []
        analysis_sources: list[str] = []
        coord_modes: set[str] = set()
        for record in samples:
            x_value, y_value, coord_mode = self._record_terminal_hit_local_xy(system, record)
            if not np.isfinite(x_value) or not np.isfinite(y_value):
                continue
            branch_power = self._safe_positive_float(record.get("branch_power"), np.nan)
            if not np.isfinite(branch_power):
                branch_power = self._safe_positive_float(record.get("transmission"), 1.0)
            source_weight = self._safe_positive_float(record.get("source_weight"), 1.0)
            source_power = self._safe_positive_float(record.get("source_power"), 1.0)
            x_values.append(float(x_value))
            y_values.append(float(y_value))
            weights.append(float(max(branch_power * source_weight * source_power, 0.0)))
            terminals.append(
                self._terminal_surface_label(record.get("last_surface"), str(record.get("last_name", "") or ""))
            )
            terminal_surfaces.append(record.get("last_surface"))
            analysis_sources.append(str(record.get("analysis_source", "") or ""))
            coord_modes.add(coord_mode)

        coord = "local" if coord_modes == {"local"} else "world"
        return {
            "x": np.asarray(x_values, dtype=float),
            "y": np.asarray(y_values, dtype=float),
            "weights": np.asarray(weights, dtype=float),
            "terminals": terminals,
            "terminal_surfaces": terminal_surfaces,
            "coord": coord,
            "used_detector_only": bool(detector_records),
            "matched_ray_count": len(ray_records),
            "analysis_sources": analysis_sources,
        }

    def _plot_branch_detector_spot_analysis(
        self,
        analysis_ax,
        system,
        mode: str,
        ray_records: list[dict[str, object]] | None = None,
    ) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path Spot" if mode == "spot" else "Path RMS", 1, False)
        samples = self._branch_detector_spot_samples(system, filter_text, ray_records=ray_records)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        y_values = np.asarray(samples.get("y", np.asarray([])), dtype=float)
        weights = np.asarray(samples.get("weights", np.asarray([])), dtype=float)
        if x_values.size == 0 or y_values.size == 0:
            analysis_ax.text(
                0.5,
                0.5,
                f"No detector hit data for\n{filter_text}",
                ha="center",
                va="center",
            )
            analysis_ax.set_axis_off()
            self.append_debug(f"Path {mode} analysis: no detector hit data for filter={filter_text}")
            return

        spot_mode = self._current_spot_view_mode()
        center_weights = np.maximum(weights, 1e-12) if weights.size == x_values.size else None
        center_x = (
            float(np.average(x_values, weights=center_weights))
            if center_weights is not None
            else float(np.mean(x_values))
        )
        center_y = (
            float(np.average(y_values, weights=center_weights))
            if center_weights is not None
            else float(np.mean(y_values))
        )
        if spot_mode == "Absolute":
            plot_x = x_values
            plot_y = y_values
        else:
            plot_x = x_values - center_x
            plot_y = y_values - center_y

        radii = np.sqrt((x_values - center_x) ** 2 + (y_values - center_y) ** 2)
        if weights.size == radii.size and float(np.sum(weights)) > 0.0:
            rms = float(np.sqrt(np.average(radii * radii, weights=np.maximum(weights, 0.0))))
        else:
            rms = float(np.sqrt(np.mean(radii * radii)))
        coordinate_label = "detector local" if samples.get("coord") == "local" else "world"

        if mode == "rms":
            bins = min(max(5, int(np.sqrt(max(len(radii), 1)))), 24)
            analysis_ax.hist(
                radii,
                bins=bins,
                weights=weights if weights.size == radii.size else None,
                color="#2563eb",
                edgecolor="white",
            )
            analysis_ax.set_title(f"Path Spot Radius | RMS={rms:.4g} mm")
            analysis_ax.set_xlabel("Radius from weighted centroid [mm]")
            analysis_ax.set_ylabel("Power-weighted count" if weights.size == radii.size else "Count")
            analysis_ax.set_box_aspect(0.52)
            analysis_ax.grid(True, axis="y", alpha=0.2)
        else:
            marker_sizes = np.full(plot_x.shape, 22.0, dtype=float)
            max_weight = float(np.nanmax(weights)) if weights.size == plot_x.size else 0.0
            if max_weight > 0.0:
                marker_sizes = 14.0 + 38.0 * np.sqrt(np.clip(weights / max_weight, 0.0, 1.0))
            scatter = analysis_ax.scatter(
                plot_x,
                plot_y,
                s=marker_sizes,
                c=weights if weights.size == plot_x.size else "#c0392b",
                cmap="viridis",
                alpha=0.82,
                edgecolors="#111827",
                linewidths=0.25,
            )
            if max_weight > 0.0:
                self.figure.colorbar(scatter, ax=analysis_ax, fraction=0.046, pad=0.04, label="Relative path power")
            analysis_ax.axhline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            analysis_ax.axvline(0.0, color="#2c3e50", linewidth=0.6, alpha=0.5)
            title_suffix = "Absolute" if spot_mode == "Absolute" else "Centroid Referenced"
            analysis_ax.set_title(f"Path Detector Spot ({title_suffix})")
            analysis_ax.set_xlabel(f"X [{coordinate_label}, mm]")
            analysis_ax.set_ylabel(f"Y [{coordinate_label}, mm]")
            self._apply_equal_spot_axis_scaling(analysis_ax, plot_x, plot_y)
            analysis_ax.grid(True, alpha=0.2)

        terminal_count = len(set(samples.get("terminals", []) or []))
        analysis_ax.text(
            0.02,
            0.98,
            f"{filter_text}\nrays={x_values.size}/{int(samples.get('matched_ray_count', x_values.size) or x_values.size)} | terminals={terminal_count}",
            transform=analysis_ax.transAxes,
            ha="left",
            va="top",
            fontsize=7.5,
            bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
        )
        self.append_debug(
            f"Path {mode} analysis ok: filter={filter_text}, rays={x_values.size}, "
            f"terminals={terminal_count}, rms={rms:.6g}, coord={coordinate_label}"
        )

    def _detector_map_extent(self, samples: dict[str, object], x_values: np.ndarray, y_values: np.ndarray) -> tuple[float, float, float, float]:
        return detector_map_extent(samples, x_values, y_values, self._detector_model_for_samples(samples))

    def _branch_detector_map_data(
        self,
        system,
        filter_text: str | None = None,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        filter_text = self._current_analysis_branch_filter() if filter_text is None else _normalize_path_filter_label(filter_text)
        samples = self._branch_detector_spot_samples(system, filter_text, require_detector=True, ray_records=ray_records)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        detector_model = self._detector_model_for_samples(samples)
        bins = self._current_detector_bin_count(int(x_values.size), coherent=False, detector_model=detector_model)
        empty_message = (
            f"No detector hits for {filter_text}. DetMap needs rays that terminate on a Detector row. "
            "Try Layouts -> Beam Splitters / Folds -> Beam Splitter Two Path Doublets, "
            "Michelson Interferometer (Interferogram), Mach-Zehnder Interferometer (Interferogram), "
            "or Twyman-Green Interferometer (Interferogram); click Update; then choose a detector "
            "Analysis path such as Output: Detector output port or a Terminal: ... Detector entry."
        )
        return detector_map_data_from_samples(
            samples,
            filter_text,
            bins=bins,
            detector_model=detector_model,
            empty_message=empty_message,
        )

    def _branch_detector_psf_data(
        self,
        system,
        filter_text: str | None = None,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        filter_text = self._current_analysis_branch_filter() if filter_text is None else _normalize_path_filter_label(filter_text)
        samples = self._branch_detector_spot_samples(system, filter_text, require_detector=True, ray_records=ray_records)
        x_values = np.asarray(samples.get("x", np.asarray([])), dtype=float)
        detector_model = self._detector_model_for_samples(samples)
        bins = self._current_detector_bin_count(int(x_values.size), coherent=False, detector_model=detector_model)
        return branch_detector_psf_data_from_samples(
            samples,
            filter_text,
            bins=bins,
            detector_model=detector_model,
        )

    def _plot_branch_detector_psf_analysis(
        self,
        analysis_ax,
        system,
        wavelength: float,
        ray_records: list[dict[str, object]] | None = None,
    ) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path PSF", 1, False)
        try:
            data = self._branch_detector_psf_data(system, filter_text, ray_records=ray_records)
            hist = np.asarray(data["hist"], dtype=float)
            x_edges = np.asarray(data["x_edges"], dtype=float)
            y_edges = np.asarray(data["y_edges"], dtype=float)
            display = hist.T / max(float(data["peak_power"]), 1e-15)
            image = analysis_ax.imshow(
                display,
                origin="lower",
                extent=[float(x_edges[0]), float(x_edges[-1]), float(y_edges[0]), float(y_edges[-1])],
                interpolation="nearest",
                aspect="equal",
                cmap="inferno",
                vmin=0.0,
                vmax=1.0,
            )
            centered_x = np.asarray(data["centered_x"], dtype=float)
            centered_y = np.asarray(data["centered_y"], dtype=float)
            if centered_x.size <= 400:
                analysis_ax.scatter(centered_x, centered_y, s=6, c="white", alpha=0.45, linewidths=0.0)
            analysis_ax.set_title(f"Path Detector PSF  |  {wavelength:.4g} um")
            analysis_ax.set_xlabel(f"X [{data['coordinate_label']}, centroid mm]")
            analysis_ax.set_ylabel(f"Y [{data['coordinate_label']}, centroid mm]")
            analysis_ax.set_box_aspect(0.62)
            cbar = analysis_ax.figure.colorbar(image, ax=analysis_ax, fraction=0.046, pad=0.04)
            cbar.set_label("Normalized power")
            analysis_ax.text(
                0.02,
                0.98,
                f"{filter_text}\n{data['terminal_label']}\nrays={centered_x.size} | bins={int(data['bins'])}x{int(data['bins'])}\n"
                f"power={float(data['total_power']):.6g}",
                transform=analysis_ax.transAxes,
                ha="left",
                va="top",
                fontsize=7.5,
                bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
            )
            self.append_debug(
                f"Path PSF ok: filter={filter_text}, terminal={data['terminal_label']}, "
                f"rays={centered_x.size}, bins={int(data['bins'])}, power={float(data['total_power']):.6g}"
            )
        except Exception as exc:
            analysis_ax.text(0.5, 0.5, str(exc), ha="center", va="center")
            analysis_ax.set_axis_off()
            self.append_debug(f"Path PSF unavailable: {exc}")

    def _branch_detector_mtf_data(
        self,
        system,
        filter_text: str | None = None,
        ray_records: list[dict[str, object]] | None = None,
    ) -> dict[str, object]:
        return branch_detector_mtf_data_from_psf(
            self._branch_detector_psf_data(system, filter_text, ray_records=ray_records)
        )

    def _plot_branch_detector_mtf_analysis(
        self,
        analysis_ax,
        system,
        wavelength: float,
        ray_records: list[dict[str, object]] | None = None,
    ) -> None:
        filter_text = self._current_analysis_branch_filter()
        self._set_analysis_parallel_status("Path MTF", 1, False)
        try:
            data = self._branch_detector_mtf_data(system, filter_text, ray_records=ray_records)
            plot_freq = np.asarray(data["plot_freq"], dtype=float)
            plot_tan = np.asarray(data["plot_tan"], dtype=float)
            plot_sag = np.asarray(data["plot_sag"], dtype=float)
            plot_avg = np.asarray(data["plot_avg"], dtype=float)
            target_freq = self._current_mtf_frequency()
            mtf_mode = self._operand_mtf_mode("MTF @ freq")
            if mtf_mode == "tangential":
                selected_curve = plot_tan
                selected_label = "Tangential"
            elif mtf_mode == "sagittal":
                selected_curve = plot_sag
                selected_label = "Sagittal"
            else:
                selected_curve = plot_avg
                selected_label = "Average"
            selected_value = float(np.interp(target_freq, plot_freq, selected_curve, left=selected_curve[0], right=selected_curve[-1]))

            analysis_ax.plot(plot_freq, plot_tan, color="#2563eb", linewidth=1.4, label="Tangential")
            analysis_ax.plot(plot_freq, plot_sag, color="#dc2626", linewidth=1.2, linestyle=(0, (6, 3)), label="Sagittal")
            if mtf_mode == "average":
                analysis_ax.plot(plot_freq, plot_avg, color="#111827", linewidth=1.0, linestyle=(0, (2, 2)), label="Average")
            analysis_ax.axvline(target_freq, color="#475569", linewidth=0.9, linestyle=(0, (2, 2)), alpha=0.8)
            analysis_ax.set_title(f"Path Detector MTF  |  {wavelength:.4g} um")
            analysis_ax.set_xlabel("Spatial frequency [cycles/mm]")
            analysis_ax.set_ylabel("MTF")
            analysis_ax.set_ylim(0.0, 1.05)
            x_max = max(float(plot_freq[-1]), max(10.0, target_freq * 1.2))
            analysis_ax.set_xlim(0.0, x_max)
            analysis_ax.set_box_aspect(0.62)
            analysis_ax.grid(True, alpha=0.2)
            analysis_ax.legend(loc="best", fontsize=7)
            analysis_ax.text(
                0.02,
                0.98,
                f"{filter_text}\n{data['terminal_label']}\n{selected_label} @ {target_freq:.3g} cy/mm = {selected_value:.4g}\n"
                f"rays={len(data['x_values'])} | bins={int(data['bins'])}x{int(data['bins'])}",
                transform=analysis_ax.transAxes,
                ha="left",
                va="top",
                fontsize=7.5,
                bbox={"facecolor": "white", "edgecolor": "#cbd5e1", "alpha": 0.78, "pad": 3},
            )
            self.append_debug(
                f"Path MTF ok: filter={filter_text}, terminal={data['terminal_label']}, "
                f"rays={len(data['x_values'])}, bins={int(data['bins'])}, target={target_freq:.6g}, value={selected_value:.6g}"
            )
        except Exception as exc:
            analysis_ax.text(0.5, 0.5, str(exc), ha="center", va="center")
            analysis_ax.set_axis_off()
            self.append_debug(f"Path MTF unavailable: {exc}")

    @staticmethod
    def _branch_psf_csv_columns() -> tuple[str, ...]:
        return BRANCH_DETECTOR_PSF_CSV_COLUMNS

    def _branch_detector_psf_csv_rows(self, data: dict[str, object]) -> list[dict[str, object]]:
        return list(iter_branch_detector_psf_csv_rows(data))

    @staticmethod
    def _branch_mtf_csv_columns() -> tuple[str, ...]:
        return BRANCH_DETECTOR_MTF_CSV_COLUMNS

    def _branch_detector_mtf_csv_rows(
        self,
        data: dict[str, object],
        *,
        target_freq: float | None = None,
        mtf_mode: str | None = None,
    ) -> list[dict[str, object]]:
        target = float(self._current_mtf_frequency() if target_freq is None else target_freq)
        mode = str(self._operand_mtf_mode("MTF @ freq") if mtf_mode is None else mtf_mode).strip().lower()
        return list(iter_branch_detector_mtf_csv_rows(data, target_freq=target, mtf_mode=mode))

    def export_branch_psf_csv(self) -> None:
        if self.last_system is None or self.last_rays is None:
            messagebox.showinfo(
                "Export Path PSF CSV",
                "No path PSF trace data. Click Update first, then choose an Analysis path.",
                parent=self,
            )
            return
        try:
            ray_records = self._ray_analysis_records_for_trace(system=self.last_system, rays=self.last_rays)
            data = self._branch_detector_psf_data(self.last_system, ray_records=ray_records)
            rows = self._branch_detector_psf_csv_rows(data)
        except Exception as exc:
            messagebox.showinfo("Export Path PSF CSV", str(exc), parent=self)
            return

        path = filedialog.asksaveasfilename(
            title="Export Path PSF CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        write_branch_detector_psf_csv(path, data)
        self.status_var.set(f"Path PSF CSV exported: {Path(path).name}")
        self.append_debug(
            f"Path PSF CSV exported: {path} | filter={data['filter_text']}, terminal={data['terminal_label']}, "
            f"rays={len(data['x_values'])}, bins={int(data['bins'])}, rows={len(rows)}"
        )

