    def _reset_debug_log(self) -> None:
        try:
            DEBUG_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
            DEBUG_LOG_PATH.write_text("", encoding="utf-8")
        except Exception:
            pass

    def _append_debug_log(self, line: str) -> None:
        try:
            with DEBUG_LOG_PATH.open("a", encoding="utf-8") as fh:
                fh.write(line + "\n")
        except Exception:
            pass

    def append_progress(self, message: str) -> None:
        if not message:
            return
        self.progress_text.insert("end", message.rstrip() + "\n")
        self.progress_text.see("end")
        self.update_idletasks()

    def _begin_analysis_progress(self, label: str) -> None:
        if self.optimization_running:
            return
        self.progress_spinner_var.set("...")
        self.progress_percent_var.set("working")
        self.progress_bar_var.set(0.0)
        self.append_progress(f"{label} started.")

    def _update_analysis_progress(self, label: str, done: int | None = None, total: int | None = None) -> None:
        if self.optimization_running:
            return
        frames = ("|", "/", "-", "\\")
        self.progress_spinner_var.set(frames[self._spinner_phase % len(frames)])
        self._spinner_phase += 1
        if done is not None and total is not None and total > 0:
            percent = max(0.0, min(100.0, (done / total) * 100.0))
            self.progress_percent_var.set(f"{int(percent)}% ({done}/{total})")
            self.progress_bar_var.set(percent)
        else:
            self.progress_percent_var.set(label)
        self.update_idletasks()

    def _finish_analysis_progress(self, label: str, success: bool = True) -> None:
        if self.optimization_running:
            return
        self.progress_spinner_var.set("ok" if success else "err")
        self.progress_percent_var.set("100%" if success else "failed")
        self.progress_bar_var.set(100.0 if success else 0.0)
        self.append_progress(f"{label} {'completed' if success else 'failed'}.")

    def _set_analysis_parallel_status(self, label: str, workers: int = 1, parallel_capable: bool = False) -> None:
        self._last_analysis_label = str(label)
        self._last_analysis_workers = max(1, int(workers))
        self._last_analysis_parallel_capable = bool(parallel_capable)
        self._last_analysis_accelerator = "CPU"

    def _set_analysis_accelerator(self, label: str) -> None:
        self._last_analysis_accelerator = str(label)

    def _analysis_parallel_summary(self) -> str:
        workers = max(1, int(self._last_analysis_workers))
        if workers <= 1:
            return "workers: 1"
        if self._last_analysis_parallel_capable:
            return f"workers: {workers} (parallel)"
        return f"workers: {workers}"

    def _analysis_compute_summary(self) -> str:
        return f"{self._analysis_parallel_summary()} | {self._last_analysis_accelerator}"

    def _report_compute_backends(self) -> None:
        if self._gpu_backend_reported:
            return
        self._gpu_backend_reported = True
        backend_pref = os.getenv("KRAKEN_POSTPROC_BACKEND", "auto").strip().lower()
        if backend_pref not in {"auto", "torch", "cupy", "cpu"}:
            backend_pref = "auto"
        self.append_debug(f"Post-processing backend preference: {backend_pref}")

        torch = _optional_torch()
        if torch is None:
            self.append_debug("Torch backend: unavailable.")
        else:
            try:
                if bool(torch.cuda.is_available()):
                    self.append_debug(f"Torch backend: CUDA available ({torch.cuda.device_count()} device(s)).")
                else:
                    self.append_debug("Torch backend: installed, CUDA not available.")
            except Exception as exc:
                self.append_debug(f"Torch backend: probe failed: {exc}")

        cp = _optional_cupy()
        if cp is None:
            self.append_debug("GPU backend: CuPy unavailable, PSF/MTF post-processing will use CPU.")
            return
        try:
            device_count = int(cp.cuda.runtime.getDeviceCount())
        except Exception:
            device_count = 0
        if device_count > 0:
            self.append_debug(f"GPU backend: CuPy available, detected {device_count} CUDA device(s).")
        else:
            self.append_debug("GPU backend: CuPy import succeeded, but no CUDA devices were detected.")

    def _update_progress_indicators(self) -> None:
        if not self.optimization_running or self.optimization_context is None:
            self.progress_spinner_var.set("idle")
            self.progress_percent_var.set("0%")
            self.progress_bar_var.set(0.0)
            return
        done = int(self.optimization_context.get("generation_done", 0))
        total = max(1, int(self.optimization_context.get("generations_total", 1)))
        percent = max(0.0, min(100.0, (done / total) * 100.0))
        self.progress_percent_var.set(f"{int(percent)}% ({done}/{total})")
        self.progress_bar_var.set(percent)

    @staticmethod
    def _pick_image_plane_data(rays):
        try:
            X, Y, Z, L, M, N = rays.pick(-1, coordinates="local")
            if np.asarray(X).size:
                return X, Y, Z, L, M, N
        except Exception:
            pass
        return rays.pick(-1)

    def _build_analysis_rays(
        self,
        system,
        wavelength: float,
        sample_count: int | None = None,
        pattern: str = "hexapolar",
        *,
        surface_index: int | None = None,
        aperture_type: str | None = None,
        aperture_value: float | None = None,
        field_type: str | None = None,
        field_x: float | None = None,
        field_y: float | None = None,
    ):
        rays = Kos.raykeeper(system)
        random_source_bundle = self._build_random_source_bundle(sample_count)
        if random_source_bundle is not None:
            Kos.TraceLoop(*random_source_bundle, wavelength, rays, clean=1)
            return rays
        pupil = Kos.PupilCalc(
            system,
            self._analysis_surface_index() if surface_index is None else int(surface_index),
            wavelength,
            self._current_aperture_type() if aperture_type is None else str(aperture_type),
            self._current_aperture_value() if aperture_value is None else float(aperture_value),
        )
        pupil.Samp = max(2, int(sample_count if sample_count is not None else self._current_ray_count()))
        pupil.Ptype = self._current_analysis_pupil_pattern(pattern) if pattern == "hexapolar" else pattern

        clean = 1
        resolved_field_type = field_type or ("angle" if self._current_object_mode() == "Infinity" else "height")
        resolved_field_x = 0.0 if field_x is None else float(field_x)
        resolved_field_y = field_y
        if resolved_field_type == "angle":
            pupil.FieldType = "angle"
            field_values = (
                [float(resolved_field_y)]
                if resolved_field_y is not None
                else self._sample_field_values(self._current_field_angle_deg())
            )
            for value in field_values:
                pupil.FieldX = resolved_field_x
                pupil.FieldY = float(value)
                x, y, z, L, M, N = self._pupil_pattern_bundle(pupil)
                Kos.TraceLoop(x, y, z, L, M, N, wavelength, rays, clean=clean)
                clean = 0
        else:
            pupil.FieldType = "height"
            field_values = (
                [float(resolved_field_y)]
                if resolved_field_y is not None
                else self._sample_field_values(self._current_field_height())
            )
            for value in field_values:
                pupil.FieldX = resolved_field_x
                pupil.FieldY = float(value)
                x, y, z, L, M, N = self._pupil_pattern_bundle(pupil)
                Kos.TraceLoop(x, y, z, L, M, N, wavelength, rays, clean=clean)
                clean = 0
        return rays

    def _serializable_row_specs(self) -> list[dict]:
        return self._serializable_specs_for_rows(self.rows)

    def _serializable_specs_for_rows(self, rows: list[SurfaceRow]) -> list[dict]:
        metal_catalogs = _normalize_metal_catalog_specs(getattr(self, "metal_catalogs", []))
        return surface_rows_to_specs(rows, metal_catalogs=metal_catalogs)

    def _mtf_worker_count(self, ray_count: int) -> int:
        cpu_total = max(1, int(os.cpu_count() or 1))
        if ray_count <= 1 or cpu_total <= 1:
            return 1
        optimization_workers_var = self.__dict__.get("optimization_workers_var")
        if optimization_workers_var is not None:
            selected = optimization_workers_var.get().strip()
            if selected and selected.lower() != "auto":
                try:
                    parsed = int(selected)
                    if parsed > 0:
                        return self._cap_analysis_worker_count(max(1, min(parsed, cpu_total, ray_count)))
                except ValueError:
                    pass
        if ray_count < 2048:
            return 1
        auto_workers = self._optimization_worker_count()
        requested = max(1, min(auto_workers, cpu_total, ray_count, max(1, ray_count // 2048)))
        return self._cap_analysis_worker_count(requested)

    def _optimization_worker_count(self) -> int:
        cpu_total = max(1, int(os.cpu_count() or 1))
        optimization_workers_var = self.__dict__.get("optimization_workers_var")
        if optimization_workers_var is not None:
            selected = optimization_workers_var.get().strip()
            if selected and selected.lower() != "auto":
                try:
                    parsed = int(selected)
                    if parsed > 0:
                        return self._cap_analysis_worker_count(max(1, min(parsed, cpu_total)))
                except ValueError:
                    pass
        configured = os.getenv("KRAKEN_OPT_WORKERS", "").strip()
        if configured:
            try:
                parsed = int(configured)
                if parsed > 0:
                    return self._cap_analysis_worker_count(max(1, min(parsed, cpu_total)))
            except ValueError:
                pass
        requested = 1 if cpu_total <= 1 else max(2, cpu_total - 1)
        return self._cap_analysis_worker_count(requested)

    def _optimization_parallel_enabled(self) -> bool:
        parallel_pref = os.getenv("KRAKEN_OPT_PARALLEL", "1").strip().lower()
        return parallel_pref not in {"0", "false", "off", "no"}

    def _optimization_preflight_messages(
        self,
        merit: MeritFunction | None,
        variables: list[OpticalVariable] | None,
        optimization_workers: int,
        parallel_enabled: bool,
    ) -> tuple[bool, list[str]]:
        backend_ok, backend_message = probe_pygmo_backend()
        messages = [
            ("Optimization backend available: " if backend_ok else "Optimization backend unavailable: ")
            + backend_message
        ]
        if merit is not None and variables is not None:
            messages.append(
                "Optimization preflight: "
                f"variables={len(variables)}, operands={len(merit.operands)}, "
                f"workers={max(1, int(optimization_workers))}."
            )
            has_mtf_operand = any(isinstance(operand, MTFAtFrequencyOperand) for operand in merit.operands)
            if has_mtf_operand and int(optimization_workers) > 1:
                messages.append(
                    "Optimization preflight: MTF operands use internal MTF chunk workers "
                    "instead of pygmo mp_bfe."
                )
            elif parallel_enabled and int(optimization_workers) > 1:
                messages.append("Optimization preflight: pygmo mp_bfe parallel population evaluation is enabled.")
            elif not parallel_enabled:
                messages.append(
                    "Optimization preflight: KRAKEN_OPT_PARALLEL disables "
                    "pygmo mp_bfe parallel evaluation."
                )
        return backend_ok, messages

    def check_optimization_backend(self) -> None:
        parallel_enabled = self._optimization_parallel_enabled()
        optimization_workers = self._optimization_worker_count() if parallel_enabled else 1
        ok, messages = self._optimization_preflight_messages(None, None, optimization_workers, parallel_enabled)
        for message in messages:
            self.append_progress(message)
        if ok:
            self.status_var.set("Optimization backend available.")
        else:
            self.status_var.set("Optimization backend unavailable.")

    @staticmethod
    def _available_memory_bytes() -> int:
        if os.name == "posix":
            try:
                with open("/proc/meminfo", "r", encoding="utf-8") as handle:
                    for line in handle:
                        if line.startswith("MemAvailable:"):
                            parts = line.split()
                            if len(parts) >= 2:
                                return max(0, int(parts[1])) * 1024
            except Exception:
                pass
        return 0

    def _cap_analysis_worker_count(self, requested: int) -> int:
        requested = max(1, int(requested))
        available = self._available_memory_bytes()
        if available <= 0:
            return requested
        reserve_mb = max(1024, int(os.getenv("KRAKEN_ANALYSIS_RESERVE_MB", "2048") or 2048))
        per_worker_mb = max(128, int(os.getenv("KRAKEN_ANALYSIS_WORKER_MB", "768") or 768))
        usable = max(0, available - reserve_mb * 1024 * 1024)
        memory_limited = max(1, usable // (per_worker_mb * 1024 * 1024)) if usable > 0 else 1
        return max(1, min(requested, int(memory_limited)))

    def _ensure_analysis_executor(self, worker_count: int) -> ProcessPoolExecutor | None:
        worker_count = self._cap_analysis_worker_count(max(1, int(worker_count)))
        if worker_count <= 1:
            return None
        analysis_executor = self.__dict__.get("_analysis_executor")
        analysis_executor_workers = int(self.__dict__.get("_analysis_executor_workers", 0) or 0)
        if analysis_executor is not None and analysis_executor_workers == worker_count:
            return analysis_executor
        self._shutdown_analysis_executor()
        mp_context = None
        if os.name == "posix":
            try:
                mp_context = mp.get_context("spawn")
            except Exception:
                mp_context = None
        if mp_context is not None:
            self._analysis_executor = ProcessPoolExecutor(max_workers=worker_count, mp_context=mp_context)
        else:
            self._analysis_executor = ProcessPoolExecutor(max_workers=worker_count)
        self._analysis_executor_workers = worker_count
        return self._analysis_executor

    def _shutdown_analysis_executor(self) -> None:
        analysis_executor = self.__dict__.get("_analysis_executor")
        if analysis_executor is not None:
            processes = list(getattr(analysis_executor, "_processes", {}).values())
            try:
                analysis_executor.shutdown(wait=False, cancel_futures=True)
            except Exception:
                pass
            for process in processes:
                if process is None:
                    continue
                try:
                    if process.is_alive():
                        process.terminate()
                except Exception:
                    pass
            deadline = time.monotonic() + 0.5
            for process in processes:
                if process is None:
                    continue
                try:
                    remaining = max(0.0, deadline - time.monotonic())
                    process.join(timeout=remaining)
                except Exception:
                    pass
            for process in processes:
                if process is None:
                    continue
                try:
                    if process.is_alive():
                        process.kill()
                except Exception:
                    pass
                try:
                    process.join(timeout=0.1)
                except Exception:
                    pass
            self._analysis_executor = None
            self._analysis_executor_workers = 0

    @staticmethod
    def _terminate_process_group(pid: int, *, force: bool = False) -> None:
        if pid <= 0 or os.name != "posix":
            return
        signals = (signal.SIGTERM, signal.SIGKILL) if force else (signal.SIGTERM,)
        for sig in signals:
            try:
                os.killpg(pid, sig)
            except ProcessLookupError:
                return
            except Exception:
                break
            if sig == signal.SIGTERM:
                time.sleep(0.05)

    def _shutdown_optimization_worker(self, force: bool = False) -> None:
        if self._optimization_stop_event is not None:
            try:
                self._optimization_stop_event.set()
            except Exception:
                pass
        process = self._optimization_process
        if process is not None:
            try:
                process.join(timeout=0.15)
            except Exception:
                pass
            try:
                if force and process.is_alive():
                    self._terminate_process_group(int(process.pid or 0), force=True)
            except Exception:
                pass
            try:
                if process.is_alive():
                    process.join(timeout=0.15)
            except Exception:
                pass
            try:
                if not process.is_alive():
                    process.close()
            except Exception:
                pass
        queue = self._optimization_queue
        if queue is not None:
            try:
                queue.close()
            except Exception:
                pass
        self._optimization_process = None
        self._optimization_queue = None
        self._optimization_stop_event = None

    def _trace_pattern_chunks_parallel(
        self,
        wavelength: float,
        bundles: list[tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]],
    ) -> tuple[np.ndarray, np.ndarray, int]:
        total_rays = int(sum(len(np.asarray(bundle[0])) for bundle in bundles))
        worker_count = self._mtf_worker_count(total_rays)
        if worker_count <= 1:
            x_parts: list[np.ndarray] = []
            y_parts: list[np.ndarray] = []
            row_specs = self._serializable_row_specs()
            for bundle in bundles:
                x_local, y_local = _trace_analysis_chunk(row_specs, wavelength, *bundle)
                if x_local.size:
                    x_parts.append(x_local)
                    y_parts.append(y_local)
            if not x_parts:
                return np.asarray([], dtype=float), np.asarray([], dtype=float), 1
            return np.concatenate(x_parts), np.concatenate(y_parts), 1

        row_specs = self._serializable_row_specs()
        futures = []
        x_parts = []
        y_parts = []
        executor = self._ensure_analysis_executor(worker_count)
        if executor is None:
            return np.asarray([], dtype=float), np.asarray([], dtype=float), 1
        try:
            chunk_specs = []
            for bundle in bundles:
                ray_total = len(np.asarray(bundle[0]))
                if ray_total == 0:
                    continue
                indices = np.array_split(np.arange(ray_total), worker_count)
                for chunk in indices:
                    if chunk.size == 0:
                        continue
                    chunk_bundle = tuple(np.asarray(values)[chunk] for values in bundle)
                    futures.append(executor.submit(_trace_analysis_chunk, row_specs, wavelength, *chunk_bundle))
                    chunk_specs.append(chunk_bundle)
            for future, chunk_bundle in zip(futures, chunk_specs):
                try:
                    x_local, y_local = future.result()
                except Exception:
                    x_local, y_local = _trace_analysis_chunk(row_specs, wavelength, *chunk_bundle)
                if x_local.size:
                    x_parts.append(x_local)
                    y_parts.append(y_local)
        finally:
            self._shutdown_analysis_executor()
        if not x_parts:
            return np.asarray([], dtype=float), np.asarray([], dtype=float), worker_count
        return np.concatenate(x_parts), np.concatenate(y_parts), worker_count

    def _trace_pattern_chunks_parallel_full(
        self,
        wavelength: float,
        bundles: list[tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]],
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, int]:
        total_rays = int(sum(len(np.asarray(bundle[0])) for bundle in bundles))
        worker_count = self._mtf_worker_count(total_rays)
        if worker_count <= 1:
            parts = [[] for _ in range(6)]
            row_specs = self._serializable_row_specs()
            for bundle in bundles:
                outputs = _trace_analysis_chunk_full(row_specs, wavelength, *bundle)
                if outputs[0].size:
                    for idx, arr in enumerate(outputs):
                        parts[idx].append(arr)
            if not parts[0]:
                empty = np.asarray([], dtype=float)
                return empty, empty, empty, empty, empty, empty, 1
            merged = [np.concatenate(group) for group in parts]
            return (*merged, 1)

        row_specs = self._serializable_row_specs()
        futures = []
        parts = [[] for _ in range(6)]
        executor = self._ensure_analysis_executor(worker_count)
        if executor is None:
            empty = np.asarray([], dtype=float)
            return empty, empty, empty, empty, empty, empty, 1
        try:
            chunk_specs = []
            for bundle in bundles:
                ray_total = len(np.asarray(bundle[0]))
                if ray_total == 0:
                    continue
                indices = np.array_split(np.arange(ray_total), worker_count)
                for chunk in indices:
                    if chunk.size == 0:
                        continue
                    chunk_bundle = tuple(np.asarray(values)[chunk] for values in bundle)
                    futures.append(executor.submit(_trace_analysis_chunk_full, row_specs, wavelength, *chunk_bundle))
                    chunk_specs.append(chunk_bundle)
            for future, chunk_bundle in zip(futures, chunk_specs):
                try:
                    outputs = future.result()
                except Exception:
                    outputs = _trace_analysis_chunk_full(row_specs, wavelength, *chunk_bundle)
                if outputs[0].size:
                    for idx, arr in enumerate(outputs):
                        parts[idx].append(arr)
        finally:
            self._shutdown_analysis_executor()
        if not parts[0]:
            empty = np.asarray([], dtype=float)
            return empty, empty, empty, empty, empty, empty, worker_count
        merged = [np.concatenate(group) for group in parts]
        return (*merged, worker_count)

    def _compute_diffraction_mtf_sample(
        self,
        system,
        *,
        wavelength: float,
        surface_index: int,
        aperture_type: str,
        aperture_value: float,
        field_type: str,
        field_x: float,
        field_y: float,
    ) -> dict[str, object]:
        def _diffraction_limited_result(pupil, method: str) -> dict[str, object]:
            focal = max(0.01, abs(float(getattr(pupil, "EFFL", 0.0))))
            diameter = max(0.01, 2.0 * float(getattr(pupil, "RadPupInp", 1.0)))
            cutoff = diameter / max(float(wavelength) * 1e-3 * focal, 1e-12)
            freq = np.linspace(0.0, max(cutoff, 1e-9), 256)
            nu = np.clip(freq / max(cutoff, 1e-12), 0.0, 1.0)
            mtf = (2.0 / np.pi) * (
                np.arccos(nu) - nu * np.sqrt(np.clip(1.0 - nu * nu, 0.0, 1.0))
            )
            return {
                "plot_freq": np.asarray(freq, dtype=float),
                "plot_tan": np.asarray(mtf, dtype=float),
                "plot_sag": np.asarray(mtf, dtype=float),
                "method": method,
                "worker_count": 1,
                "accelerator": "CPU",
                "sample_count": 0,
                "used_terms": 0,
                "phase_method": method,
            }

        def _sanitize_phase_arrays(px, py, phase):
            px = np.asarray(px, dtype=float)
            py = np.asarray(py, dtype=float)
            phase = np.asarray(phase, dtype=float)
            finite = np.isfinite(px) & np.isfinite(py) & np.isfinite(phase)
            return px[finite], py[finite], phase[finite]

        def _phase_is_degenerate(px: np.ndarray, py: np.ndarray) -> bool:
            if px.size < 6:
                return True
            unique_x = np.unique(np.round(px, 10)).size
            unique_y = np.unique(np.round(py, 10)).size
            return unique_x <= 1 or unique_y <= 1

        pupil = Kos.PupilCalc(
            system,
            int(surface_index),
            float(wavelength),
            str(aperture_type),
            float(aperture_value),
        )
        pupil.Samp = max(11, min(21, self._current_ray_count()))
        pupil.Ptype = "hexapolar"
        pupil.FieldType = str(field_type)
        pupil.FieldX = float(field_x)
        pupil.FieldY = float(field_y)
        if any(row.surface == "Thin Lens" for row in self.rows):
            return _diffraction_limited_result(pupil, "Ideal Diffraction")
        phase_method = "Phase2" if str(field_type).strip().lower() == "height" else "Phase"
        if phase_method == "Phase2":
            capture = io.StringIO()
            with redirect_stdout(capture), redirect_stderr(capture):
                px, py, phase, _p2v = Kos.Phase2(pupil)
            phase2_log = capture.getvalue().strip()
            if phase2_log:
                self.append_debug(phase2_log)
            px, py, phase = _sanitize_phase_arrays(px, py, phase)
        else:
            px, py, phase, _p2v = Kos.Phase(pupil)
            px, py, phase = _sanitize_phase_arrays(px, py, phase)
            if _phase_is_degenerate(px, py):
                capture = io.StringIO()
                with redirect_stdout(capture), redirect_stderr(capture):
                    px, py, phase, _p2v = Kos.Phase2(pupil)
                phase2_log = capture.getvalue().strip()
                if phase2_log:
                    self.append_debug(phase2_log)
                px, py, phase = _sanitize_phase_arrays(px, py, phase)
                phase_method = "Phase2"
        if _phase_is_degenerate(px, py):
            raise RuntimeError("Degenerate pupil sample from Phase/Phase2")
        if px.size < 6:
            raise RuntimeError("Not enough finite pupil samples for MTF fitting")
        phase_ptv = float(np.ptp(phase)) if phase.size else 0.0
        phase_peak = float(np.max(np.abs(phase))) if phase.size else 0.0
        if phase_ptv <= 1e-14 and phase_peak <= 1e-14:
            raise RuntimeError(f"Flat phase map from {phase_method}")

        zcoef = None
        used_terms = None
        last_error = None
        for term_count in (15, 10, 6, 4):
            if px.size <= term_count:
                continue
            try:
                coef_seed = np.ones(term_count)
                zcoef, _mat, _rms_chief, _rms_centroid, _fitting_error = Kos.Zernike_Fitting(
                    px,
                    py,
                    phase,
                    coef_seed,
                )
                used_terms = term_count
                break
            except Exception as exc:
                last_error = exc
        if zcoef is None:
            raise RuntimeError(f"Zernike fit failed: {last_error}")

        focal = max(0.01, abs(float(getattr(pupil, "EFFL", 0.0))))
        diameter = max(0.01, 2.0 * float(getattr(pupil, "RadPupInp", 1.0)))
        mtf = Kos.calculate_mtf(
            np.asarray(zcoef, dtype=float),
            focal,
            diameter,
            wavelength,
            pixels=256,
            PupilSample=4,
        )
        samples = int(mtf.shape[0])
        # Convert the FFT axis to image-plane cycles/mm using fc = D / (lambda * f).
        freq_max = diameter / max(wavelength * 1e-3 * focal, 1e-12)
        freq = np.linspace(0.0, freq_max, samples // 2)
        tangential = np.asarray(mtf[samples // 2, samples // 2:], dtype=float)
        sagittal = np.asarray(mtf[samples // 2 :, samples // 2], dtype=float)
        count = min(len(freq), len(tangential), len(sagittal))
        return {
            "plot_freq": np.asarray(freq[:count], dtype=float),
            "plot_tan": np.asarray(tangential[:count], dtype=float),
            "plot_sag": np.asarray(sagittal[:count], dtype=float),
            "method": "Diffraction",
            "worker_count": 1,
            "accelerator": "CPU",
            "sample_count": int(px.size),
            "used_terms": int(used_terms) if used_terms is not None else 0,
            "phase_method": phase_method,
        }

    def _compute_geometric_mtf_sample(
        self,
        system,
        *,
        wavelength: float,
        surface_index: int,
        aperture_type: str,
        aperture_value: float,
        field_type: str,
        field_x: float,
        field_y: float,
        algorithm: str = "psf_fft",
    ) -> dict[str, object]:
        dense_count = max(24, self._current_ray_count() * 6)
        x_local, y_local, worker_count = self._build_geometric_image_samples(
            system,
            wavelength,
            sample_count=dense_count,
            pattern="hexapolar",
            surface_index=int(surface_index),
            aperture_type=str(aperture_type),
            aperture_value=float(aperture_value),
            field_type=str(field_type),
            field_x=float(field_x),
            field_y=float(field_y),
        )
        return self._geometric_mtf_result_from_image_samples(
            x_local,
            y_local,
            worker_count=int(worker_count),
            sample_count=int(dense_count),
            algorithm=algorithm,
        )

    def _geometric_mtf_result_from_image_samples(
        self,
        x_local: np.ndarray,
        y_local: np.ndarray,
        *,
        worker_count: int,
        sample_count: int,
        algorithm: str = "psf_fft",
    ) -> dict[str, object]:
        x_vals = np.asarray(x_local, dtype=float)
        y_vals = np.asarray(y_local, dtype=float)
        if x_vals.size < 4:
            raise RuntimeError("Not enough image-plane ray samples for geometric MTF")

        centered_x, centered_y = self._center_image_plane_samples(x_vals, y_vals)
        if centered_x.size < 4:
            raise RuntimeError("Not enough centered image-plane ray samples for geometric MTF")

        span_x = max(float(np.ptp(centered_x)), 1e-3)
        span_y = max(float(np.ptp(centered_y)), 1e-3)
        span = max(span_x, span_y) * 1.25
        if span <= 0:
            span = 1.0
        bins = 128
        if str(algorithm).strip().lower() == "lsf_fft":
            positive, tangential, sagittal, accelerator = self._compute_lsf_mtf_arrays(
                centered_x,
                centered_y,
                bins,
                span,
            )
            method_name = "Geometric-LSF"
        else:
            mtf, freq, _xedges, _unused, accelerator = self._compute_geometric_mtf_arrays(
                centered_x,
                centered_y,
                bins,
                span,
            )
            center = bins // 2
            positive = np.asarray(freq[center:], dtype=float)
            tangential = np.asarray(mtf[center, center:], dtype=float)
            sagittal = np.asarray(mtf[center:, center], dtype=float)
            method_name = "Geometric-PSF"
        count = min(len(positive), len(tangential), len(sagittal))
        return {
            "plot_freq": np.asarray(positive[:count], dtype=float),
            "plot_tan": np.asarray(tangential[:count], dtype=float),
            "plot_sag": np.asarray(sagittal[:count], dtype=float),
            "method": method_name,
            "worker_count": int(worker_count),
            "accelerator": str(accelerator),
            "sample_count": int(x_vals.size),
            "pupil_samp": int(sample_count),
        }

    @staticmethod
    def _compute_lsf_mtf_arrays(
        x_local: np.ndarray,
        y_local: np.ndarray,
        bins: int,
        span: float,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, str]:
        x_local = np.asarray(x_local, dtype=float)
        y_local = np.asarray(y_local, dtype=float)
        finite = np.isfinite(x_local) & np.isfinite(y_local)
        x_local = x_local[finite]
        y_local = y_local[finite]
        if x_local.size == 0:
            raise RuntimeError("Not enough centered image-plane samples for LSF MTF")
        x_local = x_local - float(np.mean(x_local))
        y_local = y_local - float(np.mean(y_local))
        lower = -span / 2.0
        upper = span / 2.0
        hist_x, xedges = np.histogram(x_local, bins=bins, range=(lower, upper))
        hist_y, _yedges = np.histogram(y_local, bins=bins, range=(lower, upper))
        lsf_tan = np.asarray(hist_x, dtype=float)
        lsf_sag = np.asarray(hist_y, dtype=float)
        if float(np.sum(lsf_tan)) <= 0.0 or float(np.sum(lsf_sag)) <= 0.0:
            raise RuntimeError("Not enough line-spread samples for LSF MTF")

        # Apply a smooth window before FFT to stabilize high-frequency ringing.
        window = np.hanning(bins)
        lsf_tan *= window
        lsf_sag *= window
        lsf_tan /= max(float(np.sum(lsf_tan)), 1e-12)
        lsf_sag /= max(float(np.sum(lsf_sag)), 1e-12)
        mtf_tan = np.abs(np.fft.fft(lsf_tan))
        mtf_sag = np.abs(np.fft.fft(lsf_sag))
        mtf_tan /= max(float(mtf_tan[0]), 1e-12)
        mtf_sag /= max(float(mtf_sag[0]), 1e-12)
        dx = float(xedges[1] - xedges[0])
        freq = np.fft.fftfreq(bins, d=dx)
        positive = freq >= 0.0
        return (
            np.asarray(freq[positive], dtype=float),
            np.asarray(mtf_tan[positive], dtype=float),
            np.asarray(mtf_sag[positive], dtype=float),
            "CPU",
        )

    def _build_geometric_image_samples(
        self,
        system,
        wavelength: float,
        sample_count: int,
        pattern: str = "hexapolar",
        *,
        surface_index: int,
        aperture_type: str,
        aperture_value: float,
        field_type: str,
        field_x: float,
        field_y: float,
    ) -> tuple[np.ndarray, np.ndarray, int]:
        random_source_bundle = self._build_random_source_bundle(sample_count)
        if random_source_bundle is not None:
            x_local, y_local, worker_count = self._trace_pattern_chunks_parallel(wavelength, [random_source_bundle])
            finite = np.isfinite(x_local) & np.isfinite(y_local)
            return x_local[finite], y_local[finite], worker_count
        pupil = Kos.PupilCalc(
            system,
            int(surface_index),
            wavelength,
            str(aperture_type),
            float(aperture_value),
        )
        pupil.Samp = max(2, int(sample_count))
        pupil.Ptype = self._current_analysis_pupil_pattern(pattern) if pattern == "hexapolar" else str(pattern)
        pupil.FieldType = str(field_type)
        field_pairs = [(float(field_x), float(field_y))]
        bundles = []
        for fx, fy in field_pairs:
            pupil.FieldX = fx
            pupil.FieldY = fy
            bundles.append(self._pupil_pattern_bundle(pupil))
        x_local, y_local, worker_count = self._trace_pattern_chunks_parallel(wavelength, bundles)
        finite = np.isfinite(x_local) & np.isfinite(y_local)
        return x_local[finite], y_local[finite], worker_count

    @staticmethod
    def _center_image_plane_samples(
        x_local: np.ndarray,
        y_local: np.ndarray,
    ) -> tuple[np.ndarray, np.ndarray]:
        x_vals = np.asarray(x_local, dtype=float)
        y_vals = np.asarray(y_local, dtype=float)
        finite = np.isfinite(x_vals) & np.isfinite(y_vals)
        if not np.any(finite):
            return np.asarray([], dtype=float), np.asarray([], dtype=float)
        x_vals = x_vals[finite]
        y_vals = y_vals[finite]
        x_vals = x_vals - float(np.mean(x_vals))
        y_vals = y_vals - float(np.mean(y_vals))
        return x_vals, y_vals

    def _build_geometric_image_samples_for_field_samples(
        self,
        wavelength: float,
        sample_count: int,
        pattern: str,
        *,
        surface_index: int,
        aperture_type: str,
        aperture_value: float,
        field_samples: list[dict[str, float | str]],
    ) -> tuple[list[tuple[np.ndarray, np.ndarray]], int]:
        if not field_samples:
            return [], 1
        row_specs = self._serializable_row_specs()
        bundles = [
            _build_pupil_bundle_static(
                row_specs,
                wavelength,
                sample_count,
                pattern,
                surface_index=int(surface_index),
                aperture_type=str(aperture_type),
                aperture_value=float(aperture_value),
                field_type=str(sample["field_type"]),
                field_x=float(sample["field_x"]),
                field_y=float(sample["field_y"]),
                pupil_rad=self._current_pupil_rad(),
                pupil_theta=self._current_pupil_theta(),
            )
            for sample in field_samples
        ]
        total_rays = int(sum(len(np.asarray(bundle[0])) for bundle in bundles))
        worker_count = self._mtf_worker_count(total_rays)
        if worker_count <= 1:
            results: list[tuple[np.ndarray, np.ndarray]] = []
            for bundle in bundles:
                x_local, y_local = _trace_analysis_chunk(row_specs, wavelength, *bundle)
                centered_x, centered_y = self._center_image_plane_samples(x_local, y_local)
                results.append((centered_x, centered_y))
            return results, 1

        try:
            executor = self._ensure_analysis_executor(worker_count)
        except Exception:
            executor = None
        if executor is None:
            results = []
            for bundle in bundles:
                x_local, y_local = _trace_analysis_chunk(row_specs, wavelength, *bundle)
                centered_x, centered_y = self._center_image_plane_samples(x_local, y_local)
                results.append((centered_x, centered_y))
            return results, 1

        field_parts: list[list[tuple[np.ndarray, np.ndarray]]] = [[] for _ in bundles]
        futures: list[tuple[int, tuple[np.ndarray, ...], object]] = []
        chunks_per_field = max(1, worker_count // max(1, len(bundles)))
        try:
            for field_index, bundle in enumerate(bundles):
                ray_total = len(np.asarray(bundle[0]))
                if ray_total == 0:
                    continue
                chunk_count = max(1, min(chunks_per_field, ray_total))
                for chunk in np.array_split(np.arange(ray_total), chunk_count):
                    if chunk.size == 0:
                        continue
                    chunk_bundle = tuple(np.asarray(values)[chunk] for values in bundle)
                    future = executor.submit(_trace_analysis_chunk, row_specs, wavelength, *chunk_bundle)
                    futures.append((field_index, chunk_bundle, future))

            for field_index, chunk_bundle, future in futures:
                try:
                    x_local, y_local = future.result()
                except Exception:
                    x_local, y_local = _trace_analysis_chunk(row_specs, wavelength, *chunk_bundle)
                field_parts[field_index].append((np.asarray(x_local, dtype=float), np.asarray(y_local, dtype=float)))
        finally:
            self._shutdown_analysis_executor()

        results = []
        for parts in field_parts:
            if not parts:
                results.append((np.asarray([], dtype=float), np.asarray([], dtype=float)))
                continue
            merged_x = np.concatenate([part[0] for part in parts if part[0].size]) if any(part[0].size for part in parts) else np.asarray([], dtype=float)
            merged_y = np.concatenate([part[1] for part in parts if part[1].size]) if any(part[1].size for part in parts) else np.asarray([], dtype=float)
            centered_x, centered_y = self._center_image_plane_samples(merged_x, merged_y)
            results.append((centered_x, centered_y))
        return results, worker_count

    def _build_geometric_image_samples_full(
        self,
        system,
        wavelength: float,
        sample_count: int,
        pattern: str = "hexapolar",
        *,
        surface_index: int,
        aperture_type: str,
        aperture_value: float,
        field_type: str,
        field_x: float,
        field_y: float,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray, int]:
        random_source_bundle = self._build_random_source_bundle(sample_count)
        if random_source_bundle is not None:
            x_local, y_local, z_local, l_local, m_local, n_local, worker_count = self._trace_pattern_chunks_parallel_full(
                wavelength,
                [random_source_bundle],
            )
            finite = (
                np.isfinite(x_local)
                & np.isfinite(y_local)
                & np.isfinite(z_local)
                & np.isfinite(l_local)
                & np.isfinite(m_local)
                & np.isfinite(n_local)
            )
            return (
                x_local[finite],
                y_local[finite],
                z_local[finite],
                l_local[finite],
                m_local[finite],
                n_local[finite],
                worker_count,
            )
        pupil = Kos.PupilCalc(
            system,
            int(surface_index),
            wavelength,
            str(aperture_type),
            float(aperture_value),
        )
        pupil.Samp = max(2, int(sample_count))
        pupil.Ptype = self._current_analysis_pupil_pattern(pattern) if pattern == "hexapolar" else str(pattern)
        pupil.FieldType = str(field_type)
        pupil.FieldX = float(field_x)
        pupil.FieldY = float(field_y)
        bundles = [self._pupil_pattern_bundle(pupil)]
        x_local, y_local, z_local, l_local, m_local, n_local, worker_count = self._trace_pattern_chunks_parallel_full(
            wavelength,
            bundles,
        )
        finite = (
            np.isfinite(x_local)
            & np.isfinite(y_local)
            & np.isfinite(z_local)
            & np.isfinite(l_local)
            & np.isfinite(m_local)
            & np.isfinite(n_local)
        )
        return (
            x_local[finite],
            y_local[finite],
            z_local[finite],
            l_local[finite],
            m_local[finite],
            n_local[finite],
            worker_count,
        )

    def _compute_psf_histogram(
        self,
        x_local: np.ndarray,
        y_local: np.ndarray,
        bins: int,
        span: float,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, str]:
        x_local, y_local = self._center_image_plane_samples(x_local, y_local)
        if x_local.size == 0:
            raise RuntimeError("Not enough image-plane samples for PSF histogram")
        backend_pref = os.getenv("KRAKEN_POSTPROC_BACKEND", "auto").strip().lower()
        gpu_min_samples = max(1, int(os.getenv("KRAKEN_GPU_MIN_SAMPLES", "1000000")))
        allow_auto_gpu = x_local.size >= gpu_min_samples
        if backend_pref == "auto" and not allow_auto_gpu:
            backend_pref = "cpu"
        if backend_pref in {"auto", "torch"}:
            torch = _optional_torch()
            if torch is not None:
                try:
                    if bool(torch.cuda.is_available()):
                        device = torch.device("cuda")
                        lower = -span / 2.0
                        upper = span / 2.0
                        step = (upper - lower) / float(bins)
                        x_t = torch.as_tensor(x_local, dtype=torch.float64, device=device)
                        y_t = torch.as_tensor(y_local, dtype=torch.float64, device=device)
                        ix = torch.floor((x_t - lower) / step).to(torch.int64)
                        iy = torch.floor((y_t - lower) / step).to(torch.int64)
                        valid = (ix >= 0) & (ix < bins) & (iy >= 0) & (iy < bins)
                        ix = ix[valid]
                        iy = iy[valid]
                        lin = ix * bins + iy
                        hist_t = torch.zeros(bins * bins, dtype=torch.float64, device=device)
                        hist_t.scatter_add_(0, lin, torch.ones_like(lin, dtype=torch.float64))
                        hist_t = hist_t.view(bins, bins)
                        xedges_t = torch.linspace(lower, upper, bins + 1, dtype=torch.float64, device=device)
                        yedges_t = torch.linspace(lower, upper, bins + 1, dtype=torch.float64, device=device)
                        return (
                            hist_t.detach().cpu().numpy(),
                            xedges_t.detach().cpu().numpy(),
                            yedges_t.detach().cpu().numpy(),
                            "GPU-Torch",
                        )
                except Exception:
                    pass
        if backend_pref in {"auto", "cupy"}:
            cp = _optional_cupy()
            if cp is not None:
                try:
                    x_gpu = cp.asarray(x_local, dtype=cp.float64)
                    y_gpu = cp.asarray(y_local, dtype=cp.float64)
                    hist_gpu, xedges_gpu, yedges_gpu = cp.histogram2d(
                        x_gpu,
                        y_gpu,
                        bins=bins,
                        range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
                    )
                    return (
                        cp.asnumpy(hist_gpu),
                        cp.asnumpy(xedges_gpu),
                        cp.asnumpy(yedges_gpu),
                        "GPU-CuPy",
                    )
                except Exception:
                    pass
        hist, xedges, yedges = np.histogram2d(
            x_local,
            y_local,
            bins=bins,
            range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
        )
        return hist, xedges, yedges, "CPU"

    def _compute_geometric_mtf_arrays(
        self,
        x_local: np.ndarray,
        y_local: np.ndarray,
        bins: int,
        span: float,
    ) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, str]:
        x_local, y_local = self._center_image_plane_samples(x_local, y_local)
        if x_local.size == 0:
            raise RuntimeError("Not enough centered image-plane samples for geometric MTF")
        backend_pref = os.getenv("KRAKEN_POSTPROC_BACKEND", "auto").strip().lower()
        gpu_min_samples = max(1, int(os.getenv("KRAKEN_GPU_MIN_SAMPLES", "1000000")))
        allow_auto_gpu = x_local.size >= gpu_min_samples
        if backend_pref == "auto" and not allow_auto_gpu:
            backend_pref = "cpu"
        if backend_pref in {"auto", "torch"}:
            torch = _optional_torch()
            if torch is not None:
                try:
                    if bool(torch.cuda.is_available()):
                        device = torch.device("cuda")
                        lower = -span / 2.0
                        upper = span / 2.0
                        step = (upper - lower) / float(bins)
                        x_t = torch.as_tensor(x_local, dtype=torch.float64, device=device)
                        y_t = torch.as_tensor(y_local, dtype=torch.float64, device=device)
                        ix = torch.floor((x_t - lower) / step).to(torch.int64)
                        iy = torch.floor((y_t - lower) / step).to(torch.int64)
                        valid = (ix >= 0) & (ix < bins) & (iy >= 0) & (iy < bins)
                        ix = ix[valid]
                        iy = iy[valid]
                        lin = ix * bins + iy
                        hist_t = torch.zeros(bins * bins, dtype=torch.float64, device=device)
                        hist_t.scatter_add_(0, lin, torch.ones_like(lin, dtype=torch.float64))
                        hist_t = hist_t.view(bins, bins)
                        psf_t = hist_t / torch.clamp(torch.sum(hist_t), min=1.0)
                        otf_t = torch.fft.fftshift(torch.fft.fft2(psf_t))
                        mtf_t = torch.abs(otf_t)
                        mtf_t = mtf_t / torch.clamp(torch.max(mtf_t), min=1e-12)
                        xedges_t = torch.linspace(lower, upper, bins + 1, dtype=torch.float64, device=device)
                        dx = float((xedges_t[1] - xedges_t[0]).detach().cpu().item())
                        freq_t = torch.fft.fftshift(torch.fft.fftfreq(bins, d=dx, device=device))
                        return (
                            mtf_t.detach().cpu().numpy(),
                            freq_t.detach().cpu().numpy(),
                            xedges_t.detach().cpu().numpy(),
                            np.asarray([], dtype=float),
                            "GPU-Torch",
                        )
                except Exception:
                    pass
        if backend_pref in {"auto", "cupy"}:
            cp = _optional_cupy()
            if cp is not None:
                try:
                    x_gpu = cp.asarray(x_local, dtype=cp.float64)
                    y_gpu = cp.asarray(y_local, dtype=cp.float64)
                    hist_gpu, xedges_gpu, _yedges_gpu = cp.histogram2d(
                        x_gpu,
                        y_gpu,
                        bins=bins,
                        range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
                    )
                    psf_gpu = hist_gpu / cp.maximum(cp.sum(hist_gpu), 1.0)
                    otf_gpu = cp.fft.fftshift(cp.fft.fft2(psf_gpu))
                    mtf_gpu = cp.abs(otf_gpu)
                    mtf_gpu /= cp.maximum(cp.max(mtf_gpu), 1e-12)
                    dx = float(cp.asnumpy(xedges_gpu[1] - xedges_gpu[0]))
                    freq_gpu = cp.fft.fftshift(cp.fft.fftfreq(bins, d=dx))
                    return (
                        cp.asnumpy(mtf_gpu),
                        cp.asnumpy(freq_gpu),
                        cp.asnumpy(xedges_gpu),
                        np.asarray([], dtype=float),
                        "GPU-CuPy",
                    )
                except Exception:
                    pass
        hist, xedges, _yedges = np.histogram2d(
            x_local,
            y_local,
            bins=bins,
            range=[[-span / 2.0, span / 2.0], [-span / 2.0, span / 2.0]],
        )
        psf = hist / max(np.sum(hist), 1.0)
        otf = np.fft.fftshift(np.fft.fft2(psf))
        mtf = np.abs(otf)
        mtf /= max(float(np.max(mtf)), 1e-12)
        dx = float(xedges[1] - xedges[0])
        freq = np.fft.fftshift(np.fft.fftfreq(bins, d=dx))
        return mtf, freq, xedges, np.asarray([], dtype=float), "CPU"

    def _collect_optics_info(self, system, rays, wavelength: float) -> dict:
        info: dict[str, float | None | str] = {
            "effl": None,
            "magnification": None,
            "ppa": None,
            "ppp": None,
            "h1_z": None,
            "h2_z": None,
            "paraxial_image_size": None,
            "sensor_fill": None,
            "spot_rms": None,
            "spot_cen_x": None,
            "spot_cen_y": None,
            "ep_radius": None,
            "ep_z": None,
            "xp_radius": None,
            "xp_z": None,
            "airy_radius": None,
        }
        paraxial_rows = self.rows
        try:
            if any(row.surface == "Mirror" for row in self.rows):
                paraxial_rows, _last_source_index = self._paraxial_reference_rows_for_layout(self.rows)
            a, b, c, d, effl, ppa, ppp = self._exact_paraxial_solution_for_rows(paraxial_rows, wavelength)
            h1_vertex_z, h2_vertex_z = self._paraxial_vertex_zs(paraxial_rows)
            info.update(
                {
                    "effl": float(effl),
                    "ppa": float(ppa),
                    "ppp": float(ppp),
                    "h1_z": float(h1_vertex_z + float(ppa)),
                    "h2_z": float(h2_vertex_z + float(ppp)),
                }
            )
            if self._current_object_mode() == "Finite" and len(self.rows) >= 2:
                object_gap = max(float(self._paraxial_total_object_gap(self.rows)[0]), 1e-9)
                object_size = max(float(self.rows[0].diameter), 0.0)
                sensor_size = max(float(self.rows[-1].diameter), 0.0)
                object_principal = object_gap + float(ppa)
                image_gap = self._compute_image_gap_from_paraxial_solution(
                    float(a),
                    float(b),
                    float(c),
                    float(d),
                    object_gap,
                    self._current_object_mode(),
                )
                image_principal = image_gap - float(ppp)
                if np.isfinite(object_principal) and abs(object_principal) > 1e-12 and np.isfinite(image_principal):
                    magnification = image_principal / object_principal
                    image_size = abs(magnification) * object_size
                    info["paraxial_image_size"] = float(image_size)
                    info["magnification"] = float(magnification)
                    if sensor_size > 1e-12:
                        info["sensor_fill"] = float(image_size / sensor_size)
        except Exception:
            pass
        try:
            _, _, _, a, b, c, d, _effl, _ppa, _ppp, _, _, _ = system.Parax(wavelength)
            info["parax_a"] = float(a)
            info["parax_b"] = float(b)
            info["parax_c"] = float(c)
            info["parax_d"] = float(d)
            if info.get("magnification") is None:
                info["magnification"] = float(a)
        except Exception:
            pass
        try:
            analysis_rays = self._build_analysis_rays(system, wavelength)
            X, Y, Z, L, M, N = self._pick_image_plane_data(analysis_rays)
            if X.size:
                rms, cenX, cenY = Kos.RMS(X, Y, Z, L, M, N)
                info.update(
                    {
                        "spot_rms": float(rms),
                        "spot_cen_x": float(cenX),
                        "spot_cen_y": float(cenY),
                    }
                )
        except Exception:
            pass
        try:
            pupil_system, pupil_rows, pupil_surface_index = self._pupil_model_inputs(
                system,
                build_reference=True,
            )
            pupil = Kos.PupilCalc(
                pupil_system,
                pupil_surface_index,
                wavelength,
                self._current_aperture_type(),
                self._current_aperture_value(),
            )
            info.update(
                {
                    "ep_radius": float(pupil.RadPupInp),
                    "ep_z": float(pupil.PosPupInp[2]),
                    "xp_radius": float(pupil.RadPupOut),
                    "xp_z": float(pupil.PosPupOut[2]),
                    "airy_radius": float(pupil.FocusAiryRadius),
                }
            )
        except Exception:
            pass
        if self._current_aperture_type() == "EPD":
            ep_radius = max(abs(float(self._current_aperture_value())) * 0.5, 0.0)
            if np.isfinite(ep_radius) and ep_radius > 1e-9:
                info["ep_radius"] = float(ep_radius)
                # EPD mode defines the launch pupil directly in object space.
                # Draw it at the object plane so the marker matches the ray fan.
                info["ep_z"] = 0.0
                if info.get("airy_radius") is None and info.get("effl") is not None:
                    info["airy_radius"] = float(
                        1.22 * wavelength * abs(float(info["effl"])) / max(2.0 * ep_radius, 1e-9)
                    )
        return info

    def _pupil_surface_index_for_rows(self, rows: list[SurfaceRow]) -> int:
        if len(rows) <= 2:
            return max(0, len(rows) - 1)
        aperture_indices = [
            index
            for index, row in enumerate(rows[1:-1], start=1)
            if row.surface == "Aperture"
        ]
        if aperture_indices:
            return min(aperture_indices, key=lambda index: max(float(rows[index].diameter), 1e-9))
        candidate_indices = [
            index
            for index, row in enumerate(rows[1:-1], start=1)
            if row.surface in {"Standard", "Thin Lens", "Aperture"}
        ]
        if not candidate_indices:
            return max(1, len(rows) - 1)
        return min(candidate_indices, key=lambda index: (max(float(rows[index].diameter), 1e-9), index))

    def _pupil_model_inputs(
        self,
        system,
        *,
        build_reference: bool,
    ) -> tuple[object, list[SurfaceRow], int]:
        pupil_system = system
        pupil_rows = self.rows
        if build_reference and any(row.surface == "Mirror" for row in self.rows):
            pupil_rows, _last_source_index = self._paraxial_reference_rows_for_layout(self.rows)
            pupil_system = _build_system_from_specs(self._serializable_specs_for_rows(pupil_rows), build=0)
        pupil_surface_index = self._pupil_surface_index_for_rows(pupil_rows)
        return pupil_system, pupil_rows, pupil_surface_index

    def _start_progress_spinner(self) -> None:
        if self._spinner_after_id is not None:
            self.after_cancel(self._spinner_after_id)
            self._spinner_after_id = None
        self._spinner_phase = 0
        self._animate_progress_spinner()

    def _stop_progress_spinner(self) -> None:
        if self._spinner_after_id is not None:
            self.after_cancel(self._spinner_after_id)
            self._spinner_after_id = None
        if not self.optimization_running:
            self.progress_spinner_var.set("idle")

    def _animate_progress_spinner(self) -> None:
        if not self.optimization_running:
            self._spinner_after_id = None
            self.progress_spinner_var.set("idle")
            return
        frames = ("|", "/", "-", "\\")
        self.progress_spinner_var.set(frames[self._spinner_phase % len(frames)])
        self._spinner_phase += 1
        self._spinner_after_id = self.after(120, self._animate_progress_spinner)

    @staticmethod
    def _optional_finite_float(value) -> float | None:
        if value is None:
            return None
        try:
            numeric = float(value)
        except (TypeError, ValueError):
            return None
        if not np.isfinite(numeric):
            return None
        return float(numeric)

    @classmethod
    def _format_optional_float(cls, value, fmt: str = ".4g", *, scale: float = 1.0, suffix: str = "") -> str:
        numeric = cls._optional_finite_float(value)
        if numeric is None:
            return "Unavailable"
        return f"{numeric * float(scale):{fmt}}{suffix}"

    def _field_launch_sample_summary(self) -> dict[str, object]:
        requested = max(1, int(self._requested_field_count()))
        basis, unit, span = self._field_sampling_basis_span()
        sign = -1.0 if basis == "angle" and float(self._current_field_angle_deg()) < 0.0 else 1.0
        if basis == "object height":
            sign = -1.0 if float(self._current_field_height()) < 0.0 else 1.0
        maximum = float(span) * sign
        active = self._field_sampling_is_active()
        values = [float(value) for value in self._sample_field_values(maximum)] if active else [0.0]
        if not values:
            values = [0.0]
        unique_values = sorted({round(float(value), 12) for value in values})
        effective = max(1, len(unique_values))
        return {
            "requested": requested,
            "effective": effective,
            "basis": basis,
            "unit": unit,
            "min": float(min(values)),
            "max": float(max(values)),
            "overlap": requested > 1 and effective == 1,
            "active": active,
        }

    def _source_sampling_diagnostics(self, trace_summary: dict | None = None) -> list[tuple[str, str]]:
        diagnostics: list[tuple[str, str]] = []
        if self._current_source_model() != SOURCE_MODEL_DEFAULT:
            return diagnostics

        field_summary = self._field_launch_sample_summary()
        if bool(field_summary.get("overlap")):
            diagnostics.append(
                (
                    "Field sampling note",
                    (
                        f"{field_summary['requested']} requested field samples collapse to "
                        f"{field_summary['effective']} effective on-axis field because the "
                        f"{field_summary['basis']} span is 0 {field_summary['unit']}; "
                        "use a nonzero field value to launch distinct field bundles."
                    ),
                )
            )

        if not self._is_full_pupil_mode():
            pattern = self._current_pupil_pattern_label()
            if pattern in {PUPIL_PATTERN_DEFAULT, "Fan X", "Fan Y"}:
                diagnostics.append(
                    (
                        "Projection sampling note",
                        f"{pattern} is a 2D pupil slice; the orthogonal auxiliary projection can collapse to the axis. Use Cross fan or Full Pupil for paired XZ/YZ content.",
                    )
                )

        active = ""
        if trace_summary:
            active = str(trace_summary.get("active", "") or "")
        if (
            self._current_object_mode() == "Finite"
            and float(self._current_source_cone_angle()) > 1e-12
            and active.lower().startswith("sequential")
        ):
            diagnostics.append(
                (
                    "Source cone note",
                    "Sequential Pupil / field ignores Source cone angle; finite-object cone angle comes from object distance and the entrance pupil. Use a physical source or non-sequential scene for explicit source half-angle.",
                )
            )
        return diagnostics

    def _update_results(self, system, rays, wavelength: float, optics_info: dict | None = None) -> None:
        if optics_info is None:
            optics_info = self._collect_optics_info(system, rays, wavelength)
        items = []
        items.append(("Surface count", str(len(self.rows))))
        items.append(("Optimized vars", str(len(self._build_optimization_variables()))))
        items.append(("Object mode", self._current_object_mode()))
        items.append(("Wavelength [um]", f"{wavelength:.4g}"))
        items.append(("Analysis mode", self._last_analysis_label))
        items.append(("Analysis workers", self._analysis_compute_summary()))
        items.append(("Analysis surface", str(self._analysis_surface_index())))
        aperture_type_label = self._current_aperture_type_label()
        try:
            raw_aperture_value = float(self.aperture_value_var.get())
        except Exception:
            raw_aperture_value = self._current_aperture_value()
        items.append(("Aperture type", aperture_type_label))
        items.append(("Aperture value", f"{raw_aperture_value:.4g}" if aperture_type_label == "FNO" else f"{self._current_aperture_value():.4g}"))
        if aperture_type_label == "FNO":
            items.append(("Equivalent EPD [mm]", f"{self._current_aperture_value():.4g}"))
        field_metrics = self._field_metrics_summary()
        items.append(("Field type", self._field_type_display_label(self._current_field_type())))
        items.append(("Field half-angle [deg]", f"{field_metrics['current_angle_deg']:.4g}"))
        items.append(("Object semi-ht [mm]", f"{field_metrics['current_object_height']:.4g}"))
        items.append(("Paraxial img semi-ht [mm]", f"{field_metrics['current_paraxial_image_height']:.4g}"))
        items.append(("Real img semi-ht [mm]", f"{field_metrics['current_real_image_height']:.4g}"))
        field_launch_summary = self._field_launch_sample_summary()
        if int(field_launch_summary["requested"]) > 1:
            items.append((
                "Effective field samples",
                f"{int(field_launch_summary['effective'])} / {int(field_launch_summary['requested'])}",
            ))
            items.append((
                f"Field sample span [{field_launch_summary['unit']}]",
                f"{float(field_launch_summary['min']):.4g} .. {float(field_launch_summary['max']):.4g}",
            ))
            items.append(("Max parax img semi-ht [mm]", f"{field_metrics['max_paraxial_image_height']:.4g}"))
            items.append(("Max real img semi-ht [mm]", f"{field_metrics['max_real_image_height']:.4g}"))
            items.append(("Required image dia [mm]", f"{field_metrics['image_diameter']:.4g}"))
        if self.rows and self.rows[-1].surface == "Image":
            items.append(("Image row diameter [mm]", f"{float(self.rows[-1].diameter):.4g}"))

        camera_info = self._current_camera_record()
        if camera_info is not None:
            items.append(("Camera", ""))
            items.append(("Camera model", str(camera_info.get("model", self._current_camera_model()))))
            width = float(camera_info.get("sensor_width_mm", 0.0))
            height = float(camera_info.get("sensor_height_mm", 0.0))
            if width > 0.0 and height > 0.0:
                items.append(("Sensor active [mm]", f"{width:.4g} x {height:.4g}"))
            diagonal = camera_info.get("sensor_diagonal_mm")
            if diagonal is not None:
                items.append(("Sensor diagonal [mm]", f"{float(diagonal):.4g}"))
            resolution = camera_info.get("resolution_px")
            if isinstance(resolution, tuple) and len(resolution) == 2:
                items.append(("Resolution [px]", f"{int(resolution[0])} x {int(resolution[1])}"))
            pixel_size = camera_info.get("pixel_size_um")
            if isinstance(pixel_size, tuple) and len(pixel_size) == 2:
                items.append(("Pixel size [um]", f"{float(pixel_size[0]):.4g} x {float(pixel_size[1]):.4g}"))
            register = camera_info.get("camera_front_to_sensor_mm")
            if register is not None:
                items.append(("Camera front-sensor [mm]", f"{float(register):.4g}"))
            mount = camera_info.get("lens_mount")
            if mount:
                items.append(("Camera mount", str(mount)))

        total_length = sum(max(float(row.thickness), 0.0) for row in self.rows)
        items.append(("Total length [mm]", f"{total_length:.4g}"))

        trace_summary = self._trace_preview_summary(rays, self._last_scene_bundle)
        items.append(("Trace", ""))
        items.append(("Trace requested", str(trace_summary["requested"])))
        items.append(("Trace active", str(trace_summary["active"])))
        items.append(("Trace family", str(trace_summary["family"])))
        items.append(("Trace backend", str(trace_summary["backend"])))
        items.append(("Preview rays", str(trace_summary["total_rays"])))
        items.append(("Image hits", f"{trace_summary['image_hits']} / {trace_summary['total_rays']}"))
        items.append(("Stopped rays", str(trace_summary["stopped_rays"])))
        trace_note = str(trace_summary.get("note", "")).strip()
        if trace_note:
            items.append(("Trace note", trace_note))
        sampling_diagnostics = self._source_sampling_diagnostics(trace_summary)
        if sampling_diagnostics:
            items.append(("Source sampling", ""))
            items.extend(sampling_diagnostics)
        detector_aperture_records = self._collect_detector_aperture_records(ray_records=self._active_ray_analysis_records())
        self._detector_aperture_records = detector_aperture_records
        detector_counts = self._detector_aperture_counts(detector_aperture_records)
        if int(detector_counts.get("detectors", 0) or 0) > 0:
            detector_rays = int(detector_counts.get("rays", 0) or 0)
            detector_hits = int(detector_counts.get("hits", 0) or 0)
            detector_misses = int(detector_counts.get("misses", 0) or 0)
            detector_other = int(detector_counts.get("other", 0) or 0)
            hit_fraction = detector_hits / detector_rays if detector_rays > 0 else np.nan
            items.append(("Detector aperture", ""))
            items.append(("Detector surfaces", str(int(detector_counts["detectors"]))))
            items.append(("Detector rays", str(detector_rays)))
            items.append(("Detector hits", f"{detector_hits} / {detector_rays} ({self._format_percent_value(hit_fraction)})"))
            items.append(("Detector misses", str(detector_misses)))
            items.append(("Detector other terminals", str(detector_other)))
            items.append(("Detector hit power", self._format_ray_inspector_value(detector_counts.get("hit_power"))))
            items.append(("Detector miss power", self._format_ray_inspector_value(detector_counts.get("miss_power"))))
            if detector_counts.get("worst_margin") is not None:
                items.append(("Worst detector miss [mm]", f"{float(detector_counts['worst_margin']):.4g}"))
                worst_ray = str(detector_counts.get("worst_ray", "") or "").strip()
                worst_detector = str(detector_counts.get("worst_detector", "") or "").strip()
                if worst_ray or worst_detector:
                    items.append(("Worst detector miss ray", f"{worst_ray} {worst_detector}".strip()))
        focus_diag = self._sequential_focus_diagnostic(rays, trace_summary)
        self._last_sequential_focus_diagnostic = dict(focus_diag)
        if focus_diag:
            items.append(("Sequential focus", ""))
            items.append(("Best focus z [mm]", f"{float(focus_diag['best_focus_z']):.4g}"))
            items.append(("Focus offset [mm]", f"{float(focus_diag['focus_shift']):+.4g}"))
            items.append(("Image RMS [mm]", f"{float(focus_diag['image_rms']):.4g}"))
            items.append(("Best-focus RMS [mm]", f"{float(focus_diag['best_focus_rms']):.4g}"))
            focus_note = str(focus_diag.get("diagnostic", "") or "").strip()
            if focus_note:
                items.append(("Focus diagnostic", focus_note))
                self.append_debug(f"Sequential focus diagnostic: {focus_note}")

        pol_summary = self._polarization_summary(rays)
        items.append(("Coating / polarization", ""))
        items.append(("Coating attr surfaces", str(pol_summary["coated_surface_count"])))
        items.append(("Mean throughput TT", self._format_percent_value(pol_summary["mean_tt"])))
        items.append(("Image throughput TT", self._format_percent_value(pol_summary["image_mean_tt"])))
        items.append(("Mean TP / TS", f"{self._format_percent_value(pol_summary['mean_tp'])} / {self._format_percent_value(pol_summary['mean_ts'])}"))
        items.append(("Mean RP / RS", f"{self._format_percent_value(pol_summary['mean_rp'])} / {self._format_percent_value(pol_summary['mean_rs'])}"))
        items.append(("Mean P/S T split", self._format_percent_value(pol_summary["mean_ps_transmission_split"])))
        items.append(("Mean P/S R split", self._format_percent_value(pol_summary["mean_ps_reflection_split"])))

        phase2_summary = self._phase2_feature_summary()
        items.append(("Phase 2 report", ""))
        items.append(("Source model", str(phase2_summary["source_model"])))
        items.append(("Error-map surfaces", str(phase2_summary["error_map_count"])))
        if phase2_summary["max_error_pv"] is not None:
            items.append(("Max error PV", f"{float(phase2_summary['max_error_pv']):.4g}"))
            items.append(("Max error RMS", f"{float(phase2_summary['max_error_rms']):.4g}"))
        items.append(("Coating surfaces", str(phase2_summary["coating_count"])))
        items.append(("Metal catalogs", str(phase2_summary["metal_catalog_count"])))

        effl_value = self._optional_finite_float(optics_info.get("effl"))
        magnification_value = self._optional_finite_float(optics_info.get("magnification"))
        ppa_value = self._optional_finite_float(optics_info.get("ppa"))
        ppp_value = self._optional_finite_float(optics_info.get("ppp"))
        h1_z_value = self._optional_finite_float(optics_info.get("h1_z"))
        h2_z_value = self._optional_finite_float(optics_info.get("h2_z"))
        paraxial_image_size_value = self._optional_finite_float(optics_info.get("paraxial_image_size"))
        sensor_fill_value = self._optional_finite_float(optics_info.get("sensor_fill"))

        if effl_value is not None:
            items.append(("Imaging", ""))
            items.append(("EFFL [mm]", f"{effl_value:.4g}"))
            items.append(("Magnification", self._format_optional_float(magnification_value)))
            if paraxial_image_size_value is not None:
                items.append(("Paraxial image size [mm]", f"{paraxial_image_size_value:.4g}"))
            if sensor_fill_value is not None:
                items.append(("Sensor fill", f"{100.0 * sensor_fill_value:.3g}%"))
            if any(value is not None for value in (h1_z_value, h2_z_value, ppa_value, ppp_value)):
                items.append(("Principal Planes", ""))
                if h1_z_value is not None:
                    items.append(("Front PP z [mm]", f"{h1_z_value:.4g}"))
                if h2_z_value is not None:
                    items.append(("Back PP z [mm]", f"{h2_z_value:.4g}"))
                if ppa_value is not None:
                    items.append(("PPA offset [mm]", f"{ppa_value:.4g}"))
                if ppp_value is not None:
                    items.append(("PPP offset [mm]", f"{ppp_value:.4g}"))
        else:
            items.append(("Paraxial data", "Unavailable"))

        ep_radius_value = self._optional_finite_float(optics_info.get("ep_radius"))
        ep_z_value = self._optional_finite_float(optics_info.get("ep_z"))
        xp_radius_value = self._optional_finite_float(optics_info.get("xp_radius"))
        xp_z_value = self._optional_finite_float(optics_info.get("xp_z"))
        airy_radius_value = self._optional_finite_float(optics_info.get("airy_radius"))
        if any(value is not None for value in (ep_radius_value, ep_z_value, xp_radius_value, xp_z_value, airy_radius_value)):
            items.append(("Pupils", ""))
            if ep_radius_value is not None:
                items.append(("Entrance pupil radius [mm]", f"{ep_radius_value:.4g}"))
                items.append(("Entrance pupil diameter [mm]", f"{2.0 * ep_radius_value:.4g}"))
            else:
                items.append(("Entrance pupil", "Unavailable"))
            if ep_z_value is not None:
                items.append(("Entrance pupil z [mm]", f"{ep_z_value:.4g}"))
            if xp_radius_value is not None:
                items.append(("Exit pupil radius [mm]", f"{xp_radius_value:.4g}"))
                items.append(("Exit pupil diameter [mm]", f"{2.0 * xp_radius_value:.4g}"))
            else:
                items.append(("Exit pupil", "Unavailable"))
            if xp_z_value is not None:
                items.append(("Exit pupil z [mm]", f"{xp_z_value:.4g}"))
            if airy_radius_value is not None:
                items.append(("Airy radius [mm]", f"{airy_radius_value:.4g}"))
        else:
            items.append(("Pupil data", "Unavailable"))

        items.append(("Spot", ""))
        spot_rms_value = self._optional_finite_float(optics_info.get("spot_rms"))
        if spot_rms_value is not None:
            items.append(("Spot RMS [mm]", f"{spot_rms_value:.4g}"))
            items.append(("Spot centroid X [mm]", self._format_optional_float(optics_info.get("spot_cen_x"))))
            items.append(("Spot centroid Y [mm]", self._format_optional_float(optics_info.get("spot_cen_y"))))
        else:
            items.append(("Spot RMS [mm]", "Unavailable"))

        self._set_results(items)

    @staticmethod
    def _optimization_bounds(parameter: str, value: float) -> tuple[float, float]:
        for spec in VARIABLE_REGISTRY.values():
            if spec.parameter == parameter:
                return spec.default_bounds(value)
        raise ValueError(f"Unsupported optimization parameter: {parameter}")

    @staticmethod
    def _variable_spec_for_field(field: str):
        return VARIABLE_REGISTRY.get(field)

    @staticmethod
    def _variable_spec_for_parameter(parameter: str):
        for spec in VARIABLE_REGISTRY.values():
            if _native_variable_matches(spec.parameter, parameter):
                return spec
        return None

    @classmethod
    def _optimization_value_from_row(cls, row: SurfaceRow, variable: OpticalVariable) -> float:
        spec = cls._variable_spec_for_parameter(variable.parameter)
        if spec is not None:
            return spec.value_from_row(row)
        if hasattr(row, str(variable.parameter)):
            return float(getattr(row, str(variable.parameter)))
        raise ValueError(f"Unsupported optimization parameter: {variable.parameter}")

    @classmethod
    def _apply_optimization_value_to_row(cls, row: SurfaceRow, variable: OpticalVariable, value: float) -> None:
        spec = cls._variable_spec_for_parameter(variable.parameter)
        if spec is not None:
            setattr(row, spec.field, float(value))
            return
        if hasattr(row, str(variable.parameter)):
            setattr(row, str(variable.parameter), float(value))
            return
        raise ValueError(f"Unsupported optimization parameter: {variable.parameter}")

    @staticmethod
    def _merit_spec_for_label(label: str):
        for spec in OPERAND_REGISTRY.values():
            if spec.label == label:
                return spec
        return None

    def _selected_operand_specs(self) -> list:
        if "merit_mode_list" in self.__dict__:
            labels = [self.merit_mode_list.get(i) for i in self.merit_mode_list.curselection()]
        else:
            labels = [str(label) for label in getattr(self, "_headless_selected_operand_labels", [])]
        specs = []
        for label in labels:
            spec = self._merit_spec_for_label(label)
            if spec is not None:
                specs.append(spec)
        return specs

    def _operand_weight(self, label: str) -> float:
        var = self.operand_weight_vars.get(label)
        if var is None:
            spec = self._merit_spec_for_label(label)
            return 1.0 if spec is None else spec.default_weight
        try:
            return float(var.get())
        except ValueError:
            spec = self._merit_spec_for_label(label)
            return 1.0 if spec is None else spec.default_weight

    def _operand_target(self, label: str) -> float:
        var = self.operand_target_vars.get(label)
        if var is None:
            spec = self._merit_spec_for_label(label)
            return 0.0 if spec is None else spec.default_target
        try:
            return float(var.get())
        except ValueError:
            spec = self._merit_spec_for_label(label)
            return 0.0 if spec is None else spec.default_target

    def _operand_wavelength(self, label: str) -> float:
        var = self.operand_wavelength_vars.get(label)
        if var is None:
            return self._current_wavelength()
        try:
            return float(var.get())
        except ValueError:
            return self._current_wavelength()

    def _operand_field(self, label: str) -> float:
        var = self.operand_field_vars.get(label)
        if var is None:
            return 0.0
        try:
            return float(var.get())
        except ValueError:
            return 0.0

    def _operand_field_x(self, label: str) -> float:
        var = self.operand_field_x_vars.get(label)
        if var is None:
            return 0.0
        try:
            return float(var.get())
        except ValueError:
            return 0.0

    def _operand_field_y(self, label: str) -> float:
        var = self.operand_field_y_vars.get(label)
        if var is not None:
            try:
                return float(var.get())
            except ValueError:
                return 0.0
        return self._operand_field(label)

    def _operand_field_type(self, label: str) -> str:
        if self._current_object_mode() == "Infinity":
            return "angle"
        return "height"

    def _resolved_field_coordinate(self, field_basis: str, raw_value: float, resolved_field_type: str) -> float:
        metrics = self._field_metrics_for_value(field_basis, raw_value)
        if resolved_field_type == "angle":
            return float(metrics["angle_deg"])
        return float(metrics["object_height"])

    def _resolved_mtf_field_samples(self, label: str) -> list[dict[str, float | str]]:
        field_basis = self._current_field_type()
        resolved_field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
        basis_label = self._field_type_display_label(field_basis)
        if field_basis == "Angle" and resolved_field_type == "height":
            basis_label = "Field Half-Angle -> Object Semi-Height"
        unit = self._field_type_unit(field_basis)
        raw_x = 0.0
        resolved_x = 0.0
        raw_limit = abs(float(self._current_field_value()))
        count = max(1, self._current_field_count())
        if raw_limit <= 1e-9:
            raw_values = [0.0]
        elif count == 1:
            raw_values = [float(raw_limit)]
        else:
            raw_values = list(np.linspace(0.0, float(raw_limit), count))

        samples: list[dict[str, float | str]] = []
        for raw_value in raw_values:
            resolved_y = self._resolved_field_coordinate(field_basis, raw_value, resolved_field_type)
            samples.append(
                {
                    "basis": basis_label,
                    "unit": unit,
                    "display_x": float(raw_x),
                    "display_y": float(raw_value),
                    "field_type": resolved_field_type,
                    "field_x": float(resolved_x),
                    "field_y": float(resolved_y),
                    "legend": f"{self._format_field_sample_value(raw_value)} {unit}".strip(),
                }
            )
        return samples

    def _resolved_positive_field_samples(self) -> list[dict[str, float | str]]:
        field_basis = self._current_field_type()
        resolved_field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
        unit = self._field_type_unit(field_basis)
        raw_limit = abs(float(self._current_field_value()))
        count = max(1, self._current_field_count())
        if count == 1:
            raw_values = [raw_limit]
        else:
            raw_values = list(np.linspace(0.0, raw_limit, count))
        samples: list[dict[str, float | str]] = []
        for raw_value in raw_values:
            resolved_y = self._resolved_field_coordinate(field_basis, raw_value, resolved_field_type)
            samples.append(
                {
                    "basis": self._field_type_display_label(field_basis),
                    "unit": unit,
                    "display_y": float(raw_value),
                    "field_type": resolved_field_type,
                    "field_x": 0.0,
                    "field_y": float(resolved_y),
                    "legend": f"{self._format_field_sample_value(raw_value)} {unit}".strip(),
                }
            )
        return samples

    def _resolved_field_grid_samples(self) -> list[dict[str, float | str]]:
        field_basis = self._current_field_type()
        resolved_field_type = "angle" if self._current_object_mode() == "Infinity" else "height"
        basis_label = self._field_type_display_label(field_basis)
        unit = self._field_type_unit(field_basis)
        raw_limit = abs(float(self._current_field_value()))
        count = max(3, self._current_field_count())
        if raw_limit <= 1e-9:
            raw_values = [0.0]
        else:
            raw_values = list(np.linspace(-raw_limit, raw_limit, count))
        samples: list[dict[str, float | str]] = []
        seen: set[tuple[float, float]] = set()
        for raw_y in raw_values:
            for raw_x in raw_values:
                key = (round(float(raw_x), 12), round(float(raw_y), 12))
                if key in seen:
                    continue
                seen.add(key)
                resolved_x = self._resolved_field_coordinate(field_basis, float(raw_x), resolved_field_type)
                resolved_y = self._resolved_field_coordinate(field_basis, float(raw_y), resolved_field_type)
                samples.append(
                    {
                        "basis": basis_label,
                        "unit": unit,
                        "display_x": float(raw_x),
                        "display_y": float(raw_y),
                        "field_type": resolved_field_type,
                        "field_x": float(resolved_x),
                        "field_y": float(resolved_y),
                    }
                )
        return samples

    def _operand_surface_index(self, label: str) -> int:
        var = self.operand_surface_vars.get(label)
        if var is None:
            return self._analysis_surface_index()
        value = var.get().strip()
        if not value or value == "Auto":
            return self._analysis_surface_index()
        try:
            return int(value.split(":", 1)[0].strip())
        except ValueError:
            return self._analysis_surface_index()

    def _operand_aperture_type(self, label: str) -> str:
        var = self.operand_aperture_type_vars.get(label)
        if var is None:
            return self._current_aperture_type()
        value = var.get().strip().upper()
        if value == "FNO":
            return "EPD"
        return value if value in {"STOP", "EPD"} else self._current_aperture_type()

    def _operand_aperture_value(self, label: str) -> float:
        var = self.operand_aperture_value_vars.get(label)
        if var is None:
            return self._current_aperture_value()
        try:
            value = float(var.get())
        except ValueError:
            return self._current_aperture_value()
        return value if value != 0.0 else self._current_aperture_value()

    def _build_optimization_variables(self) -> list[OpticalVariable]:
        variables: list[OpticalVariable] = []
        for index, row in enumerate(self.rows):
            if row.surface == "Image":
                continue
            for spec in VARIABLE_REGISTRY.values():
                if not spec.is_supported(row) or not self._variable_enabled_for_row(row, spec):
                    continue
                value = spec.value_from_row(row)
                lower, upper = spec.get_bounds(row) or spec.default_bounds(value)
                variables.append(
                    OpticalVariable(
                        index,
                        spec.parameter,
                        lower,
                        upper,
                        name=f"{row.name} {spec.label}",
                    )
                )
        return variables

    def _build_merit_function(self) -> MeritFunction:
        selected_specs = self._selected_operand_specs()
        if not selected_specs:
            return MeritFunction(operands=[])
        operands = []
        for spec in selected_specs:
            operands.extend(spec.build_merit_function(self).operands)
        return MeritFunction(operands=operands)

    def _build_tolerance_merit_function(self) -> tuple[MeritFunction, list[str]]:
        for attr_name in (
            "operand_weight_vars",
            "operand_target_vars",
            "operand_wavelength_vars",
            "operand_field_vars",
            "operand_field_x_vars",
            "operand_field_y_vars",
            "operand_surface_vars",
            "operand_aperture_type_vars",
            "operand_aperture_value_vars",
            "operand_frequency_vars",
            "operand_mtf_mode_vars",
            "operand_mtf_algorithm_vars",
        ):
            self.__dict__.setdefault(attr_name, {})
        selected_specs = self._selected_operand_specs()
        if selected_specs:
            operands = []
            labels = []
            for spec in selected_specs:
                labels.append(str(spec.label))
                operands.extend(spec.build_merit_function(self).operands)
            return MeritFunction(operands=operands), labels
        default_spec = self._merit_spec_for_label("Spot RMS")
        if default_spec is None:
            return MeritFunction(operands=[]), []
        return default_spec.build_merit_function(self), [str(default_spec.label)]

    @staticmethod
    def _finite_stats(values: list[float]) -> dict[str, float]:
        arr = np.asarray(values, dtype=float).reshape(-1)
        arr = arr[np.isfinite(arr)]
        if arr.size == 0:
            return {"mean": np.nan, "std": np.nan, "min": np.nan, "p95": np.nan, "max": np.nan}
        return {
            "mean": float(np.mean(arr)),
            "std": float(np.std(arr)),
            "min": float(np.min(arr)),
            "p95": float(np.percentile(arr, 95.0)),
            "max": float(np.max(arr)),
        }

    def run_tolerance_monte_carlo(
        self,
        *,
        sample_count: int = 25,
        seed: int = 12345,
    ) -> dict[str, object]:
        sample_count = max(1, int(sample_count))
        seed = int(seed)
        variables = self._build_optimization_variables()
        if not variables:
            raise RuntimeError("No tolerance variables are marked. Mark variable cells or set native Var/VarBounds first.")
        merit_function, operand_labels = self._build_tolerance_merit_function()
        if not merit_function.operands:
            raise RuntimeError("No merit operands are available for tolerance reporting.")

        system = self.build_system()
        has_mtf_operand = any(isinstance(operand, MTFAtFrequencyOperand) for operand in merit_function.operands)
        evaluator = MeritEvaluator(
            system.SDT,
            setup=system.SETUP,
            merit_function=merit_function,
            mtf_worker_count=self._mtf_worker_count(self._current_ray_count()) if has_mtf_operand else 1,
        )
        nominal = [
            float(self._optimization_value_from_row(self.rows[variable.surface_index], variable))
            for variable in variables
        ]
        couplings = [self._tolerance_variable_coupling(variable) for variable in variables]
        manufacturing = [self._tolerance_variable_manufacturing(variable) for variable in variables]
        rng = np.random.default_rng(seed)
        sample_vectors = [np.asarray(nominal, dtype=float)]
        for _sample_index in range(sample_count):
            group_quantiles: dict[str, float] = {}
            values: list[float] = []
            for variable, coupling in zip(variables, couplings):
                lower = float(variable.lower_bound)
                upper = float(variable.upper_bound)
                if lower > upper:
                    lower, upper = upper, lower
                group = str(coupling.get("group", "") or "").strip()
                if group:
                    quantile = group_quantiles.setdefault(group, float(rng.uniform(0.0, 1.0)))
                    if int(coupling.get("sign", 1) or 1) < 0:
                        quantile = 1.0 - quantile
                    values.append(float(lower + quantile * (upper - lower)))
                else:
                    values.append(float(rng.uniform(lower, upper)))
            sample_vectors.append(np.asarray(values, dtype=float))

        records: list[dict[str, object]] = []
        for sample_index, values in enumerate(sample_vectors):
            result = evaluator.evaluate(variables, values)
            record: dict[str, object] = {
                "sample": sample_index,
                "kind": "nominal" if sample_index == 0 else "monte_carlo",
                "valid": bool(result.valid),
                "total_merit": float(result.total),
                "message": str(result.message),
            }
            for variable, value in zip(variables, values):
                key = f"var_s{int(variable.surface_index)}_{str(variable.parameter).lower()}"
                record[key] = float(value)
            for operand in result.operands:
                key = re.sub(r"[^a-z0-9]+", "_", str(operand.name).strip().lower()).strip("_") or "operand"
                record[f"{key}_value"] = float(operand.value)
                record[f"{key}_weighted"] = float(operand.weighted)
                record[f"{key}_residual"] = float(operand.residual)
            records.append(record)

        valid_records = [record for record in records if bool(record.get("valid"))]
        variable_records = [
            {
                "name": variable.normalized_name(),
                "surface_index": int(variable.surface_index),
                "parameter": str(variable.parameter),
                "nominal": float(nominal[index]),
                "lower": float(variable.lower_bound),
                "upper": float(variable.upper_bound),
                "compensator": self._tolerance_variable_compensator_enabled(variable),
                **(
                    {
                        "coupling_group": str(couplings[index].get("group", "")),
                        "coupling_sign": int(couplings[index].get("sign", 1) or 1),
                    }
                    if couplings[index]
                    else {}
                ),
                **self._tolerance_manufacturing_record_fields(manufacturing[index]),
            }
            for index, variable in enumerate(variables)
        ]
        coupling_groups = sorted(
            {
                str(record.get("coupling_group", "") or "")
                for record in variable_records
                if str(record.get("coupling_group", "") or "").strip()
            }
        )
        total_values = [float(record.get("total_merit", np.nan)) for record in records if bool(record.get("valid"))]
        worst_record = max(valid_records, key=lambda record: float(record.get("total_merit", -np.inf)), default=None)
        summary = {
            "sample_count": sample_count,
            "seed": seed,
            "variables": variable_records,
            "coupling_groups": [
                {
                    "group": group,
                    "variable_count": sum(1 for record in variable_records if str(record.get("coupling_group", "")) == group),
                }
                for group in coupling_groups
            ],
            "operand_labels": operand_labels,
            "records": records,
            "valid_count": len(valid_records),
            "invalid_count": len(records) - len(valid_records),
            "total_merit_stats": self._finite_stats(total_values),
            "worst_sample": None if worst_record is None else int(worst_record.get("sample", -1)),
            "worst_total_merit": np.nan if worst_record is None else float(worst_record.get("total_merit", np.nan)),
        }
        self._last_tolerance_monte_carlo_records = records
        self._last_tolerance_monte_carlo_summary = summary
        return summary

    @staticmethod
    def _format_stats_line(stats: dict[str, float]) -> str:
        return (
            f"mean={float(stats.get('mean', np.nan)):.6g}, "
            f"std={float(stats.get('std', np.nan)):.6g}, "
            f"min={float(stats.get('min', np.nan)):.6g}, "
            f"p95={float(stats.get('p95', np.nan)):.6g}, "
            f"max={float(stats.get('max', np.nan)):.6g}"
        )

    def tolerance_monte_carlo_report_text(self, summary: dict[str, object] | None = None) -> str:
        summary = dict(summary if summary is not None else self._last_tolerance_monte_carlo_summary)
        if not summary:
            return "# KrakenOS Tolerance Monte Carlo Report\n\nNo tolerance run has been executed.\n"
        variables = list(summary.get("variables", []) or [])
        records = list(summary.get("records", []) or [])
        lines = [
            "# KrakenOS Tolerance Monte Carlo Report",
            "",
            f"Samples: {int(summary.get('sample_count', 0) or 0)} Monte Carlo + nominal",
            f"Seed: {int(summary.get('seed', 0) or 0)}",
            f"Valid/invalid evaluations: {int(summary.get('valid_count', 0) or 0)}/{int(summary.get('invalid_count', 0) or 0)}",
            f"Merit operands: {', '.join(str(label) for label in list(summary.get('operand_labels', []) or []))}",
            "",
            "Variables:",
        ]
        for variable in variables:
            role = "compensator" if bool(variable.get("compensator", True)) else "tolerance-only"
            coupling_group = str(variable.get("coupling_group", "") or "").strip()
            coupling = ""
            if coupling_group:
                coupling = ", coupling={}{}".format(
                    "-" if int(variable.get("coupling_sign", 1) or 1) < 0 else "",
                    coupling_group,
                )
            manufacturing = self._format_tolerance_manufacturing_inline(dict(variable))
            lines.append(
                "- {name}: nominal={nominal:.6g}, bounds=[{lower:.6g}, {upper:.6g}], role={role}{coupling}{manufacturing}".format(
                    name=variable.get("name", ""),
                    nominal=float(variable.get("nominal", np.nan)),
                    lower=float(variable.get("lower", np.nan)),
                    upper=float(variable.get("upper", np.nan)),
                    role=role,
                    coupling=coupling,
                    manufacturing=manufacturing,
                )
            )
        lines.extend(
            [
                "",
                f"Total merit: {self._format_stats_line(dict(summary.get('total_merit_stats', {}) or {}))}",
                (
                    f"Worst sample: {summary.get('worst_sample')} "
                    f"(total merit={float(summary.get('worst_total_merit', np.nan)):.6g})"
                ),
                "",
                "Top samples by total merit:",
            ]
        )
        top_records = sorted(
            [record for record in records if bool(record.get("valid"))],
            key=lambda record: float(record.get("total_merit", -np.inf)),
            reverse=True,
        )[:5]
        for record in top_records:
            lines.append(
                "- sample={sample} kind={kind} merit={merit:.6g} message={message}".format(
                    sample=int(record.get("sample", 0) or 0),
                    kind=record.get("kind", ""),
                    merit=float(record.get("total_merit", np.nan)),
                    message=record.get("message", ""),
                )
            )
        return "\n".join(lines).strip() + "\n"

    def open_tolerance_monte_carlo_report(self) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Tolerance Monte Carlo", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        preset = self._active_tolerance_solve_preset()
        sample_count = simpledialog.askinteger(
            "Tolerance Monte Carlo",
            "Monte Carlo sample count",
            initialvalue=self._tolerance_preset_int(preset.get("sample_count", 25), 25, 1, 1000),
            minvalue=1,
            maxvalue=1000,
            parent=self,
        )
        if sample_count is None:
            return
        seed = simpledialog.askinteger(
            "Tolerance Monte Carlo",
            "Random seed",
            initialvalue=self._tolerance_preset_int(preset.get("seed", 12345), 12345, 0, 2**31 - 1),
            minvalue=0,
            maxvalue=2**31 - 1,
            parent=self,
        )
        if seed is None:
            return
        self._begin_analysis_progress("Tolerance Monte Carlo")
        try:
            summary = self.run_tolerance_monte_carlo(sample_count=int(sample_count), seed=int(seed))
            report = self.tolerance_monte_carlo_report_text(summary)
            self.append_debug(report)
            ok, backend = self._copy_text_to_clipboard(report)
            if ok:
                self.status_var.set(f"Tolerance Monte Carlo report copied to clipboard ({backend}).")
            else:
                self.status_var.set("Tolerance Monte Carlo report written to Debug; clipboard unavailable.")
            self._finish_analysis_progress("Tolerance Monte Carlo", success=True)
        except Exception as exc:
            self._finish_analysis_progress("Tolerance Monte Carlo", success=False)
            self.append_debug(f"Tolerance Monte Carlo failed: {traceback.format_exc()}")
            messagebox.showerror("Tolerance Monte Carlo", str(exc), parent=self)

    def export_tolerance_monte_carlo_csv(self) -> None:
        records = list(getattr(self, "_last_tolerance_monte_carlo_records", []) or [])
        if not records:
            messagebox.showinfo("Export Tolerance Monte Carlo", "Run Tolerance Monte Carlo Report first.", parent=self)
            return
        path = filedialog.asksaveasfilename(
            title="Export Tolerance Monte Carlo CSV",
            defaultextension=".csv",
            filetypes=[("CSV files", "*.csv"), ("All files", "*")],
            parent=self,
        )
        if not path:
            return
        columns: list[str] = []
        for preferred in ("sample", "kind", "valid", "total_merit", "message"):
            if any(preferred in record for record in records):
                columns.append(preferred)
        for record in records:
            for key in record:
                if key not in columns:
                    columns.append(str(key))
        with open(path, "w", newline="", encoding="utf-8") as handle:
            writer = csv.DictWriter(handle, fieldnames=columns, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(records)
        self.status_var.set(f"Tolerance Monte Carlo CSV exported: {Path(path).name}")

    @staticmethod
    def _tolerance_record_float(record: dict[str, object], key: str, default: float = np.nan) -> float:
        try:
            value = float(record.get(key, default))
        except Exception:
            return float(default)
        return value if np.isfinite(value) else float(default)

    @staticmethod
    def _tolerance_relative_delta(nominal: float, perturbed: float) -> float:
        if not np.isfinite(nominal) or abs(float(nominal)) <= 1e-18:
            return np.nan
        return (float(perturbed) - float(nominal)) / abs(float(nominal))

    @staticmethod
    def _tolerance_metric_label(key: str) -> str:
        text = str(key or "").replace("_", " ").strip()
        return text.title() if text else "Metric"

    @staticmethod
    def _tolerance_variable_key(variable: dict[str, object] | OpticalVariable) -> str:
        if isinstance(variable, OpticalVariable):
            surface_index = int(variable.surface_index)
            parameter = str(variable.parameter)
        else:
            surface_index = int(variable.get("surface_index", -1))
            parameter = str(variable.get("parameter", "") or "")
        return f"var_s{surface_index}_{parameter.lower()}"

    @staticmethod
    def _row_tolerance_compensator_names(row: SurfaceRow) -> tuple[str, ...]:
        advanced = dict(getattr(row, "advanced", {}) or {})
        value = advanced.get(TOLERANCE_COMPENSATORS_ADVANCED_ATTR)
        if isinstance(value, dict):
            return tuple(str(key).strip() for key, enabled in value.items() if enabled and str(key).strip())
        if isinstance(value, str):
            return tuple(part.strip() for part in re.split(r"[,;\n]+", value) if part.strip())
        if isinstance(value, (list, tuple, set)):
            return tuple(str(item).strip() for item in value if str(item).strip())
        return ()

    @staticmethod
    def _row_has_tolerance_compensator_metadata(row: SurfaceRow) -> bool:
        return TOLERANCE_COMPENSATORS_ADVANCED_ATTR in dict(getattr(row, "advanced", {}) or {})

    @classmethod
    def _row_tolerance_compensator_enabled(cls, row: SurfaceRow, parameter: str) -> bool:
        return any(_native_variable_matches(candidate, parameter) for candidate in cls._row_tolerance_compensator_names(row))

    def _has_explicit_tolerance_compensators(self) -> bool:
        return any(self._row_has_tolerance_compensator_metadata(row) for row in self.rows)

    def _tolerance_variable_compensator_enabled(self, variable: OpticalVariable) -> bool:
        if not self._has_explicit_tolerance_compensators():
            return True
        surface_index = int(variable.surface_index)
        if surface_index < 0 or surface_index >= len(self.rows):
            return False
        return self._row_tolerance_compensator_enabled(self.rows[surface_index], str(variable.parameter))

    def set_tolerance_compensator_enabled(self, surface_index: int, parameter: str, enabled: bool) -> None:
        if surface_index < 0 or surface_index >= len(self.rows):
            raise IndexError(f"Surface index out of range: {surface_index}")
        if not enabled and not self._has_explicit_tolerance_compensators():
            for candidate_row in self.rows:
                names = []
                for spec in VARIABLE_REGISTRY.values():
                    if spec.is_supported(candidate_row) and self._variable_enabled_for_row(candidate_row, spec):
                        names.append(str(spec.parameter))
                if names:
                    candidate_row.advanced = dict(candidate_row.advanced or {})
                    candidate_row.advanced[TOLERANCE_COMPENSATORS_ADVANCED_ATTR] = names
        row = self.rows[int(surface_index)]
        advanced = dict(row.advanced or {})
        names = [
            candidate
            for candidate in self._row_tolerance_compensator_names(row)
            if not _native_variable_matches(candidate, parameter)
        ]
        if enabled:
            names.append(str(parameter))
        if names:
            advanced[TOLERANCE_COMPENSATORS_ADVANCED_ATTR] = names
        elif not enabled:
            advanced[TOLERANCE_COMPENSATORS_ADVANCED_ATTR] = []
        else:
            advanced.pop(TOLERANCE_COMPENSATORS_ADVANCED_ATTR, None)
        row.advanced = advanced

    @staticmethod
    def _tolerance_coupling_sign(value: object) -> int:
        if isinstance(value, str):
            text = value.strip().lower()
            if text in {"-1", "-", "opposite", "opposed", "inverse", "inverted", "anti"}:
                return -1
            if text in {"1", "+", "+1", "same", "linked", "common"}:
                return 1
        try:
            numeric = float(value)
        except Exception:
            return 1
        return -1 if numeric < 0.0 else 1

    @classmethod
    def _normalize_tolerance_coupling_payload(cls, value: object) -> dict[str, dict[str, object]]:
        couplings: dict[str, dict[str, object]] = {}

        def add(parameter: object, group: object, sign: object = 1) -> None:
            parameter_text = str(parameter or "").strip()
            group_text = str(group or "").strip()
            if not parameter_text or not group_text:
                return
            couplings[parameter_text] = {
                "group": group_text,
                "sign": cls._tolerance_coupling_sign(sign),
            }

        if isinstance(value, dict):
            if "parameter" in value and "group" in value:
                add(value.get("parameter"), value.get("group"), value.get("sign", value.get("direction", 1)))
            else:
                for parameter, payload in value.items():
                    if isinstance(payload, dict):
                        add(parameter, payload.get("group", payload.get("name", "")), payload.get("sign", payload.get("direction", 1)))
                    elif isinstance(payload, (list, tuple)) and payload:
                        add(parameter, payload[0], payload[1] if len(payload) > 1 else 1)
                    else:
                        text = str(payload or "").strip()
                        sign = -1 if text.startswith("-") else 1
                        add(parameter, text[1:].strip() if sign < 0 else text, sign)
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, dict):
                    add(item.get("parameter"), item.get("group", item.get("name", "")), item.get("sign", item.get("direction", 1)))
                elif isinstance(item, (list, tuple)) and len(item) >= 2:
                    add(item[0], item[1], item[2] if len(item) > 2 else 1)
        return couplings

    @classmethod
    def _row_tolerance_couplings(cls, row: SurfaceRow) -> dict[str, dict[str, object]]:
        advanced = dict(getattr(row, "advanced", {}) or {})
        return cls._normalize_tolerance_coupling_payload(advanced.get(TOLERANCE_COUPLING_ADVANCED_ATTR))

    @classmethod
    def _row_tolerance_coupling(cls, row: SurfaceRow, parameter: str) -> dict[str, object]:
        for candidate, payload in cls._row_tolerance_couplings(row).items():
            if _native_variable_matches(candidate, parameter):
                group = str(payload.get("group", "") or "").strip()
                if group:
                    return {"group": group, "sign": cls._tolerance_coupling_sign(payload.get("sign", 1))}
        return {}

    def _tolerance_variable_coupling(self, variable: OpticalVariable) -> dict[str, object]:
        surface_index = int(variable.surface_index)
        if surface_index < 0 or surface_index >= len(self.rows):
            return {}
        return self._row_tolerance_coupling(self.rows[surface_index], str(variable.parameter))

    def set_tolerance_coupling(self, surface_index: int, parameter: str, group: str, *, sign: int = 1) -> None:
        if surface_index < 0 or surface_index >= len(self.rows):
            raise IndexError(f"Surface index out of range: {surface_index}")
        group_text = str(group or "").strip()
        if not group_text:
            self.clear_tolerance_coupling(surface_index, parameter)
            return
        row = self.rows[int(surface_index)]
        advanced = dict(row.advanced or {})
        couplings = self._row_tolerance_couplings(row)
        for candidate in list(couplings):
            if _native_variable_matches(candidate, parameter):
                couplings.pop(candidate, None)
        couplings[str(parameter)] = {
            "group": group_text,
            "sign": self._tolerance_coupling_sign(sign),
        }
        advanced[TOLERANCE_COUPLING_ADVANCED_ATTR] = couplings
        row.advanced = advanced

    def clear_tolerance_coupling(self, surface_index: int, parameter: str) -> None:
        if surface_index < 0 or surface_index >= len(self.rows):
            raise IndexError(f"Surface index out of range: {surface_index}")
        row = self.rows[int(surface_index)]
        advanced = dict(row.advanced or {})
        couplings = self._row_tolerance_couplings(row)
        for candidate in list(couplings):
            if _native_variable_matches(candidate, parameter):
                couplings.pop(candidate, None)
        if couplings:
            advanced[TOLERANCE_COUPLING_ADVANCED_ATTR] = couplings
        else:
            advanced.pop(TOLERANCE_COUPLING_ADVANCED_ATTR, None)
        row.advanced = advanced

    def edit_current_tolerance_coupling(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None or not self._variable_enabled_for_row(row, spec):
            return
        current = self._row_tolerance_coupling(row, spec.parameter)
        initial = ""
        if current:
            sign_prefix = "-" if int(current.get("sign", 1) or 1) < 0 else ""
            initial = f"{sign_prefix}{current.get('group', '')}"
        value = simpledialog.askstring(
            "Tolerance Coupling",
            "Group name for shared random quantile. Prefix with '-' for inverted/opposite motion. Blank clears coupling.",
            initialvalue=initial,
            parent=self,
        )
        if value is None:
            return
        text = str(value).strip()
        self._begin_history_capture()
        if not text:
            self.clear_tolerance_coupling(index, spec.parameter)
            message = f"Cleared tolerance coupling for row {index} {spec.label}."
        else:
            sign = -1 if text.startswith("-") else 1
            group = text[1:].strip() if sign < 0 else text
            self.set_tolerance_coupling(index, spec.parameter, group, sign=sign)
            message = f"Row {index} {spec.label} tolerance coupling: {'-' if sign < 0 else ''}{group}."
        self._sync_table()
        self._commit_history_capture()
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    def clear_current_tolerance_coupling(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None:
            return
        self._begin_history_capture()
        self.clear_tolerance_coupling(index, spec.parameter)
        self._sync_table()
        self._commit_history_capture()
        message = f"Cleared tolerance coupling for row {index} {spec.label}."
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    @staticmethod
    def _tolerance_manufacturing_tags(value: object) -> tuple[str, ...]:
        if value is None:
            return ()
        if isinstance(value, str):
            return tuple(part.strip() for part in re.split(r"[,;\n]+", value) if part.strip())
        if isinstance(value, (list, tuple, set)):
            return tuple(str(item).strip() for item in value if str(item).strip())
        return (str(value).strip(),) if str(value).strip() else ()

    @classmethod
    def _normalize_tolerance_manufacturing_payload(cls, value: object) -> dict[str, dict[str, object]]:
        records: dict[str, dict[str, object]] = {}

        def add(
            parameter: object,
            *,
            source_type: object = "",
            source_id: object = "",
            note: object = "",
            tags: object = (),
        ) -> None:
            parameter_text = str(parameter or "").strip()
            payload = {
                "source_type": str(source_type or "").strip(),
                "source_id": str(source_id or "").strip(),
                "note": str(note or "").strip(),
                "tags": list(cls._tolerance_manufacturing_tags(tags)),
            }
            if parameter_text and (
                any(payload[key] for key in ("source_type", "source_id", "note")) or payload["tags"]
            ):
                records[parameter_text] = payload

        def source_type_from(payload: dict[str, object]) -> object:
            return payload.get(
                "manufacturing_source_type",
                payload.get("source_type", payload.get("type", payload.get("process", ""))),
            )

        def source_id_from(payload: dict[str, object]) -> object:
            return payload.get(
                "manufacturing_source_id",
                payload.get("source_id", payload.get("id", payload.get("spec_id", payload.get("vendor_spec", "")))),
            )

        def note_from(payload: dict[str, object]) -> object:
            return payload.get("manufacturing_note", payload.get("note", payload.get("notes", "")))

        def tags_from(payload: dict[str, object]) -> object:
            return payload.get("manufacturing_tags", payload.get("tags", payload.get("tag", ())))

        if isinstance(value, dict):
            if "parameter" in value:
                add(
                    value.get("parameter"),
                    source_type=source_type_from(value),
                    source_id=source_id_from(value),
                    note=note_from(value),
                    tags=tags_from(value),
                )
            else:
                for parameter, payload in value.items():
                    if isinstance(payload, dict):
                        add(
                            parameter,
                            source_type=source_type_from(payload),
                            source_id=source_id_from(payload),
                            note=note_from(payload),
                            tags=tags_from(payload),
                        )
                    elif isinstance(payload, (list, tuple)):
                        add(
                            parameter,
                            source_type=payload[0] if len(payload) > 0 else "",
                            source_id=payload[1] if len(payload) > 1 else "",
                            tags=payload[2] if len(payload) > 2 else (),
                            note=payload[3] if len(payload) > 3 else "",
                        )
                    else:
                        add(parameter, source_type=payload)
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, dict):
                    add(
                        item.get("parameter"),
                        source_type=source_type_from(item),
                        source_id=source_id_from(item),
                        note=note_from(item),
                        tags=tags_from(item),
                    )
                elif isinstance(item, (list, tuple)) and item:
                    add(
                        item[0],
                        source_type=item[1] if len(item) > 1 else "",
                        source_id=item[2] if len(item) > 2 else "",
                        tags=item[3] if len(item) > 3 else (),
                        note=item[4] if len(item) > 4 else "",
                    )
        return records

    @classmethod
    def _row_tolerance_manufacturing(cls, row: SurfaceRow, parameter: str) -> dict[str, object]:
        advanced = dict(getattr(row, "advanced", {}) or {})
        for candidate, payload in cls._normalize_tolerance_manufacturing_payload(
            advanced.get(TOLERANCE_MANUFACTURING_ADVANCED_ATTR)
        ).items():
            if _native_variable_matches(candidate, parameter):
                return dict(payload)
        return {}

    def _tolerance_variable_manufacturing(self, variable: OpticalVariable) -> dict[str, object]:
        surface_index = int(variable.surface_index)
        if surface_index < 0 or surface_index >= len(self.rows):
            return {}
        return self._row_tolerance_manufacturing(self.rows[surface_index], str(variable.parameter))

    @staticmethod
    def _tolerance_manufacturing_record_fields(metadata: dict[str, object]) -> dict[str, object]:
        if not metadata:
            return {}
        tags_value = metadata.get("manufacturing_tags", metadata.get("tags", []))
        tags = "; ".join(
            str(tag).strip()
            for tag in KrakenLayoutEditor._tolerance_manufacturing_tags(tags_value)
            if str(tag).strip()
        )
        fields = {
            "manufacturing_source_type": str(
                metadata.get("manufacturing_source_type", metadata.get("source_type", "")) or ""
            ).strip(),
            "manufacturing_source_id": str(
                metadata.get("manufacturing_source_id", metadata.get("source_id", "")) or ""
            ).strip(),
            "manufacturing_note": str(metadata.get("manufacturing_note", metadata.get("note", "")) or "").strip(),
            "manufacturing_tags": tags,
        }
        return {key: value for key, value in fields.items() if str(value).strip()}

    @staticmethod
    def _format_tolerance_manufacturing_inline(record: dict[str, object]) -> str:
        source_type = str(record.get("manufacturing_source_type", "") or "").strip()
        source_id = str(record.get("manufacturing_source_id", "") or "").strip()
        tags = str(record.get("manufacturing_tags", "") or "").strip()
        note = str(record.get("manufacturing_note", "") or "").strip()
        parts: list[str] = []
        if source_type or source_id:
            if source_type and source_id:
                parts.append(f"source={source_type}:{source_id}")
            else:
                parts.append(f"source={source_type or source_id}")
        if tags:
            parts.append(f"tags={tags}")
        if note:
            parts.append(f"note={note}")
        return "" if not parts else ", " + ", ".join(parts)

    def set_tolerance_manufacturing_metadata(
        self,
        surface_index: int,
        parameter: str,
        *,
        source_type: str = "",
        source_id: str = "",
        tags: object = (),
        note: str = "",
    ) -> None:
        if surface_index < 0 or surface_index >= len(self.rows):
            raise IndexError(f"Surface index out of range: {surface_index}")
        metadata = self._tolerance_manufacturing_record_fields(
            {
                "source_type": source_type,
                "source_id": source_id,
                "tags": self._tolerance_manufacturing_tags(tags),
                "note": note,
            }
        )
        if not metadata:
            self.clear_tolerance_manufacturing_metadata(surface_index, parameter)
            return
        row = self.rows[int(surface_index)]
        advanced = dict(row.advanced or {})
        records = self._normalize_tolerance_manufacturing_payload(advanced.get(TOLERANCE_MANUFACTURING_ADVANCED_ATTR))
        for candidate in list(records):
            if _native_variable_matches(candidate, parameter):
                records.pop(candidate, None)
        records[str(parameter)] = {
            "source_type": str(metadata.get("manufacturing_source_type", "") or ""),
            "source_id": str(metadata.get("manufacturing_source_id", "") or ""),
            "note": str(metadata.get("manufacturing_note", "") or ""),
            "tags": self._tolerance_manufacturing_tags(metadata.get("manufacturing_tags", "")),
        }
        advanced[TOLERANCE_MANUFACTURING_ADVANCED_ATTR] = records
        row.advanced = advanced

    def clear_tolerance_manufacturing_metadata(self, surface_index: int, parameter: str) -> None:
        if surface_index < 0 or surface_index >= len(self.rows):
            raise IndexError(f"Surface index out of range: {surface_index}")
        row = self.rows[int(surface_index)]
        advanced = dict(row.advanced or {})
        records = self._normalize_tolerance_manufacturing_payload(advanced.get(TOLERANCE_MANUFACTURING_ADVANCED_ATTR))
        for candidate in list(records):
            if _native_variable_matches(candidate, parameter):
                records.pop(candidate, None)
        if records:
            advanced[TOLERANCE_MANUFACTURING_ADVANCED_ATTR] = records
        else:
            advanced.pop(TOLERANCE_MANUFACTURING_ADVANCED_ATTR, None)
        row.advanced = advanced

    def edit_current_tolerance_manufacturing(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None or not self._variable_enabled_for_row(row, spec):
            return
        current = self._row_tolerance_manufacturing(row, spec.parameter)
        initial = " | ".join(
            [
                str(current.get("source_type", "") or ""),
                str(current.get("source_id", "") or ""),
                "; ".join(str(tag) for tag in list(current.get("tags", []) or [])),
                str(current.get("note", "") or ""),
            ]
        ).strip()
        value = simpledialog.askstring(
            "Tolerance Manufacturing Metadata",
            "Enter: source type | source/spec ID | tags | note. Blank clears metadata.",
            initialvalue=initial,
            parent=self,
        )
        if value is None:
            return
        text = str(value).strip()
        self._begin_history_capture()
        if not text:
            self.clear_tolerance_manufacturing_metadata(index, spec.parameter)
            message = f"Cleared manufacturing metadata for row {index} {spec.label}."
        else:
            parts = [part.strip() for part in text.split("|")]
            while len(parts) < 4:
                parts.append("")
            self.set_tolerance_manufacturing_metadata(
                index,
                spec.parameter,
                source_type=parts[0],
                source_id=parts[1],
                tags=parts[2],
                note=parts[3],
            )
            message = f"Row {index} {spec.label} manufacturing metadata: {parts[0] or parts[1] or parts[2] or 'set'}."
        self._sync_table()
        self._commit_history_capture()
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    def clear_current_tolerance_manufacturing(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None:
            return
        self._begin_history_capture()
        self.clear_tolerance_manufacturing_metadata(index, spec.parameter)
        self._sync_table()
        self._commit_history_capture()
        message = f"Cleared manufacturing metadata for row {index} {spec.label}."
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    @classmethod
    def _normalize_tolerance_manufacturing_template(
        cls,
        value: object,
        *,
        fallback_name: str = "Manufacturing source",
    ) -> dict[str, object]:
        if not isinstance(value, dict):
            return {}
        fields = cls._tolerance_manufacturing_record_fields(value)
        if not fields:
            return {}
        name = str(
            value.get(
                "name",
                value.get(
                    "label",
                    fields.get("manufacturing_source_id", fields.get("manufacturing_source_type", fallback_name)),
                ),
            )
            or fallback_name
        ).strip()
        if not name:
            return {}
        return {
            "name": name,
            "source_type": str(fields.get("manufacturing_source_type", "") or ""),
            "source_id": str(fields.get("manufacturing_source_id", "") or ""),
            "tags": list(cls._tolerance_manufacturing_tags(fields.get("manufacturing_tags", ""))),
            "note": str(fields.get("manufacturing_note", "") or ""),
        }

    @classmethod
    def _normalize_tolerance_manufacturing_templates(cls, value: object) -> list[dict[str, object]]:
        raw_items: list[object]
        if isinstance(value, dict):
            if isinstance(value.get("templates"), (list, tuple)):
                raw_items = list(value.get("templates", []) or [])
            elif "name" in value:
                raw_items = [value]
            else:
                raw_items = [
                    dict(payload, name=str(name))
                    for name, payload in value.items()
                    if isinstance(payload, dict)
                ]
        elif isinstance(value, (list, tuple)):
            raw_items = list(value)
        else:
            raw_items = []
        templates: list[dict[str, object]] = []
        seen_names: set[str] = set()
        for index, item in enumerate(raw_items, start=1):
            template = cls._normalize_tolerance_manufacturing_template(item, fallback_name=f"Template {index}")
            name = str(template.get("name", "") or "")
            if not name or name in seen_names:
                continue
            seen_names.add(name)
            templates.append(template)
        return templates

    def _tolerance_manufacturing_template_by_name(self, name: str) -> dict[str, object] | None:
        wanted = str(name or "").strip()
        for template in self._normalize_tolerance_manufacturing_templates(
            self.__dict__.get("tolerance_manufacturing_templates", [])
        ):
            if str(template.get("name", "")) == wanted:
                return dict(template)
        wanted_lower = wanted.lower()
        for template in self._normalize_tolerance_manufacturing_templates(
            self.__dict__.get("tolerance_manufacturing_templates", [])
        ):
            if str(template.get("name", "")).lower() == wanted_lower:
                return dict(template)
        return None

    def add_tolerance_manufacturing_template(
        self,
        name: str,
        *,
        source_type: str = "",
        source_id: str = "",
        tags: object = (),
        note: str = "",
    ) -> dict[str, object]:
        template = self._normalize_tolerance_manufacturing_template(
            {
                "name": name,
                "source_type": source_type,
                "source_id": source_id,
                "tags": tags,
                "note": note,
            }
        )
        if not template:
            raise ValueError("Manufacturing template requires a name and at least one metadata field.")
        templates = [
            existing
            for existing in self._normalize_tolerance_manufacturing_templates(
                self.__dict__.get("tolerance_manufacturing_templates", [])
            )
            if str(existing.get("name", "")) != str(template.get("name", ""))
        ]
        templates.append(template)
        self.tolerance_manufacturing_templates = templates
        return dict(template)

    def apply_tolerance_manufacturing_template(
        self,
        surface_index: int,
        parameter: str,
        template_or_name: str | dict[str, object],
    ) -> dict[str, object]:
        if isinstance(template_or_name, dict):
            template = self._normalize_tolerance_manufacturing_template(template_or_name)
        else:
            template = self._tolerance_manufacturing_template_by_name(str(template_or_name)) or {}
        if not template:
            raise ValueError("Manufacturing template was not found.")
        self.set_tolerance_manufacturing_metadata(
            surface_index,
            parameter,
            source_type=str(template.get("source_type", "") or ""),
            source_id=str(template.get("source_id", "") or ""),
            tags=template.get("tags", ()),
            note=str(template.get("note", "") or ""),
        )
        return dict(template)

    def save_current_tolerance_manufacturing_template(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None:
            return
        metadata = self._row_tolerance_manufacturing(row, spec.parameter)
        if not metadata:
            self._cleanup_current_popup_menu()
            return
        default_name = str(metadata.get("source_id", "") or metadata.get("source_type", "") or f"{row.name} {spec.label}")
        name = simpledialog.askstring(
            "Save Manufacturing Template",
            "Template name:",
            initialvalue=default_name,
            parent=self,
        )
        if name is None:
            return
        name_text = str(name).strip()
        if not name_text:
            self._cleanup_current_popup_menu()
            return
        self._begin_history_capture()
        template = self.add_tolerance_manufacturing_template(
            name_text,
            source_type=str(metadata.get("source_type", "") or ""),
            source_id=str(metadata.get("source_id", "") or ""),
            tags=metadata.get("tags", ()),
            note=str(metadata.get("note", "") or ""),
        )
        self._commit_history_capture()
        message = f"Saved manufacturing template: {template.get('name', '')}."
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    def apply_current_tolerance_manufacturing_template(self) -> None:
        if self.current_menu_row_id is None or self.current_menu_field is None:
            return
        index = self._table_item_row_index(self.current_menu_row_id)
        if index is None:
            return
        row = self.rows[index]
        spec = self._variable_spec_for_field(self.current_menu_field)
        if spec is None or not self._variable_enabled_for_row(row, spec):
            return
        templates = self._normalize_tolerance_manufacturing_templates(
            self.__dict__.get("tolerance_manufacturing_templates", [])
        )
        if not templates:
            self._cleanup_current_popup_menu()
            return
        names = [str(template.get("name", "") or "") for template in templates if str(template.get("name", "") or "")]
        value = simpledialog.askstring(
            "Apply Manufacturing Template",
            "Enter template name.\nAvailable: " + ", ".join(names),
            initialvalue=names[0] if names else "",
            parent=self,
        )
        if value is None:
            return
        template_name = str(value).strip()
        if not template_name:
            self._cleanup_current_popup_menu()
            return
        template = self._tolerance_manufacturing_template_by_name(template_name)
        if template is None:
            messagebox.showerror(
                "Manufacturing Template",
                f"Template not found: {template_name}",
                parent=self,
            )
            self._cleanup_current_popup_menu()
            return
        self._begin_history_capture()
        self.apply_tolerance_manufacturing_template(index, spec.parameter, template)
        self._sync_table()
        self._commit_history_capture()
        message = f"Applied manufacturing template {template.get('name', '')} to row {index} {spec.label}."
        self.append_progress(message)
        self.status_var.set(message)
        self._cleanup_current_popup_menu()

    @staticmethod
    def _tolerance_preset_int(value: object, default: int, min_value: int, max_value: int) -> int:
        try:
            parsed = int(value)
        except Exception:
            parsed = int(default)
        return max(int(min_value), min(int(max_value), int(parsed)))

    @staticmethod
    def _tolerance_preset_bool(value: object, default: bool = True) -> bool:
        if isinstance(value, str):
            text = value.strip().lower()
            if text in {"1", "true", "yes", "on", "compensator", "enabled"}:
                return True
            if text in {"0", "false", "no", "off", "tolerance-only", "disabled"}:
                return False
        if value is None:
            return bool(default)
        return bool(value)

    @classmethod
    def _normalize_tolerance_solve_preset(
        cls,
        value: object,
        *,
        fallback_name: str = "Tolerance solve",
    ) -> dict[str, object]:
        if not isinstance(value, dict):
            return {}
        name = str(value.get("name", fallback_name) or fallback_name).strip()
        if not name:
            return {}
        compare_view = str(value.get("tolerance_compare_view", TOLERANCE_COMPARE_VIEW_DEFAULT) or "").strip()
        if compare_view not in TOLERANCE_COMPARE_VIEW_VALUES:
            compare_view = TOLERANCE_COMPARE_VIEW_DEFAULT
        selected_operands = [
            str(label).strip()
            for label in list(value.get("selected_operands", []) or [])
            if str(label).strip()
        ]
        operands: dict[str, dict[str, object]] = {}
        raw_operands = value.get("operands", {})
        if isinstance(raw_operands, dict):
            for label, payload in raw_operands.items():
                if not isinstance(payload, dict):
                    continue
                clean_payload: dict[str, object] = {}
                for key, item in payload.items():
                    if isinstance(item, (str, int, float, bool)) or item is None:
                        clean_payload[str(key)] = item
                    else:
                        clean_payload[str(key)] = str(item)
                if clean_payload:
                    operands[str(label)] = clean_payload
        compensators: list[dict[str, object]] = []
        seen_compensators: set[tuple[int, str]] = set()
        for item in list(value.get("compensators", []) or []):
            if not isinstance(item, dict):
                continue
            try:
                surface_index = int(item.get("surface_index", -1))
            except Exception:
                surface_index = -1
            parameter = str(item.get("parameter", "") or "").strip()
            if surface_index < 0 or not parameter:
                continue
            key = (surface_index, parameter.lower())
            if key in seen_compensators:
                continue
            seen_compensators.add(key)
            enabled_value = item.get("compensator", item.get("enabled", True))
            coupling_group = str(item.get("coupling_group", "") or "").strip()
            if not coupling_group and "coupling" in item:
                coupling_text = str(item.get("coupling", "") or "").strip()
                coupling_group = coupling_text[1:].strip() if coupling_text.startswith("-") else coupling_text
                item = dict(item)
                item.setdefault("coupling_sign", -1 if coupling_text.startswith("-") else 1)
            manufacturing = cls._tolerance_manufacturing_record_fields(
                {
                    "source_type": item.get("manufacturing_source_type", item.get("source_type", item.get("process", ""))),
                    "source_id": item.get("manufacturing_source_id", item.get("source_id", item.get("spec_id", ""))),
                    "tags": item.get("manufacturing_tags", item.get("tags", ())),
                    "note": item.get("manufacturing_note", item.get("note", "")),
                }
            )
            compensators.append(
                {
                    "surface_index": surface_index,
                    "surface_name": str(item.get("surface_name", "") or ""),
                    "parameter": parameter,
                    "name": str(item.get("name", "") or ""),
                    "nominal": item.get("nominal", ""),
                    "lower": item.get("lower", ""),
                    "upper": item.get("upper", ""),
                    "compensator": cls._tolerance_preset_bool(enabled_value, True),
                    **(
                        {
                            "coupling_group": coupling_group,
                            "coupling_sign": cls._tolerance_coupling_sign(
                                item.get("coupling_sign", item.get("coupling_direction", 1))
                            ),
                        }
                        if coupling_group or "coupling_group" in item or "coupling_sign" in item or "coupling" in item
                        else {}
                    ),
                    **manufacturing,
                }
            )
        return {
            "name": name,
            "sample_count": cls._tolerance_preset_int(
                value.get("sample_count", TOLERANCE_SOLVE_PRESET_DEFAULTS["sample_count"]), 25, 1, 1000
            ),
            "seed": cls._tolerance_preset_int(
                value.get("seed", TOLERANCE_SOLVE_PRESET_DEFAULTS["seed"]), 12345, 0, 2**31 - 1
            ),
            "compensator_steps": cls._tolerance_preset_int(
                value.get("compensator_steps", TOLERANCE_SOLVE_PRESET_DEFAULTS["compensator_steps"]), 9, 3, 101
            ),
            "multi_steps": cls._tolerance_preset_int(
                value.get("multi_steps", TOLERANCE_SOLVE_PRESET_DEFAULTS["multi_steps"]), 5, 3, 51
            ),
            "multi_passes": cls._tolerance_preset_int(
                value.get("multi_passes", TOLERANCE_SOLVE_PRESET_DEFAULTS["multi_passes"]), 2, 1, 20
            ),
            "tolerance_compare_view": compare_view,
            "selected_operands": selected_operands,
            "operands": operands,
            "compensator_policy": str(value.get("compensator_policy", "explicit") or "explicit"),
            "coupling_policy": str(value.get("coupling_policy", "preserve") or "preserve"),
            "manufacturing_policy": str(value.get("manufacturing_policy", "preserve") or "preserve"),
            "compensators": compensators,
        }

    @classmethod
    def _normalize_tolerance_solve_presets(cls, value: object) -> list[dict[str, object]]:
        raw_items: list[object]
        if isinstance(value, dict):
            if isinstance(value.get("presets"), (list, tuple)):
                raw_items = list(value.get("presets", []) or [])
            elif "name" in value:
                raw_items = [value]
            else:
                raw_items = [
                    dict(payload, name=str(name))
                    for name, payload in value.items()
                    if isinstance(payload, dict)
                ]
        elif isinstance(value, (list, tuple)):
            raw_items = list(value)
        else:
            raw_items = []
        presets: list[dict[str, object]] = []
        seen_names: set[str] = set()
        for index, item in enumerate(raw_items, start=1):
            preset = cls._normalize_tolerance_solve_preset(item, fallback_name=f"Preset {index}")
            name = str(preset.get("name", "") or "")
            if not name or name in seen_names:
                continue
            seen_names.add(name)
            presets.append(preset)
        return presets

    def _active_tolerance_solve_preset(self) -> dict[str, object]:
        presets = self._normalize_tolerance_solve_presets(getattr(self, "tolerance_solve_presets", []))
        active_name = str(getattr(self, "active_tolerance_solve_preset_name", "") or "").strip()
        for preset in presets:
            if str(preset.get("name", "")) == active_name:
                return dict(preset)
        return dict(presets[0]) if presets else {}

    def _tolerance_solve_preset_by_name(self, name: str) -> dict[str, object] | None:
        wanted = str(name or "").strip()
        for preset in self._normalize_tolerance_solve_presets(getattr(self, "tolerance_solve_presets", [])):
            if str(preset.get("name", "")) == wanted:
                return dict(preset)
        return None

    def _current_tolerance_preset_operands(self) -> tuple[list[str], dict[str, dict[str, object]]]:
        selected = self._selected_operand_labels()
        operands: dict[str, dict[str, object]] = {}
        var_maps = (
            ("weight", getattr(self, "operand_weight_vars", {}) or {}),
            ("target", getattr(self, "operand_target_vars", {}) or {}),
            ("wavelength", getattr(self, "operand_wavelength_vars", {}) or {}),
            ("field", getattr(self, "operand_field_vars", {}) or {}),
            ("field_x", getattr(self, "operand_field_x_vars", {}) or {}),
            ("field_y", getattr(self, "operand_field_y_vars", {}) or {}),
            ("surface", getattr(self, "operand_surface_vars", {}) or {}),
            ("aperture_type", getattr(self, "operand_aperture_type_vars", {}) or {}),
            ("aperture_value", getattr(self, "operand_aperture_value_vars", {}) or {}),
            ("frequency", getattr(self, "operand_frequency_vars", {}) or {}),
            ("mtf_mode", getattr(self, "operand_mtf_mode_vars", {}) or {}),
            ("mtf_algorithm", getattr(self, "operand_mtf_algorithm_vars", {}) or {}),
        )
        labels = {spec.label for spec in OPERAND_REGISTRY.values()}
        labels.update(selected)
        for _key, mapping in var_maps:
            labels.update(str(label) for label in mapping)
        for label in labels:
            payload: dict[str, object] = {}
            for key, mapping in var_maps:
                var = mapping.get(label)
                if var is not None:
                    try:
                        payload[key] = var.get()
                    except Exception:
                        pass
            if payload:
                operands[str(label)] = payload
        return selected, operands

    def _current_tolerance_compensator_preset_payload(self) -> list[dict[str, object]]:
        payload: list[dict[str, object]] = []
        for variable in self._build_optimization_variables():
            surface_index = int(variable.surface_index)
            row = self.rows[surface_index]
            coupling = self._tolerance_variable_coupling(variable)
            manufacturing = self._tolerance_variable_manufacturing(variable)
            try:
                nominal = float(self._optimization_value_from_row(row, variable))
            except Exception:
                nominal = float("nan")
            payload.append(
                {
                    "surface_index": surface_index,
                    "surface_name": str(row.name or ""),
                    "parameter": str(variable.parameter),
                    "name": variable.normalized_name(),
                    "nominal": nominal,
                    "lower": float(variable.lower_bound),
                    "upper": float(variable.upper_bound),
                    "compensator": self._tolerance_variable_compensator_enabled(variable),
                    **(
                        {
                            "coupling_group": str(coupling.get("group", "") or ""),
                            "coupling_sign": int(coupling.get("sign", 1) or 1),
                        }
                        if coupling
                        else {}
                    ),
                    **self._tolerance_manufacturing_record_fields(manufacturing),
                }
            )
        return payload

    def save_tolerance_solve_preset(
        self,
        name: str,
        *,
        sample_count: int | None = None,
        seed: int | None = None,
        compensator_steps: int | None = None,
        multi_steps: int | None = None,
        multi_passes: int | None = None,
        tolerance_compare_view: str | None = None,
    ) -> dict[str, object]:
        active = self._active_tolerance_solve_preset()
        selected_operands, operands = self._current_tolerance_preset_operands()
        compare_view = tolerance_compare_view or self._current_tolerance_compare_view()
        preset = self._normalize_tolerance_solve_preset(
            {
                "name": name,
                "sample_count": sample_count if sample_count is not None else active.get("sample_count", 25),
                "seed": seed if seed is not None else active.get("seed", 12345),
                "compensator_steps": (
                    compensator_steps if compensator_steps is not None else active.get("compensator_steps", 9)
                ),
                "multi_steps": multi_steps if multi_steps is not None else active.get("multi_steps", 5),
                "multi_passes": multi_passes if multi_passes is not None else active.get("multi_passes", 2),
                "tolerance_compare_view": compare_view,
                "selected_operands": selected_operands,
                "operands": operands,
                "compensator_policy": "explicit",
                "coupling_policy": "explicit",
                "manufacturing_policy": "explicit",
                "compensators": self._current_tolerance_compensator_preset_payload(),
            }
        )
        if not preset:
            raise ValueError("Tolerance solve preset name is required.")
        presets = [
            existing
            for existing in self._normalize_tolerance_solve_presets(getattr(self, "tolerance_solve_presets", []))
            if str(existing.get("name", "")) != str(preset.get("name", ""))
        ]
        presets.append(preset)
        self.tolerance_solve_presets = presets
        self.active_tolerance_solve_preset_name = str(preset.get("name", ""))
        return dict(preset)

    def apply_tolerance_solve_preset(self, preset_or_name: str | dict[str, object]) -> dict[str, object]:
        if isinstance(preset_or_name, dict):
            preset = self._normalize_tolerance_solve_preset(preset_or_name)
        else:
            preset = self._tolerance_solve_preset_by_name(str(preset_or_name)) or {}
        if not preset:
            raise ValueError("Tolerance solve preset was not found.")
        self.active_tolerance_solve_preset_name = str(preset.get("name", ""))
        compare_view = str(preset.get("tolerance_compare_view", "") or "").strip()
        if compare_view in TOLERANCE_COMPARE_VIEW_VALUES and "tolerance_compare_view_var" in self.__dict__:
            self.tolerance_compare_view_var.set(compare_view)
        selected_operands = [str(label) for label in list(preset.get("selected_operands", []) or [])]
        self._set_selected_operand_labels(selected_operands)
        operand_settings = preset.get("operands", {})
        if isinstance(operand_settings, dict):
            for label, payload in operand_settings.items():
                if not isinstance(payload, dict):
                    continue
                for key, attr_name in (
                    ("weight", "operand_weight_vars"),
                    ("target", "operand_target_vars"),
                    ("wavelength", "operand_wavelength_vars"),
                    ("field", "operand_field_vars"),
                    ("field_x", "operand_field_x_vars"),
                    ("field_y", "operand_field_y_vars"),
                    ("surface", "operand_surface_vars"),
                    ("aperture_type", "operand_aperture_type_vars"),
                    ("aperture_value", "operand_aperture_value_vars"),
                    ("frequency", "operand_frequency_vars"),
                    ("mtf_mode", "operand_mtf_mode_vars"),
                    ("mtf_algorithm", "operand_mtf_algorithm_vars"),
                ):
                    mapping = getattr(self, attr_name, {}) or {}
                    var = mapping.get(label)
                    if var is not None and key in payload:
                        var.set(str(payload[key]).strip())
        compensator_records = list(preset.get("compensators", []) or [])
        if str(preset.get("compensator_policy", "explicit")) == "explicit" or compensator_records:
            roles: dict[tuple[int, str], bool] = {}
            for record in compensator_records:
                if not isinstance(record, dict):
                    continue
                try:
                    surface_index = int(record.get("surface_index", -1))
                except Exception:
                    continue
                parameter = str(record.get("parameter", "") or "").strip()
                if surface_index < 0 or not parameter:
                    continue
                roles[(surface_index, parameter.lower())] = self._tolerance_preset_bool(
                    record.get("compensator", record.get("enabled", True)),
                    True,
                )
            for surface_index, row in enumerate(self.rows):
                enabled_names: list[str] = []
                touched = False
                for spec in VARIABLE_REGISTRY.values():
                    if not spec.is_supported(row) or not self._variable_enabled_for_row(row, spec):
                        continue
                    key = (surface_index, str(spec.parameter).lower())
                    if key not in roles:
                        continue
                    touched = True
                    if roles[key]:
                        enabled_names.append(str(spec.parameter))
                if touched:
                    row.advanced = dict(row.advanced or {})
                    row.advanced[TOLERANCE_COMPENSATORS_ADVANCED_ATTR] = enabled_names
        if str(preset.get("coupling_policy", "preserve")) == "explicit":
            couplings: dict[tuple[int, str], tuple[str, int]] = {}
            for record in compensator_records:
                if not isinstance(record, dict):
                    continue
                try:
                    surface_index = int(record.get("surface_index", -1))
                except Exception:
                    continue
                parameter = str(record.get("parameter", "") or "").strip()
                if surface_index < 0 or not parameter:
                    continue
                group = str(record.get("coupling_group", "") or "").strip()
                sign = self._tolerance_coupling_sign(record.get("coupling_sign", 1))
                couplings[(surface_index, parameter.lower())] = (group, sign)
            for surface_index, row in enumerate(self.rows):
                row_couplings = self._row_tolerance_couplings(row)
                touched = False
                for spec in VARIABLE_REGISTRY.values():
                    if not spec.is_supported(row) or not self._variable_enabled_for_row(row, spec):
                        continue
                    key = (surface_index, str(spec.parameter).lower())
                    if key not in couplings:
                        continue
                    touched = True
                    for candidate in list(row_couplings):
                        if _native_variable_matches(candidate, spec.parameter):
                            row_couplings.pop(candidate, None)
                    group, sign = couplings[key]
                    if group:
                        row_couplings[str(spec.parameter)] = {"group": group, "sign": sign}
                if touched:
                    row.advanced = dict(row.advanced or {})
                    if row_couplings:
                        row.advanced[TOLERANCE_COUPLING_ADVANCED_ATTR] = row_couplings
                    else:
                        row.advanced.pop(TOLERANCE_COUPLING_ADVANCED_ATTR, None)
        if str(preset.get("manufacturing_policy", "preserve")) == "explicit":
            manufacturing_records: dict[tuple[int, str], dict[str, object]] = {}
            for record in compensator_records:
                if not isinstance(record, dict):
                    continue
                try:
                    surface_index = int(record.get("surface_index", -1))
                except Exception:
                    continue
                parameter = str(record.get("parameter", "") or "").strip()
                if surface_index < 0 or not parameter:
                    continue
                metadata = self._tolerance_manufacturing_record_fields(record)
                manufacturing_records[(surface_index, parameter.lower())] = metadata
            for surface_index, row in enumerate(self.rows):
                row_records = self._normalize_tolerance_manufacturing_payload(
                    (row.advanced or {}).get(TOLERANCE_MANUFACTURING_ADVANCED_ATTR)
                )
                touched = False
                for spec in VARIABLE_REGISTRY.values():
                    if not spec.is_supported(row) or not self._variable_enabled_for_row(row, spec):
                        continue
                    key = (surface_index, str(spec.parameter).lower())
                    if key not in manufacturing_records:
                        continue
                    touched = True
                    for candidate in list(row_records):
                        if _native_variable_matches(candidate, spec.parameter):
                            row_records.pop(candidate, None)
                    metadata = manufacturing_records[key]
                    if metadata:
                        row_records[str(spec.parameter)] = {
                            "source_type": str(metadata.get("manufacturing_source_type", "") or ""),
                            "source_id": str(metadata.get("manufacturing_source_id", "") or ""),
                            "tags": self._tolerance_manufacturing_tags(metadata.get("manufacturing_tags", "")),
                            "note": str(metadata.get("manufacturing_note", "") or ""),
                        }
                if touched:
                    row.advanced = dict(row.advanced or {})
                    if row_records:
                        row.advanced[TOLERANCE_MANUFACTURING_ADVANCED_ATTR] = row_records
                    else:
                        row.advanced.pop(TOLERANCE_MANUFACTURING_ADVANCED_ATTR, None)
        return dict(preset)

    def tolerance_solve_preset_report_text(self, preset: dict[str, object] | None = None) -> str:
        resolved = dict(preset if preset is not None else self._active_tolerance_solve_preset())
        if not resolved:
            return "# KrakenOS Tolerance Solve Preset\n\nNo active preset.\n"
        compensators = list(resolved.get("compensators", []) or [])
        enabled = [record for record in compensators if bool(dict(record).get("compensator", True))]
        lines = [
            "# KrakenOS Tolerance Solve Preset",
            "",
            f"Name: {resolved.get('name', '')}",
            f"Monte Carlo samples: {int(resolved.get('sample_count', 0) or 0)}",
            f"Seed: {int(resolved.get('seed', 0) or 0)}",
            f"Compensator sweep steps: {int(resolved.get('compensator_steps', 0) or 0)}",
            f"Multi-compensator steps/passes: {int(resolved.get('multi_steps', 0) or 0)}/{int(resolved.get('multi_passes', 0) or 0)}",
            f"Tolerance compare view: {resolved.get('tolerance_compare_view', TOLERANCE_COMPARE_VIEW_DEFAULT)}",
            f"Merit operands: {', '.join(str(label) for label in list(resolved.get('selected_operands', []) or [])) or 'default Spot RMS'}",
            f"Compensators: {len(enabled)} enabled / {len(compensators)} marked tolerance variable(s)",
            "",
            "Tolerance variable roles:",
        ]
        if compensators:
            for record in compensators:
                item = dict(record)
                role = "compensator" if bool(item.get("compensator", True)) else "tolerance-only"
                coupling_group = str(item.get("coupling_group", "") or "").strip()
                coupling = ""
                if coupling_group:
                    coupling = " coupling={}{}".format(
                        "-" if int(item.get("coupling_sign", 1) or 1) < 0 else "",
                        coupling_group,
                    )
                manufacturing = self._format_tolerance_manufacturing_inline(item)
                lines.append(f"- S{item.get('surface_index')} {item.get('parameter')}: {role}{coupling}{manufacturing}")
        else:
            lines.append("- none marked at save time")
        return "\n".join(lines).strip() + "\n"

    def open_save_tolerance_solve_preset_dialog(self) -> None:
        self._commit_pending_table_edit()
        try:
            self._read_rows_from_table()
        except Exception as exc:
            messagebox.showerror("Save Tolerance Solve Preset", f"Could not read the surface table:\n\n{exc}", parent=self)
            return
        active = self._active_tolerance_solve_preset()
        default_name = str(active.get("name", "") or "Nominal tolerance solve")
        dialog = tk.Toplevel(self)
        dialog.withdraw()
        dialog.title("Save Tolerance Solve Preset")
        dialog.transient(self)
        dialog.grab_set()
        dialog.resizable(False, False)

        vars_by_key = {
            "name": tk.StringVar(master=dialog, value=default_name),
            "sample_count": tk.StringVar(master=dialog, value=str(active.get("sample_count", 25))),
            "seed": tk.StringVar(master=dialog, value=str(active.get("seed", 12345))),
            "compensator_steps": tk.StringVar(master=dialog, value=str(active.get("compensator_steps", 9))),
            "multi_steps": tk.StringVar(master=dialog, value=str(active.get("multi_steps", 5))),
            "multi_passes": tk.StringVar(master=dialog, value=str(active.get("multi_passes", 2))),
            "tolerance_compare_view": tk.StringVar(
                master=dialog,
                value=str(active.get("tolerance_compare_view", self._current_tolerance_compare_view())),
            ),
        }
        fields = (
            ("Preset name", "name"),
            ("Monte Carlo samples", "sample_count"),
            ("Random seed", "seed"),
            ("Single-compensator steps", "compensator_steps"),
            ("Multi-compensator steps", "multi_steps"),
            ("Multi-compensator passes", "multi_passes"),
        )
        for row_index, (label, key) in enumerate(fields):
            ttk.Label(dialog, text=label).grid(row=row_index, column=0, sticky="w", padx=12, pady=(10 if row_index == 0 else 4, 2))
            ttk.Entry(dialog, textvariable=vars_by_key[key], width=30).grid(
                row=row_index,
                column=1,
                sticky="ew",
                padx=12,
                pady=(10 if row_index == 0 else 4, 2),
            )
        compare_row = len(fields)
        ttk.Label(dialog, text="Tolerance compare view").grid(row=compare_row, column=0, sticky="w", padx=12, pady=(4, 2))
        ttk.Combobox(
            dialog,
            textvariable=vars_by_key["tolerance_compare_view"],
            values=TOLERANCE_COMPARE_VIEW_VALUES,
            state="readonly",
            width=28,
        ).grid(row=compare_row, column=1, sticky="ew", padx=12, pady=(4, 2))
        role_count = len(self._current_tolerance_compensator_preset_payload())
        ttk.Label(
            dialog,
            text=f"Saves merit operands and {role_count} tolerance variable role(s).",
        ).grid(row=compare_row + 1, column=0, columnspan=2, sticky="w", padx=12, pady=(8, 4))

        buttons = ttk.Frame(dialog)
        buttons.grid(row=compare_row + 2, column=0, columnspan=2, sticky="e", padx=12, pady=(8, 12))

        def accept() -> None:
            try:
                self._begin_history_capture()
                preset = self.save_tolerance_solve_preset(
                    vars_by_key["name"].get(),
                    sample_count=int(vars_by_key["sample_count"].get()),
                    seed=int(vars_by_key["seed"].get()),
                    compensator_steps=int(vars_by_key["compensator_steps"].get()),
                    multi_steps=int(vars_by_key["multi_steps"].get()),
                    multi_passes=int(vars_by_key["multi_passes"].get()),
                    tolerance_compare_view=vars_by_key["tolerance_compare_view"].get(),
                )
                self._commit_history_capture()
            except Exception as exc:
                self._history_pending_state = None
                messagebox.showerror("Save Tolerance Solve Preset", str(exc), parent=dialog)
                return
            self.append_debug(self.tolerance_solve_preset_report_text(preset))
            self.status_var.set(f"Saved tolerance solve preset '{preset.get('name')}'. Save layout to persist it.")
            dialog.destroy()

        ttk.Button(buttons, text="Cancel", command=dialog.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(buttons, text="Save Preset", command=accept).pack(side="right")
        dialog.columnconfigure(1, weight=1)
        dialog.update_idletasks()
        self._show_centered_dialog(dialog)
        dialog.wait_window()

    def open_apply_tolerance_solve_preset_dialog(self) -> None:
        presets = self._normalize_tolerance_solve_presets(getattr(self, "tolerance_solve_presets", []))
        if not presets:
            messagebox.showinfo("Apply Tolerance Solve Preset", "No saved tolerance solve presets are available in this layout.", parent=self)
            return
        active = str(getattr(self, "active_tolerance_solve_preset_name", "") or "")
        names = [str(preset.get("name", "")) for preset in presets]
        selected_name = active if active in names else names[0]
        if len(names) == 1:
            try:
                self._begin_history_capture()
                preset = self.apply_tolerance_solve_preset(selected_name)
                self._sync_table()
                self._commit_history_capture()
            except Exception as exc:
                self._history_pending_state = None
                messagebox.showerror("Apply Tolerance Solve Preset", str(exc), parent=self)
                return
            self.append_debug(self.tolerance_solve_preset_report_text(preset))
            self.status_var.set(f"Applied tolerance solve preset '{selected_name}'. Click Update when ready.")
            return

        dialog = tk.Toplevel(self)
        dialog.withdraw()
        dialog.title("Apply Tolerance Solve Preset")
        dialog.transient(self)
        dialog.grab_set()
        dialog.resizable(False, False)
        preset_var = tk.StringVar(master=dialog, value=selected_name)
        ttk.Label(dialog, text="Preset").grid(row=0, column=0, sticky="w", padx=12, pady=(12, 4))
        ttk.Combobox(dialog, textvariable=preset_var, values=names, state="readonly", width=36).grid(
            row=1,
            column=0,
            sticky="ew",
            padx=12,
            pady=(0, 8),
        )
        ttk.Label(
            dialog,
            text="Applies defaults, merit operands, tolerance compare view, and compensator roles without tracing.",
        ).grid(row=2, column=0, sticky="w", padx=12, pady=(0, 8))
        buttons = ttk.Frame(dialog)
        buttons.grid(row=3, column=0, sticky="e", padx=12, pady=(4, 12))

        def accept() -> None:
            selected = preset_var.get().strip()
            try:
                self._begin_history_capture()
                preset = self.apply_tolerance_solve_preset(selected)
                self._sync_table()
                self._commit_history_capture()
            except Exception as exc:
                self._history_pending_state = None
                messagebox.showerror("Apply Tolerance Solve Preset", str(exc), parent=dialog)
                return
            self.append_debug(self.tolerance_solve_preset_report_text(preset))
            self.status_var.set(f"Applied tolerance solve preset '{selected}'. Click Update when ready.")
            dialog.destroy()

        ttk.Button(buttons, text="Cancel", command=dialog.destroy).pack(side="right", padx=(6, 0))
        ttk.Button(buttons, text="Apply Preset", command=accept).pack(side="right")
        dialog.columnconfigure(0, weight=1)
        dialog.update_idletasks()
        self._show_centered_dialog(dialog)
        dialog.wait_window()

    @classmethod
    def _tolerance_compensator_indices_from_records(cls, variable_records: list[dict[str, object]]) -> list[int]:
        if not variable_records:
            return []
        if any("compensator" in record for record in variable_records):
            return [
                index
                for index, record in enumerate(variable_records)
                if bool(record.get("compensator", True))
            ]
        return list(range(len(variable_records)))

    @staticmethod
    def _tolerance_optical_variables_from_records(variable_records: list[dict[str, object]]) -> list[OpticalVariable]:
        variables: list[OpticalVariable] = []
        for record in variable_records:
            surface_index = int(record.get("surface_index", -1))
            parameter = str(record.get("parameter", "") or "")
            if surface_index < 0 or not parameter:
                raise RuntimeError("Tolerance summary contains an invalid variable record.")
            variables.append(
                OpticalVariable(
                    surface_index,
                    parameter,
                    float(record.get("lower", np.nan)),
                    float(record.get("upper", np.nan)),
                    name=str(record.get("name", "") or ""),
                )
            )
        return variables

    def _tolerance_sample_values_from_record(
        self,
        record: dict[str, object],
        variable_records: list[dict[str, object]],
    ) -> list[float]:
        values: list[float] = []
        for variable in variable_records:
            key = self._tolerance_variable_key(variable)
            default = float(variable.get("nominal", np.nan))
            value = self._tolerance_record_float(record, key, default)
            if not np.isfinite(value):
                raise RuntimeError(f"Tolerance sample is missing finite value for {key}.")
            values.append(float(value))
        return values

    def _tolerance_system_for_record(
        self,
        base_system,
        variable_records: list[dict[str, object]],
        record: dict[str, object],
    ):
        variables = self._tolerance_optical_variables_from_records(variable_records)
        values = self._tolerance_sample_values_from_record(record, variable_records)
        evaluator = MeritEvaluator(base_system.SDT, setup=base_system.SETUP, merit_function=MeritFunction([]))
        surfaces = evaluator.apply_variables(variables, values)
        sink = io.StringIO()
        with redirect_stdout(sink), redirect_stderr(sink):
            return Kos.system(surfaces, base_system.SETUP, build=1)

    @staticmethod
    def _tolerance_unique_sweep_values(*value_sets: object) -> list[float]:
        values: dict[float, float] = {}
        for value_set in value_sets:
            arr = np.asarray(value_set, dtype=float).ravel()
            for value in arr:
                if not np.isfinite(value):
                    continue
                values[round(float(value), 12)] = float(value)
        return [values[key] for key in sorted(values)]

    def run_tolerance_compensator_sweep(
        self,
        summary: dict[str, object] | None = None,
        *,
        steps: int = 9,
    ) -> dict[str, object]:
        steps = max(3, min(101, int(steps)))
        context = self._tolerance_nominal_worst_context(summary)
        variable_records = [dict(item) for item in list(context["variable_records"])]
        if not variable_records:
            raise RuntimeError("Tolerance Monte Carlo has no variables to sweep.")
        base_system = context["base_system"]
        variables = self._tolerance_optical_variables_from_records(variable_records)
        compensator_indices = self._tolerance_compensator_indices_from_records(variable_records)
        if not compensator_indices:
            raise RuntimeError("No tolerance compensators are enabled. Add ToleranceCompensators metadata to at least one marked variable.")
        nominal_values = np.asarray(
            self._tolerance_sample_values_from_record(dict(context["nominal_record"]), variable_records),
            dtype=float,
        )
        worst_record = dict(context["worst_record"])
        worst_values = np.asarray(self._tolerance_sample_values_from_record(worst_record, variable_records), dtype=float)
        worst_total = self._tolerance_record_float(worst_record, "total_merit")
        merit_function, operand_labels = self._build_tolerance_merit_function()
        if not merit_function.operands:
            raise RuntimeError("No merit operands are available for tolerance compensator sweep.")
        has_mtf_operand = any(isinstance(operand, MTFAtFrequencyOperand) for operand in merit_function.operands)
        evaluator = MeritEvaluator(
            base_system.SDT,
            setup=base_system.SETUP,
            merit_function=merit_function,
            mtf_worker_count=self._mtf_worker_count(self._current_ray_count()) if has_mtf_operand else 1,
        )

        records: list[dict[str, object]] = []
        for variable_index in compensator_indices:
            variable = variables[variable_index]
            variable_record = variable_records[variable_index]
            lower = float(variable.lower_bound)
            upper = float(variable.upper_bound)
            if not np.isfinite(lower) or not np.isfinite(upper):
                continue
            if lower > upper:
                lower, upper = upper, lower
            if abs(upper - lower) <= 1e-18:
                candidate_values = [float(lower)]
            else:
                candidate_values = self._tolerance_unique_sweep_values(
                    np.linspace(lower, upper, steps),
                    [nominal_values[variable_index], worst_values[variable_index]],
                )
            key = self._tolerance_variable_key(variable_record)
            for step_index, value in enumerate(candidate_values):
                test_values = worst_values.copy()
                test_values[variable_index] = float(value)
                result = evaluator.evaluate(variables, test_values)
                total_merit = float(result.total)
                record: dict[str, object] = {
                    "compensator": variable.normalized_name(),
                    "compensator_key": key,
                    "surface_index": int(variable.surface_index),
                    "parameter": str(variable.parameter),
                    "coupling_group": str(variable_record.get("coupling_group", "") or ""),
                    "coupling_sign": int(variable_record.get("coupling_sign", 1) or 1),
                    "manufacturing_source_type": str(variable_record.get("manufacturing_source_type", "") or ""),
                    "manufacturing_source_id": str(variable_record.get("manufacturing_source_id", "") or ""),
                    "manufacturing_tags": str(variable_record.get("manufacturing_tags", "") or ""),
                    "manufacturing_note": str(variable_record.get("manufacturing_note", "") or ""),
                    "step": int(step_index),
                    "value": float(value),
                    "nominal_value": float(nominal_values[variable_index]),
                    "worst_value": float(worst_values[variable_index]),
                    "lower": lower,
                    "upper": upper,
                    "base_sample": int(context["worst_sample"]),
                    "valid": bool(result.valid),
                    "total_merit": total_merit,
                    "worst_total_merit": worst_total,
                    "delta_vs_worst": total_merit - worst_total if np.isfinite(total_merit) and np.isfinite(worst_total) else np.nan,
                    "improvement_vs_worst": worst_total - total_merit if np.isfinite(total_merit) and np.isfinite(worst_total) else np.nan,
                    "is_nominal_value": abs(float(value) - float(nominal_values[variable_index])) <= 1e-12,
                    "is_worst_value": abs(float(value) - float(worst_values[variable_index])) <= 1e-12,
                    "message": str(result.message),
                }
                for operand in result.operands:
                    operand_key = re.sub(r"[^a-z0-9]+", "_", str(operand.name).strip().lower()).strip("_") or "operand"
                    record[f"{operand_key}_value"] = float(operand.value)
                    record[f"{operand_key}_weighted"] = float(operand.weighted)
                    record[f"{operand_key}_residual"] = float(operand.residual)
                records.append(record)

        valid_records = [record for record in records if bool(record.get("valid"))]
        best_record = min(valid_records, key=lambda record: self._tolerance_record_float(record, "total_merit", np.inf), default=None)
        best_by_compensator: list[dict[str, object]] = []
        for key in sorted({str(record.get("compensator_key", "")) for record in records}):
            candidates = [record for record in valid_records if str(record.get("compensator_key", "")) == key]
            if candidates:
                best_by_compensator.append(min(candidates, key=lambda record: self._tolerance_record_float(record, "total_merit", np.inf)))
        summary_out = {
            "kind": "worst_sample_compensator_sweep",
            "steps": steps,
            "variables": variable_records,
            "operand_labels": operand_labels,
            "records": records,
            "best_by_compensator": best_by_compensator,
            "compensator_count": len(compensator_indices),
            "valid_count": len(valid_records),
            "invalid_count": len(records) - len(valid_records),
            "base_sample": int(context["worst_sample"]),
            "base_total_merit": worst_total,
            "best_compensator": None if best_record is None else dict(best_record),
            "best_total_merit": np.nan if best_record is None else self._tolerance_record_float(best_record, "total_merit"),
            "best_improvement_vs_worst": np.nan if best_record is None else self._tolerance_record_float(best_record, "improvement_vs_worst"),
            "comparison": context["comparison"],
        }
        self._last_tolerance_compensator_records = records
        self._last_tolerance_compensator_summary = summary_out
        return summary_out

    def tolerance_compensator_sweep_report_text(self, summary: dict[str, object] | None = None) -> str:
        summary = dict(summary if summary is not None else self._last_tolerance_compensator_summary)
        if not summary:
            return "# KrakenOS Tolerance Compensator Sweep\n\nNo compensator sweep has been executed.\n"
        best = dict(summary.get("best_compensator", {}) or {})
        lines = [
            "# KrakenOS Tolerance Compensator Sweep",
            "",
            f"Base worst sample: {summary.get('base_sample')}",
            f"Base worst merit: {float(summary.get('base_total_merit', np.nan)):.6g}",
            f"Sweep steps per compensator: {int(summary.get('steps', 0) or 0)} plus nominal/worst values",
            f"Eligible compensators: {int(summary.get('compensator_count', 0) or 0)}",
            f"Valid/invalid evaluations: {int(summary.get('valid_count', 0) or 0)}/{int(summary.get('invalid_count', 0) or 0)}",
            f"Merit operands: {', '.join(str(label) for label in list(summary.get('operand_labels', []) or []))}",
            "",
            "Best compensation:",
        ]
        if best:
            coupling_group = str(best.get("coupling_group", "") or "").strip()
            coupling = ""
            if coupling_group:
                coupling = ", coupling={}{}".format(
                    "-" if int(best.get("coupling_sign", 1) or 1) < 0 else "",
                    coupling_group,
                )
            manufacturing = self._format_tolerance_manufacturing_inline(best)
            lines.append(
                "- {name}: value={value:.6g}, merit={merit:.6g}, improvement={improvement:.6g}{coupling}{manufacturing}".format(
                    name=best.get("compensator", ""),
                    value=float(best.get("value", np.nan)),
                    merit=float(best.get("total_merit", np.nan)),
                    improvement=float(best.get("improvement_vs_worst", np.nan)),
                    coupling=coupling,
                    manufacturing=manufacturing,
                )
            )
        else:
            lines.append("- none")
        lines.extend(["", "Best per compensator:"])
        for record in list(summary.get("best_by_compensator", []) or []):
            coupling_group = str(record.get("coupling_group", "") or "").strip()
            coupling = ""
            if coupling_group:
                coupling = ", coupling={}{}".format(
                    "-" if int(record.get("coupling_sign", 1) or 1) < 0 else "",
                    coupling_group,
                )
            manufacturing = self._format_tolerance_manufacturing_inline(record)
            lines.append(
                "- {name}: value={value:.6g}, merit={merit:.6g}, improvement={improvement:.6g}{coupling}{manufacturing}".format(
                    name=record.get("compensator", ""),
                    value=float(record.get("value", np.nan)),
                    merit=float(record.get("total_merit", np.nan)),
                    improvement=float(record.get("improvement_vs_worst", np.nan)),
                    coupling=coupling,
                    manufacturing=manufacturing,
                )
            )
        return "\n".join(lines).strip() + "\n"

    def tolerance_compensator_csv_rows(
        self,
        summary: dict[str, object] | None = None,
    ) -> tuple[list[str], list[dict[str, object]]]:
        summary = dict(summary if summary is not None else self._last_tolerance_compensator_summary)
        rows = [dict(record) for record in list(summary.get("records", []) or [])]
        columns: list[str] = []
        for preferred in (
            "compensator",
            "compensator_key",
            "surface_index",
            "parameter",
            "coupling_group",
            "coupling_sign",
            "manufacturing_source_type",
            "manufacturing_source_id",
            "manufacturing_tags",
            "manufacturing_note",
            "step",
            "value",
            "nominal_value",
            "worst_value",
            "lower",
            "upper",
            "base_sample",
            "valid",
            "total_merit",
            "worst_total_merit",
            "delta_vs_worst",
            "improvement_vs_worst",
            "is_nominal_value",
            "is_worst_value",
            "message",
        ):
            if any(preferred in row for row in rows):
                columns.append(preferred)
        for row in rows:
            for key in row:
                if key not in columns:
                    columns.append(str(key))
        return columns, rows

    def run_tolerance_multi_compensator_solve(
        self,
        summary: dict[str, object] | None = None,
        *,
        steps: int = 5,
        passes: int = 2,
    ) -> dict[str, object]:
        steps = max(3, min(51, int(steps)))
        passes = max(1, min(20, int(passes)))
        context = self._tolerance_nominal_worst_context(summary)
        variable_records = [dict(item) for item in list(context["variable_records"])]
        if not variable_records:
            raise RuntimeError("Tolerance Monte Carlo has no variables to solve.")
        base_system = context["base_system"]
        variables = self._tolerance_optical_variables_from_records(variable_records)
        compensator_indices = self._tolerance_compensator_indices_from_records(variable_records)
        if not compensator_indices:
            raise RuntimeError("No tolerance compensators are enabled. Add ToleranceCompensators metadata to at least one marked variable.")
        nominal_values = np.asarray(
            self._tolerance_sample_values_from_record(dict(context["nominal_record"]), variable_records),
            dtype=float,
        )
        worst_record = dict(context["worst_record"])
        worst_values = np.asarray(self._tolerance_sample_values_from_record(worst_record, variable_records), dtype=float)
        base_total = self._tolerance_record_float(worst_record, "total_merit")
        merit_function, operand_labels = self._build_tolerance_merit_function()
        if not merit_function.operands:
            raise RuntimeError("No merit operands are available for tolerance multi-compensator solve.")
        has_mtf_operand = any(isinstance(operand, MTFAtFrequencyOperand) for operand in merit_function.operands)
        evaluator = MeritEvaluator(
            base_system.SDT,
            setup=base_system.SETUP,
            merit_function=merit_function,
            mtf_worker_count=self._mtf_worker_count(self._current_ray_count()) if has_mtf_operand else 1,
        )

        current_values = worst_values.copy()
        current_result = evaluator.evaluate(variables, current_values)
        current_total = float(current_result.total)
        records: list[dict[str, object]] = []
        accepted_records: list[dict[str, object]] = []
        pass_summaries: list[dict[str, object]] = []

        for pass_index in range(1, passes + 1):
            pass_start_total = float(current_total)
            improved_this_pass = False
            accepted_this_pass = 0
            for variable_index in compensator_indices:
                variable = variables[variable_index]
                variable_record = variable_records[variable_index]
                lower = float(variable.lower_bound)
                upper = float(variable.upper_bound)
                if not np.isfinite(lower) or not np.isfinite(upper):
                    continue
                if lower > upper:
                    lower, upper = upper, lower
                if abs(upper - lower) <= 1e-18:
                    candidate_values = [float(lower)]
                else:
                    candidate_values = self._tolerance_unique_sweep_values(
                        np.linspace(lower, upper, steps),
                        [nominal_values[variable_index], worst_values[variable_index], current_values[variable_index]],
                    )
                key = self._tolerance_variable_key(variable_record)
                previous_value = float(current_values[variable_index])
                best_record: dict[str, object] | None = None
                best_values = current_values.copy()
                best_total = float(current_total)
                for step_index, value in enumerate(candidate_values):
                    test_values = current_values.copy()
                    test_values[variable_index] = float(value)
                    result = evaluator.evaluate(variables, test_values)
                    total_merit = float(result.total)
                    record: dict[str, object] = {
                        "pass": int(pass_index),
                        "compensator": variable.normalized_name(),
                        "compensator_key": key,
                        "surface_index": int(variable.surface_index),
                        "parameter": str(variable.parameter),
                        "coupling_group": str(variable_record.get("coupling_group", "") or ""),
                        "coupling_sign": int(variable_record.get("coupling_sign", 1) or 1),
                        "manufacturing_source_type": str(variable_record.get("manufacturing_source_type", "") or ""),
                        "manufacturing_source_id": str(variable_record.get("manufacturing_source_id", "") or ""),
                        "manufacturing_tags": str(variable_record.get("manufacturing_tags", "") or ""),
                        "manufacturing_note": str(variable_record.get("manufacturing_note", "") or ""),
                        "step": int(step_index),
                        "value": float(value),
                        "previous_value": previous_value,
                        "nominal_value": float(nominal_values[variable_index]),
                        "worst_value": float(worst_values[variable_index]),
                        "lower": lower,
                        "upper": upper,
                        "base_sample": int(context["worst_sample"]),
                        "valid": bool(result.valid),
                        "accepted": False,
                        "total_merit": total_merit,
                        "previous_total_merit": float(current_total),
                        "base_total_merit": base_total,
                        "delta_vs_previous": total_merit - current_total if np.isfinite(total_merit) and np.isfinite(current_total) else np.nan,
                        "improvement_vs_previous": current_total - total_merit if np.isfinite(total_merit) and np.isfinite(current_total) else np.nan,
                        "improvement_vs_worst": base_total - total_merit if np.isfinite(total_merit) and np.isfinite(base_total) else np.nan,
                        "is_nominal_value": abs(float(value) - float(nominal_values[variable_index])) <= 1e-12,
                        "is_worst_value": abs(float(value) - float(worst_values[variable_index])) <= 1e-12,
                        "message": str(result.message),
                    }
                    for value_index, solve_variable in enumerate(variables):
                        record[f"solve_s{int(solve_variable.surface_index)}_{str(solve_variable.parameter).lower()}"] = float(test_values[value_index])
                    for operand in result.operands:
                        operand_key = re.sub(r"[^a-z0-9]+", "_", str(operand.name).strip().lower()).strip("_") or "operand"
                        record[f"{operand_key}_value"] = float(operand.value)
                        record[f"{operand_key}_weighted"] = float(operand.weighted)
                        record[f"{operand_key}_residual"] = float(operand.residual)
                    records.append(record)
                    if bool(result.valid) and total_merit < best_total - 1e-12:
                        best_total = total_merit
                        best_values = test_values
                        best_record = record
                if best_record is not None:
                    best_record["accepted"] = True
                    accepted_records.append(dict(best_record))
                    current_values = best_values
                    current_total = best_total
                    improved_this_pass = True
                    accepted_this_pass += 1
            pass_summaries.append(
                {
                    "pass": int(pass_index),
                    "start_total_merit": pass_start_total,
                    "end_total_merit": float(current_total),
                    "improvement": pass_start_total - float(current_total) if np.isfinite(pass_start_total) and np.isfinite(current_total) else np.nan,
                    "accepted_steps": accepted_this_pass,
                }
            )
            if not improved_this_pass:
                break

        solved_variables = []
        for index, (variable, variable_record) in enumerate(zip(variables, variable_records)):
            solved_variables.append(
                {
                    "name": variable.normalized_name(),
                    "key": self._tolerance_variable_key(variable_record),
                    "compensator": bool(index in compensator_indices),
                    "surface_index": int(variable.surface_index),
                    "parameter": str(variable.parameter),
                    "coupling_group": str(variable_record.get("coupling_group", "") or ""),
                    "coupling_sign": int(variable_record.get("coupling_sign", 1) or 1),
                    "manufacturing_source_type": str(variable_record.get("manufacturing_source_type", "") or ""),
                    "manufacturing_source_id": str(variable_record.get("manufacturing_source_id", "") or ""),
                    "manufacturing_tags": str(variable_record.get("manufacturing_tags", "") or ""),
                    "manufacturing_note": str(variable_record.get("manufacturing_note", "") or ""),
                    "nominal": float(nominal_values[index]),
                    "worst": float(worst_values[index]),
                    "solved": float(current_values[index]),
                    "delta_vs_worst": float(current_values[index] - worst_values[index]),
                    "delta_vs_nominal": float(current_values[index] - nominal_values[index]),
                    "lower": float(variable.lower_bound),
                    "upper": float(variable.upper_bound),
                }
            )
        summary_out = {
            "kind": "worst_sample_multi_compensator_solve",
            "steps": steps,
            "passes_requested": passes,
            "passes_completed": len(pass_summaries),
            "variables": variable_records,
            "operand_labels": operand_labels,
            "records": records,
            "accepted_records": accepted_records,
            "pass_summaries": pass_summaries,
            "solved_variables": solved_variables,
            "compensator_count": len(compensator_indices),
            "valid_count": len([record for record in records if bool(record.get("valid"))]),
            "invalid_count": len([record for record in records if not bool(record.get("valid"))]),
            "base_sample": int(context["worst_sample"]),
            "base_total_merit": base_total,
            "final_total_merit": float(current_total),
            "improvement_vs_worst": base_total - float(current_total) if np.isfinite(base_total) and np.isfinite(current_total) else np.nan,
            "comparison": context["comparison"],
        }
        self._last_tolerance_multi_compensator_records = records
        self._last_tolerance_multi_compensator_summary = summary_out
        return summary_out

    def tolerance_multi_compensator_report_text(self, summary: dict[str, object] | None = None) -> str:
        summary = dict(summary if summary is not None else self._last_tolerance_multi_compensator_summary)
        if not summary:
            return "# KrakenOS Tolerance Multi-Compensator Solve\n\nNo multi-compensator solve has been executed.\n"
        lines = [
            "# KrakenOS Tolerance Multi-Compensator Solve",
            "",
            f"Base worst sample: {summary.get('base_sample')}",
            f"Base worst merit: {float(summary.get('base_total_merit', np.nan)):.6g}",
            f"Final merit: {float(summary.get('final_total_merit', np.nan)):.6g}",
            f"Improvement vs worst: {float(summary.get('improvement_vs_worst', np.nan)):.6g}",
            f"Passes completed/requested: {int(summary.get('passes_completed', 0) or 0)}/{int(summary.get('passes_requested', 0) or 0)}",
            f"Sweep steps per variable: {int(summary.get('steps', 0) or 0)} plus nominal/current/worst values",
            f"Eligible compensators: {int(summary.get('compensator_count', 0) or 0)}",
            f"Accepted steps: {len(list(summary.get('accepted_records', []) or []))}",
            f"Valid/invalid evaluations: {int(summary.get('valid_count', 0) or 0)}/{int(summary.get('invalid_count', 0) or 0)}",
            f"Merit operands: {', '.join(str(label) for label in list(summary.get('operand_labels', []) or []))}",
            "",
            "Solved compensator values:",
        ]
        for record in list(summary.get("solved_variables", []) or []):
            role = "compensator" if bool(record.get("compensator", True)) else "held tolerance"
            coupling_group = str(record.get("coupling_group", "") or "").strip()
            coupling = ""
            if coupling_group:
                coupling = ", coupling={}{}".format(
                    "-" if int(record.get("coupling_sign", 1) or 1) < 0 else "",
                    coupling_group,
                )
            manufacturing = self._format_tolerance_manufacturing_inline(record)
            lines.append(
                "- {name}: worst={worst:.6g}, solved={solved:.6g}, nominal={nominal:.6g}, role={role}{coupling}{manufacturing}".format(
                    name=record.get("name", ""),
                    worst=float(record.get("worst", np.nan)),
                    solved=float(record.get("solved", np.nan)),
                    nominal=float(record.get("nominal", np.nan)),
                    role=role,
                    coupling=coupling,
                    manufacturing=manufacturing,
                )
            )
        lines.extend(["", "Accepted coordinate steps:"])
        accepted = list(summary.get("accepted_records", []) or [])
        if accepted:
            for record in accepted[:12]:
                lines.append(
                    "- pass {pass_no} {name}: {previous:.6g} -> {value:.6g}, merit {old:.6g} -> {new:.6g}".format(
                        pass_no=int(record.get("pass", 0) or 0),
                        name=record.get("compensator", ""),
                        previous=float(record.get("previous_value", np.nan)),
                        value=float(record.get("value", np.nan)),
                        old=float(record.get("previous_total_merit", np.nan)),
                        new=float(record.get("total_merit", np.nan)),
                    )
                )
        else:
            lines.append("- none")
        return "\n".join(lines).strip() + "\n"

